  str_skill_href_desc_name_30054 = "จิตจรัสแสง",
  str_skill_href_desc_desc_30054 = "ได้รับ <color=#00F6FF>2</color> แต้มเมื่อเข้าสู่การต่อสู้ และ <color=#00F6FF>1</color> แต้มเมื่อเริ่มแต่ละรอบ สูงสุด <color=#00F6FF>6</color> แต้ม",
  str_skill_href_desc_name_30055 = "แต้มเหยื่อล่อ",
