  str_skill_name_590028103 = "กางเขนแห่งความมืด",
  str_skill_desc_590028103 = "ดาร์กซัมมอนเนอร์ทำดาเมจใส่เป้าหมายเป็นพื้นที่รูปบวกไปจนสุดสนามรบ",
  str_skill_name_590028104 = "เรียกดวงไฟพลังงาน",
  str_skill_desc_590028104 = "ดาร์กซัมมอนเนอร์เรียกดวงไฟพลังงาน 2 ดวงให้ปรากฏรอบตัว จากนั้นฟื้นฟูพลังชีวิตให้กับดวงไฟพลังงานทุกดวง",
  str_skill_name_590028105 = "เรียกดวงไฟพลังงาน",
  str_skill_desc_590028105 = "ดาร์กซัมมอนเนอร์เรียกดวงไฟพลังงาน 3 ดวงให้ปรากฏรอบตัว จากนั้นฟื้นฟูพลังชีวิตให้กับดวงไฟพลังงานทุกดวง",
  str_skill_name_590028106 = "เก็บพลังงาน I",
  str_skill_desc_590028106 = "ดาร์กซัมมอนเนอร์รวบรวมพลังงานเพื่อจู่โจมเป็นวงกว้าง ยิ่งมีดวงไฟพลังงานมากเท่าไหร่ ระยะจู่โจมก็จะยิ่งกว้างขึ้น",
  str_skill_name_590028107 = "เก็บพลังงาน II",
  str_skill_desc_590028107 = "ดาร์กซัมมอนเนอร์เทเลพอร์ตไปหาเป้าหมายและรวบรวมพลังงานเพื่อจู่โจมเป็นวงกว้าง ยิ่งมีดวงไฟพลังงานมากเท่าไหร่ ระยะจู่โจมก็จะยิ่งกว้างขึ้น",
  str_skill_name_590028108 = "หยุดสรรพเสียง",
  str_skill_desc_590028108 = "ดาร์กซัมมอนเนอร์จุดระเบิดวงพลังงานที่ชาร์จพลังเอาไว้ ทำดาเมจเป็นพื้นที่เล็ก ๆ",
  str_skill_name_590028109 = "ความเงียบสงัด",
  str_skill_desc_590028109 = "ดาร์กซัมมอนเนอร์จุดระเบิดวงพลังงานที่ชาร์จพลังเอาไว้ ทำดาเมจเป็นพื้นที่กว้าง",
  str_skill_name_590028110 = "ไร้ตัวตน",
  str_skill_desc_590028110 = "ดาร์กซัมมอนเนอร์จุดระเบิดวงพลังงานที่ชาร์จพลังเอาไว้ ทำดาเมจทั้งสนามรบ",
  str_skill_desc_510001 = "ใช้กรงเล็บจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510002 = "ใช้เฮดบัตต์จู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510003 = "ใช้กำปั้นทุบเป้าหมายในระยะโจมตี",
  str_skill_desc_511003 = "ใช้กำปั้นทุบเป้าหมายในระยะโจมตี ทำดาเมจใส่ศัตรูที่อยู่รอบ ๆ และสตันศัตรูเหล่านั้นในรอบถัดไป",
  str_skill_desc_510004 = "โจมตีระยะไกลใส่เป้าหมายที่อยู่แถวเดียวกันในแนวนอนหรือแนวตั้งที่อยู่ในระยะโจมตี",
  str_skill_desc_510005 = "ใช้เขี้ยวกัดเป้าหมายในระยะโจมตี",
  str_skill_desc_510006 = "เรียกโพรเบอร์มาต่อสู้ทุกรอบ",
  str_skill_desc_510007 = "เรียกเดรตเชอร์มาต่อสู้ทุกรอบ จนมีเดรตเชอร์ 5 ตัวในสนามรบ",
  str_skill_desc_5100061 = "เรียกดาร์กวอสปสู่สนามรบทุกรอบ",
  str_skill_desc_5100062 = "เรียกเดรดเบลดมาต่อสู้ทุกรอบ",
  str_skill_desc_5100063 = "เรียกสแลชเชอร์มาที่สนามรบในแต่ละรอบ",
  str_skill_desc_5100064 = "อัญเชิญ Vinesmarks เข้าสู่การต่อสู้ในแต่ละรอบ",
  str_skill_desc_5100071 = "อัญเชิญอิคลิพไซท์สู่สนามรบทุกรอบ",
  str_skill_desc_1000071 = "เรียก Burstbugs เข้าสู่สนามรบทุกรอบ",
  str_skill_desc_510008 = "เรียกพลหอกลูโมมาต่อสู้ทุกรอบ",
  str_skill_desc_510009 = "ดาร์กวอสป์ใช้เหล็กในจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510010 = "เดรดเบลดใช้ดาบจู่โจมเป้าหมายในระยะโจมตี 2 ครั้ง",
  str_skill_desc_29203121 = "ออเจียนใช้ดาบจู่โจมเป้าหมายในระยะโจมตี 2 ครั้ง มอบสถานะเลือดออก",
  str_skill_desc_29203123 = "ออเจียนใช้ดาบจู่โจมเป้าหมายในระยะโจมตี 2 ครั้ง มอบสถานะเลือดออกและเหนื่อย",
  str_skill_desc_510011 = "คูเรียร์ใช้ดาบพิเศษจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510012 = "กางบาเรีย สามารถป้องกันการโจมตีได้ 3 ครั้ง",
  str_skill_desc_510013 = "ใช้เลเซอร์โจมตีเป้าหมายที่อยู่ห่างออกไป 1 ช่อง",
  str_skill_desc_510014 = "จู่โจมเป้าหมายในระยะโจมตี จากนั้นเทเลพอร์ตไปยังตำแหน่งใดก็ได้ในสนามรบ",
  str_skill_desc_510015 = "ใช้หอกจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510016 = "ใช้โล่ขนาดใหญ่จู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510017 = "โจมตีระยะไกลใส่เป้าหมายที่อยู่แถวเดียวกันในแนวนอนหรือแนวตั้งที่อยู่ในระยะโจมตี",
  str_skill_desc_510018 = "ทำดาเมจใส่เป้าหมายใน 4 ทิศทางระยะ 1 ช่อง และผลักเป้าหมายที่โดนโจมตีให้กระเด็นถอยหลัง 1 ช่อง",
  str_skill_desc_510019 = "ทำดาเมจให้กับพื้นที่ด้านหน้าเป็นวงกว้าง",
  str_skill_desc_510020 = "ทำดาเมจในระยะโจมตี",
  str_skill_desc_510021 = "ทำดาเมจใส่ 3 แถวแนวตั้งทางด้านหน้า และผลักศัตรูที่โดนโจมตีให้ถอยกระเด็น",
  str_skill_desc_510022 = "เรียกพลังความมืดมาคุ้มครอง สถานะความมืด 1 สแต็กสามารถป้องกันดาเมจได้ 1 ครั้ง",
  str_skill_desc_510023 = "ทำดาเมจธาตุไฟใส่เป้าหมายในระยะโจมตี",
  str_skill_desc_510024 = "ยิงกระสุนในแนวเส้นตรงเพื่อผลักเป้าหมายให้กระเด็นถอยหลัง",
  str_skill_desc_510025 = "การแตะที่อุปกรณ์ควบคุมจะเป็นการยิงลูกศรไปยังทิศที่หอหน้าไม้เล็งอยู่ ทำดาเมจใส่เป้าหมายที่โดนยิง",
  str_skill_desc_510026 = "วานี่ใช้พลังงานจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี",
  str_skill_desc_510027 = "วานี่ใช้พลังงานเพื่อฟื้นฟูพลังชีวิตของฟิเล็กซ์",
  str_skill_desc_510028 = "ฟิเล็กซ์ใช้ระบบป้องกันติดอาวุธเพื่อโจมตีเป้าหมายในระยะโจมตี",
  str_skill_desc_510029 = "ฟิเล็กซ์ผสานพลังงานเข้าไปในระบบป้องกันติดอาวุธแล้วฟาดใส่พื้น ทำดาเมจใส่เป้าหมายในระยะโจมตี และทำให้เป้าหมายสตัน",
  str_skill_desc_510030 = "วอร์มองเกอร์ใช้กำปั้นฟาดพื้น ทำดาเมจใส่เป้าหมายในระยะโจมตี และทำให้เป้าหมายสตัน",
  str_skill_desc_510031 = "ทำดาเมจใส่เป้าหมายในวงรอบตัว 1 ชั้น เป็นจำนวน 1 ครั้งทุก ๆ 2 รอบ",
  str_skill_desc_510032 = "วางหนามสไปค์เพสต์บนช่องที่เดินผ่าน หนามจะทำดาเมจใส่ผู้ที่เดินไปเหยียบ",
  str_skill_desc_510033 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี และผลักเป้าหมายให้กระเด็นถอยหลัง",
  str_skill_desc_510034 = "โจมตีเป้าหมายในระยะโจมตี 1 ครั้ง",
  str_skill_desc_510035 = "บอร์ดอมรวบรวมพลังเพื่อใช้ท่าจู่โจมธาตุไฟเป็นพื้นที่รูปบวก ทำดาเมจใส่เป้าหมายและทำให้เกิดสถานะเผาไหม้ บอร์ดอมจะไม่มีทางโดนขัดจังหวะขณะรวมพลัง",
  str_skill_desc_510036 = "บอร์ดอมดูดพลังงานจากช่องซึ่งมีธาตุเหมือนตัวเองในวงรอบตัว 1 ชั้น จากนั้นโจมตีเป้าหมายในระยะรอบตัว (ยิ่งดูดพลังงานได้มากเท่าใดก็จะยิ่งทำดาเมจแรงขึ้น) และทำให้เกิดสถานะเผาไหม้",
  str_skill_desc_510037 = "บอร์ดอมรวบรวมพลังเพื่อใช้ท่าจู่โจมธาตุสายฟ้าเป็นพื้นที่รูปบวก ทำดาเมจใส่เป้าหมายและทำให้เกิดสถานะอัมพาต บอร์ดอมจะไม่มีทางโดนขัดจังหวะขณะรวมพลัง",
  str_skill_desc_510038 = "บอร์ดอมดูดพลังงานจากช่องซึ่งมีธาตุเหมือนตัวเองในวงรอบตัว 1 ชั้น จากนั้นโจมตีเป้าหมายในระยะรอบตัว (ยิ่งดูดพลังงานได้มากเท่าใดก็จะยิ่งทำดาเมจแรงขึ้น) และทำให้เกิดสถานะอัมพาต",
  str_skill_desc_500039 = "เชลต์ใช้หางขนาดใหญ่ของมันโจมตีเป้าหมายภายในระยะโจมตี ทำดาเมจ 2 ครั้ง",
  str_skill_desc_500040 = "ไชร์ใช้หางขนาดใหญ่ของมันรวบรวมหนามพลังงานเพื่อโจมตีเป้าหมายในระยะโจมตี ทำดาเมจ 2 ครั้ง",
  str_skill_desc_510039 = "เชลต์ใช้หางอันแข็งแกร่งจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510040 = "ไชร์ใช้หนามพลังงานจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี",
  str_skill_desc_510041 = "การแตะที่อุปกรณ์ควบคุมจะเป็นการยิงลูกศรพิษไปยังทิศที่หอหน้าไม้เล็งอยู่ ทำดาเมจใส่เป้าหมายและทำให้เป้าหมายเกิดสถานะพิษ",
  str_skill_desc_510042 = "การแตะที่อุปกรณ์ควบคุมจะเป็นการยิงลูกศรอัมพาตไปยังทิศที่หอหน้าไม้เล็งอยู่ ออโรเรียนที่ถูกยิงจะเกิดสถานะอัมพาต ส่งผลให้เคลื่อนที่ได้เพียง 1 ช่องเท่านั้นในรอบถัดไป",
  str_skill_desc_510043 = "ไซโลมิสไซล์ที่บรรจุระเบิดเดธไรเดอร์ 1 ลูก",
  str_skill_desc_510044 = "ทาบาอัดใช้กรงเล็บจู่โจมเป้าหมายในระยะโจมตี",
  str_skill_desc_510045 = "ทำดาเมจใส่เป้าหมายทั้งหมดหนึ่งครั้ง",
  str_skill_desc_510046 = "ไอเทมเวทมนตร์ที่ยูนิเมตสร้างขึ้น ซึ่งจะทำงานเมื่อเดินผ่าน สามารถเพิ่ม ATK ของออโรเรียนทุกคนเท่ากับ 10% ของ ATK ของยูนิเมต",
  str_skill_desc_510047 = "ไอเท็มเวทมนตร์ที่ยูนิเมตสร้างขึ้น ซึ่งจะทำงานเมื่อเดินผ่าน สามารถเพิ่ม DEF ของทีมเท่ากับ 10% ของ DEF ของยูนิเมต",
  str_skill_desc_80001 = "คริสตัลสายฟ้าฟาดที่ยูนิเมตจำลองขึ้นมา ซึ่งจะทำงานเมื่อเดินผ่าน สามารถปลดปล่อยสายฟ้าใส่ศัตรูทุกตัว ทำดาเมจเท่ากับ 50% ของดาเมจที่ยูนิเมตทำได้",
  str_skill_desc_80002 = "คริสตัลอุกกาบาตที่ยูนิเมตจำลองขึ้นมา ซึ่งจะทำงานเมื่อเดินผ่าน สามารถเรียกอุกกาบาตใส่ศัตรูที่มี HP มากที่สุด ทำดาเมจเท่ากับ 100% ของดาเมจที่ยูนิเมตทำได้",
  str_skill_desc_80003 = "ไอเทมเวทมนตร์ที่ยูนิเมตสร้างขึ้น ซึ่งจะทำงานเมื่อเดินผ่าน สามารถฟื้นฟู HP ของออโรเรียนทุกคนเท่ากับ 100% ของ ATK ของยูนิเมต",
  str_skill_desc_510048 = "ฟื้นฟูพลังชีวิตเท่ากับ 20% ของ Max HP",
  str_skill_desc_5100482 = "ฟื้นฟู HP สูงสุด 10%",
  str_skill_desc_510049 = "รอบสกิลของออโรเรียนทุกคนที่ลงสนามรบจะ -1",
  str_skill_desc_510050 = "ผลักกระเด็นถอยหลังได้ และจะระเบิดเมื่อผลักไปโดนเป้าหมายหรือบาเรีย ทำดาเมจเป็นวงรอบตัว 1 ชั้น โดยมีศูนย์กลางเป็นจุดกระทบ",
  str_skill_desc_510051 = "ก้อนหินแข็งที่ตั้งอยู่ตามสนามรบไม่สามารถทำลายได้ ใช้ป้องกันการโจมตีระยะไกลของอาวุธยิงได้",
  str_skill_desc_510052 = "กองหินธรรมดา ทำลายได้โดยใช้สกิลที่สร้างดาเมจเป็นพื้นที่",
  str_skill_desc_510053 = "สวิตช์สำหรับเปิดหีบ เหยียบสวิตช์ให้ครบ 3 จุดเพื่อเปิดหีบที่อยู่ตรงกลาง",
  str_skill_desc_510054 = "หีบสมบัติจากเมืองหลวงเก่าที่บรรจุสิ่งของเอาไว้มากมาย เหยียบสวิตช์ให้ครบทั้ง 3 จุดรอบหีบดังกล่าวเพื่อเปิดหีบและรับสมบัติมากมาย",
  str_skill_desc_500216 = "โบว์ลิงเกอร์เข้าสู่สถานะชาร์จในรอบถัดไป ถ้าอิคลิพไซท์ตรงกลางโดนโจมตีด้วยระเบิดเดธไรเดอร์ขณะอยู่ในสถานะชาร์จ โบว์ลิงเกอร์จะเกิดสถานะอัมพาต 1 รอบ",
  str_skill_desc_510216 = "โบว์ลิงเกอร์ปล่อยระเบิดเดธไรเดอร์และเข้าสู่สถานะชาร์จ ถ้าอิคลิพไซท์ตรงกลางโดนโจมตีด้วยระเบิดเดธไรเดอร์ขณะอยู่ในสถานะชาร์จ โบว์ลิงเกอร์จะเกิดสถานะอัมพาต 1 รอบ",
  str_skill_desc_500217 = "โบว์ลิงเกอร์ยิงระเบิดทำลายล้างโจมตีพื้นที่ขนาด 2x2 ช่องเป็นจำนวน 6 ตำแหน่งทั่วกระดาน Alchemy และทำดาเมจใส่เป้าหมายทั้งหมดในระยะระเบิด (ถ้าอิคลิพไซท์ตรงกลางโดนโจมตีด้วยระเบิดเดธไรเดอร์ โบว์ลิงเกอร์จะเกิดสถานะอัมพาต)",
  str_skill_desc_500218 = "โบว์ลิงเกอร์ปลดปล่อยพลังงานที่ชาร์จไว้เพื่อทำดาเมจใส่ศัตรูทุกตัวและ\nผลักกระเด็นถอยหลัง",
  str_skill_name_510219 = "สับสน",
  str_skill_desc_510219 = "โจมตีเป้าหมายในระยะโจมตี 1 ครั้ง และเพิ่มเวลาคูลดาวน์สกิลใช้งานของออโรเรียนทุกคน 1 รอบ",
  str_skill_name_510220 = "พุ่งตัวจู่โจม",
  str_skill_desc_510220 = "กระโดดพุ่งตัวไปโจมตีเป้าหมายในระยะโจมตี 1 ครั้ง",
  str_skill_name_510221 = "พันธนาการลูมินา",
  str_skill_desc_510221 = "กักขังพลังลูมินา ล็อกช่องรอบตัว 1 ชั้น ช่องที่ถูกล็อกจะเปลี่ยนสีไม่ได้",
  str_skill_name_510222 = "ซุ่มยิง",
  str_skill_desc_510222 = "จู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี 1 ครั้ง ยิ่งเป้าหมายอยู่ห่างจากเถาวัลย์เท่าใดก็จะยิ่งได้รับดาเมจแรงขึ้นเท่านั้น",
  str_skill_name_510223 = "กรงเล็บอันร้ายกาจ",
  str_skill_desc_510223 = "โจมตีเป้าหมายในระยะโจมตี 1 ครั้ง",
  str_skill_name_510224 = "ถอนราก",
  str_skill_desc_510224 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี และทุบช่องทั้งหมดภายในระยะ",
  str_skill_name_510225 = "ความเกลียดชัง",
  str_skill_desc_510225 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี เป้าหมายที่ถูกโจมตีจะเกลียดชังออโรเรียนธาตุเดียวกันรอบตัวที่ไม่ใช่กัปตัน ออโรเรียนที่ถูกเกลียดชังไม่สามารถจัดลงสนามรบหรือใช้สกิลใช้งานได้ เมื่อภูตต้องสาปพ่ายแพ้ เอฟเฟกต์ความเกลียดชังนี้จะถูกลบออกจากออโรเรียนธาตุเดียวกัน",
  str_skill_name_510226 = "เพลิงวิญญาณ",
  str_skill_desc_510226 = "จู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี 1 ครั้ง",
  str_skill_name_510227 = "หนวดรัดพัน",
  str_skill_desc_510227 = "พุ่งจู่โจมเป้าหมายและกระแทกเป้าหมายไปยังตำแหน่งใกล้เคียง เปลี่ยนตำแหน่งและเปลี่ยนสีช่องทุกช่องในวงรอบตัว 2 ชั้น",
  str_skill_name_510228 = "แสงอันเจิดจ้า",
  str_skill_desc_510228 = "ทำดาเมจรุนแรงกับเป้าหมายในระยะโจมตี",
  str_skill_name_510229 = "แสงอันสงบนิ่ง",
  str_skill_desc_510229 = "ทำดาเมจอย่างมากกับเป้าหมายในระยะโจมตี แล้วเปลี่ยนสีทุกช่อง\nในวง 1 ชั้นรอบเป้าหมายที่โดนโจมตี",
  str_skill_name_1001811 = "เพิลนาลูน",
  str_skill_desc_1001811 = "คาราคาลูนกลายเป็นเพิลนาลูน ทำดาเมจกับเป้าหมายที่อยู่ในระยะ และล็อกช่องที่อยู่ตรงกลางระยะโจมตี",
  str_skill_name_1001821 = "อิแพกต์",
  str_skill_desc_1001821 = "พลังงานของคาราคาลูนเปี่ยมล้น ทำดาเมจในพื้นที่ 4 แถวแนวตั้งและแนวนอน และสุ่มล็อก 8 ช่องที่อยู่ภายในระยะโจมตี",
  str_skill_name_1001831 = "ลูเมน",
  str_skill_desc_1001831 = "คาราคาลูนกลายเป็นเพิลนาลูน ทำดาเมจกับเป้าหมายที่อยู่ในพื้นที่การโจมตี จากนั้นย้ายไปที่อีกฝั่งหนึ่งของกระดาน แล้วล็อกช่องในวงรอบตัว 2 ชั้น ช่องที่ล็อกไว้จะเปลี่ยนสีไม่ได้",
  str_skill_name_1002111 = "ทุบกระหน่ำ",
  str_skill_desc_1002111 = "ทำดาเมจกับเป้าหมายภายในพื้นที่การโจมตี ถ้าเป้าหมายโดนตีจะกระเด็นไปที่ขอบกระดาน",
  str_skill_name_1002121 = "พลังพายุ",
  str_skill_desc_1002121 = "ทำดาเมจมหาศาลใส่เป้าหมายในวงรอบตัว 2 ชั้น และทุบช่องทั้งหมดภายในระยะ",
  str_skill_name_1002131 = "พลังล้นหลั่ง",
  str_skill_desc_1002131 = "ทำดาเมจกับ 4 แถวแนวตั้งและแนวนอน ถ้าเป้าหมายโดนตีจะกระเด็นไปที่ขอบกระดาน",
  str_skill_name_1002211 = "รูนสายฟ้าเสริมพลัง",
  str_skill_desc_1002211 = "เรียกสายฟ้ากระหน่ำชุดใหญ่เพื่อทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_1002221 = "เฉือนคมกริบ",
  str_skill_desc_1002221 = "หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายเป็นพื้นที่รูปบวกไปจนสุดระยะ โดยมีศูนย์กลางที่ตัวยูนิต",
  str_skill_name_1002231 = "โซนิกบลาสต์โคลอสซัส",
  str_skill_desc_1002231 = "ชูมเมอร์ควบคุมโคลอสซัสเพื่อปล่อยระเบิดพลังคลื่นเสียง ทำดาเมจใส่เป้าหมายทุกตัว",
  str_skill_name_1002251 = "ปิศาจตื่นขึ้น",
  str_skill_desc_1002251 = "หลังจากชูมเมอร์เคลื่อนที่ จะผลักเป้าหมายให้กระเด็นถอยหลังไปยังด้านข้างของกระดาน และปลุกปิศาจใกล้เคียงให้ตื่นขึ้น ปิศาจที่ตื่นขึ้นจะทำดาเมจกับเป้าหมายภายในวงรอบตัว 2 ชั้นของตำแหน่งตัวเอง",
  str_skill_name_1002261 = "พลังงานบ้าคลั่ง",
  str_skill_desc_1002261 = "ชูมเมอร์ปล่อยพลังงานบ้าคลั่ง โจมตีเป้าหมายทั้งหมดบนกระดาน ยิ่งเป้าหมายอยู่ไกลจากชูมเมอร์มากเท่าไร จะยิ่งได้รับดาเมจมากขึ้นเท่านั้น",
  str_skill_name_1002271 = "สปรินต์",
  str_skill_desc_1002271 = "ชูมเมอร์เคลื่อนที่ออกห่างจากเป้าหมายและเรียกสปรินต์ไปยังพื้นที่โจมตี ทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_29002421 = "เผาไหม้",
  str_skill_desc_29002421 = "ทำดาเมจกับเป้าหมายใน 5 แถวแนวตั้งด้านหน้าผู้โจมตี",
  str_skill_name_29002422 = "ราชันแห่งอัคคี",
  str_skill_desc_29002422 = "ปล่อยเพลิงอันตรายร้ายแรงทำดาเมจทั้งกระดาน และทำดาเมจเพิ่มเติม 1 ครั้งกับเป้าหมายใน 4 แถวแนวนอนด้านข้างของกระดาน",
  str_skill_name_29002423 = "เรียกไวน์สมาร์ก",
  str_skill_desc_29002423 = "เรียกไวน์สมาร์ก 2 ตัวมาสู่สนามรบ",
  str_skill_name_1002603 = "ช็อตพลังงาน",
  str_skill_desc_1002603 = "โจมตีเป้าหมายด้านหน้าด้วยระเบิดพลังงานอันเข้มข้นที่ทำให้เป้าหมายกระเด็นถอยหลัง",
  str_skill_name_1002604 = "บาเรียสะท้อน",
  str_skill_desc_1002604 = "กางบาเรียเพื่อลดดาเมจที่คุณได้รับ เมื่อคุณถูกโจมตีขณะที่บาเรียทำงาน ดาเมจส่วนหนึ่งจะสะท้อนกลับไปหาเป้าหมาย",
  str_skill_name_1002605 = "ซ่อมแซมแบบสแตติก",
  str_skill_desc_1002605 = "T1024 เริ่มซ่อมแซมชิ้นส่วนที่เสียหาย ณ ตำแหน่งปฏิบัติงาน ฟื้นฟู HP จำนวนหนึ่ง",
  str_skill_name_1004501 = "อุปสรรคกั้น",
  str_skill_desc_1004501 = "ทำดาเมจกับเป้าหมายภายในพื้นที่การโจมตี ถ้าเป้าหมายโดนตีจะล็อกช่องในวงรอบตัว 1 ชั้น ช่องที่ล็อกไว้จะเปลี่ยนสีไม่ได้",
  str_skill_name_1002702 = "ซ่อมแซมแบบไดนามิก",
  str_skill_desc_1002702 = "โจมตีระยะไกลใส่เป้าหมายที่อยู่แถวเดียวกันในแนวนอนหรือแนวตั้งที่อยู่ในระยะโจมตี",
  str_skill_name_1000901 = "คอยจังหวะ",
  str_skill_desc_1000901 = "ขึ้นอยู่กับระยะห่างไปยังเป้าหมาย ถ้าเป้าหมายอยู่ประชิดตัวจะทำดาเมจรุนแรงกับเป้าหมาย ถ้าเป้าหมายอยู่ห่างจะดึงเป้าหมายเข้าหาตัว",
  str_skill_name_1000911 = "คอยจังหวะ",
  str_skill_desc_1000911 = "ทำดาเมจอย่างรุนแรงเมื่อเข้าใกล้เป้าหมาย หรือดึงเป้าหมายเข้ามาเมื่ออยู่ห่างออกไป จากนั้นเรียกสไปค์เพสต์ออกมาภายในวงรอบตัว 1 ชั้น",
  str_skill_name_1000921 = "ตึงเครียด",
  str_skill_desc_1000921 = "กำหนดรูปแบบการต่อสู้อิงตามระยะห่างจากตัวเป้าหมาย จากนั้นวางสไปค์เพสต์รอบตัว ทำดาเมจรุนแรงเมื่ออยู่ใกล้เป้าหมาย และจะดึงเป้าหมายเข้าหาตัวเมื่ออยู่ไกลจากเป้าหมาย",
  str_skill_name_1000931 = "ตึงเครียด",
  str_skill_desc_1000931 = "กำหนดรูปแบบการต่อสู้อิงตามระยะห่างจากตัวเป้าหมาย จากนั้นวางสไปค์เพสต์รอบตัว ทำดาเมจรุนแรงเมื่ออยู่ใกล้เป้าหมาย และจะดึงเป้าหมายเข้าหาตัวเมื่ออยู่ไกลจากเป้าหมาย",
  str_skill_name_1001001 = "ช่วงชิงพลังงาน",
  str_skill_desc_1001001 = "ดูดพลังงานจากออโรเรียนที่มีรอบคูลดาวน์สกิลใช้งานเหลือน้อยที่สุด ทำให้ต้องรอคูลดาวน์นานขึ้นอีก 3 รอบ",
  str_skill_name_1001611 = "เคออส: เกาะอันเปล่าเปลี่ยว",
  str_skill_desc_1001611 = "พุ่งจู่โจมและกระแทกเป้าหมายไปยังช่องข้าง ๆ\nและเปลี่ยนสีของทุกช่องในวง 2 ชั้นรอบตัว\nที่เป็นปลายทางของการพุ่งตัว",
  str_skill_name_1001621 = "เคออส: ระเบิด",
  str_skill_desc_1001621 = "ทำดาเมจอย่างมากกับเป้าหมายในระยะโจมตี แล้วเปลี่ยนสีทุกช่อง\nในวง 1 ชั้นรอบเป้าหมายที่โดนโจมตี",
  str_skill_name_1001631 = "เคออส: มอดไหม้",
  str_skill_desc_1001631 = "สุ่มทำดาเมจพื้นที่ 2x2 ช่องจำนวน 7 ตำแหน่ง แล้วเปลี่ยนสีทุกช่องในวง 1 ชั้นรอบเป้าหมายที่โดนโจมตี",
  str_skill_name_1001711 = "เดธเลส: จุดระเบิด",
  str_skill_desc_1001711 = "ทำดาเมจใส่เป้าหมายในวงรอบตัว 2 ชั้น จากนั้นหากโจมตีโดนเป้าหมาย จะเพิ่มเวลาคูลดาวน์สกิลใช้งานของออโรเรียนทุกคนในทีม 2 รอบ",
  str_skill_name_1001721 = "เดธเลส: อาฟเตอร์ช็อก",
  str_skill_desc_1001721 = "ทำดาเมจเป็นพื้นที่รูปบวกไปจนสุดสนามรบ จากนั้นหากโจมตีโดนเป้าหมาย จะเพิ่มเวลาคูลดาวน์สกิลใช้งานของออโรเรียนทุกคนในทีม 2 รอบ",
  str_skill_name_1001741 = "กวาดล้าง: จู่โจมปิดฉาก",
  str_skill_desc_1001741 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี จากนั้น หากโจมตีโดนเป้าหมาย จะเพิ่มเวลาคูลดาวน์สกิลใช้งานของออโรเรียนทุกคนในทีม 1 รอบ",
  str_skill_name_1001751 = "กวาดล้าง: หลังศึกผ่านพ้น",
  str_skill_desc_1001751 = "ทำดาเมจเป็นพื้นที่รูปบวกไปจนสุดสนามรบ จากนั้น หากโจมตีโดนเป้าหมาย จะเพิ่มเวลาคูลดาวน์สกิลใช้งานของออโรเรียนทุกคนในทีม 1 รอบ",
  str_skill_name_1001771 = "จู่โจมปิดฉาก",
  str_skill_desc_1001771 = "ทำดาเมจเป็นพื้นที่รูปบวกไปจนสุดสนามรบ จากนั้น หากโจมตีโดนเป้าหมาย จะทำให้ออโรเรียนที่มีรอบคูลดาวน์สกิลใช้งานเหลือน้อยที่สุดต้องคูลดาวน์นานขึ้นอีก 3 รอบ",
  str_skill_name_1001781 = "ช่วงชิงพลังงาน",
  str_skill_desc_1001781 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี หากโจมตีโดนเป้าหมาย จะทำให้ออโรเรียนที่มีรอบคูลดาวน์สกิลใช้งานเหลือน้อยที่สุดต้องคูลดาวน์นานขึ้นอีก 3 รอบ",
  str_skill_name_500411 = "แหล่งจ่ายพลังงาน",
  str_skill_desc_500411 = "ดวงไฟพลังงานเคลื่อนไหวไม่ได้ แต่จะช่วยลดดาเมจที่ดาร์กซัมมอนเนอร์ได้รับผ่านลิงก์พลังงาน",
  str_skill_name_500244 = "คริสตัลสายฟ้าฟาด",
  str_skill_desc_500244 = "คริสตัลแห่งแสงสว่างอันลึกลับที่จะทำงานเมื่อเดินผ่าน ปลดปล่อยสายฟ้าโจมตีศัตรูทุกตัว",
  str_skill_name_500245 = "คริสตัลอุกกาบาต",
  str_skill_desc_500245 = "คริสตัลแห่งแสงสว่างอันลึกลับที่จะทำงานเมื่อเดินผ่าน แล้วเรียกอุกกาบาตมาโจมตีศัตรูที่มี HP สูงสุด",
  str_skill_name_500170 = "เคียว",
  str_skill_desc_500170 = "แฟนท่อมโจมตี 1 ครั้ง ทำดาเมจธาตุ",
  str_skill_name_500171 = "เคียว+",
  str_skill_desc_500171 = "แฟนท่อมบ้าคลั่งโจมตี 2 ครั้ง ทำดาเมจธาตุรุนแรงขึ้นกว่าเดิม",
  str_skill_name_500172 = "กฎของเมอร์ฟี",
  str_skill_desc_500172 = "แฟนท่อมทำดาเมจธาตุเป็นพื้นที่รูปบวก",
  str_skill_name_500173 = "กฎของเมอร์ฟี+",
  str_skill_desc_500173 = "แฟนท่อมบ้าคลั่งทำดาเมจใส่ศัตรูทุกตัวในระยะโจมตี",
  str_skill_name_500174 = "ภาพมายาช่วยต่อสู้",
  str_skill_desc_500174 = "เรียกภาพมายา 1 ตัวมาช่วยแฟนท่อม ภาพมายาที่ปรากฏตัวอยู่แล้วจะถูกดูดกลับเข้าไปก่อนเรียกภาพมายาใหม่ออกมา",
  str_skill_name_500227 = "เสาะหา",
  str_skill_desc_500227 = "เคลื่อนที่ไปอยู่ติดกับช่องที่มีธาตุเดียวกับไซฟอร์บ เตรียมพร้อมดูดพลังงานจากช่องนั้น",
  str_skill_name_500228 = "ผสานพลัง",
  str_skill_desc_500228 = "ไซฟอร์บดูดพลังงานจากช่องที่ตัวเองอยู่ และช่องที่มีธาตุเหมือนตัวเองในวงรอบตัว 1 ชั้น จากนั้นปล่อยลูกพลังงานโจมตีศัตรูทุกตัว ยิ่งดูดพลังงานจากช่องได้มากเท่าใดก็จะยิ่งทำดาเมจแรงขึ้น",
  str_skill_desc_520228 = "ไซฟอร์บดูดพลังงานจากช่องที่ตัวเองอยู่และช่องที่เป็นธาตุเดียวกับตัวเอง และทุบช่องสีแดงในวงรอบตัว 1 ชั้น จากนั้นปล่อยลูกพลังงานโจมตีศัตรูทั้งหมด ยิ่งดูดพลังงานจากช่องได้มากเท่าใด ก็ยิ่งทำดาเมจแรงขึ้นเท่านั้น",
  str_skill_name_501001 = "สายฟ้าแห่งเงามืด",
  str_skill_desc_501001 = "เอนเฟอร์โนเรียกสายฟ้าให้ผ่าลงมาแบบสุ่มตำแหน่งในกระดาน Alchemy แล้วทำดาเมจธาตุและทำให้เป้าหมายเกิดสถานะอัมพาต",
  str_skill_name_501003 = "ฝนเพลิง",
  str_skill_desc_501003 = "เอนเฟอร์โนเรียกฝนเพลิงให้ตกลงมาแบบสุ่มตำแหน่งในกระดาน Alchemy แล้วทำดาเมจธาตุและทำให้เป้าหมายเกิดสถานะเผาไหม้",
  str_skill_name_501011 = "โจมตีระยะไกล",
  str_skill_desc_501011 = "แชโดว์วอล์กเกอร์ปล่อยคลื่นกระแทกขนาด 2 ช่องเป็นพื้นที่รูปบวกไปจนสุดสนามรบ ทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_501015 = "เสริมกำลังใจ",
  str_skill_desc_501015 = "แชโดว์วอล์กเกอร์เคลื่อนที่ไปยังบริเวณที่มียูนิตฝ่ายเดียวกันมากที่สุด แล้วมอบตราพละกำลังให้ยูนิตฝ่ายเดียวกันในระยะ 12 ช่องรอบตัว ทำให้ ATK เพิ่มขึ้น",
  str_skill_name_501021 = "เฮดบัตต์",
  str_skill_desc_501021 = "เบิสต์บัคทำดาเมจใส่เป้าหมายในระยะด้วยหัวอันแข็งแกร่ง เมื่อ HP ของมันเหลือน้อย จะเดินไปหาผู้เล่นแล้วระเบิดตัวเอง",
  str_skill_name_501025 = "เผาเป็นจุณ",
  str_skill_desc_501025 = "เบิสต์บัคใช้พลังชีวิตเฮือกสุดท้ายเคลื่อนที่และระเบิดตัวเอง ทำดาเมจใส่เป้าหมายในวงรอบตัว 1 ชั้น",
  str_skill_name_501031 = "ปนเปื้อน",
  str_skill_desc_501031 = "เมิร์กไมต์โจมตีเป้าหมายในระยะ มันมีพลังต้านทานสูงมาก ให้โจมตีด้วยธาตุที่เมิร์กไมต์แพ้ทางเพื่อทำดาเมจรุนแรง",
  str_skill_name_501032 = "ปนเปื้อน",
  str_skill_desc_501032 = "เมิร์กไมต์โจมตีเป้าหมายทั้งหมดในระยะโจมตี และเปลี่ยนสีทุกช่องตามเส้นทางการเคลื่อนที่ให้เป็นสีเดียวกับธาตุของตัวเอง",
  str_skill_name_501042 = "คำรามคลั่ง",
  str_skill_desc_501042 = "Gertzurde's Servant ใช้ Penetrability Mark กับเป้าหมายภายใน 2 กลุ่มที่อยู่รอบๆ ลด ATK ของทุกเป้าหมายในแต่ละกองซ้อน",
  str_skill_name_501052 = "โคลอสซัส: คมกริบ",
  str_skill_desc_501052 = "ชูมเมอร์ทำดาเมจใส่เป้าหมายเป็นพื้นที่รูปบวกโดยมีศูนย์กลางที่ตัวเธอเอง",
  str_skill_name_501053 = "พลังแห่งสายฟ้า",
  str_skill_desc_501053 = "ชูมเมอร์เรียกพลังแห่งสายฟ้าเพื่อจู่โจมตำแหน่งต่าง ๆ ในสนามรบแบบสุ่ม",
  str_skill_name_501054 = "โคลอสซัส: โซนิกบลาสต์",
  str_skill_desc_501054 = "ชูมเมอร์ควบคุมโคลอสซัสเพื่อปล่อยระเบิดพลังคลื่นเสียง ทำดาเมจใส่เป้าหมายทุกตัว",
  str_skill_name_501056 = "โคลอสซัส: หนวดโจมตี",
  str_skill_desc_501056 = "ชูมเมอร์ควบคุมโคลอสซัสให้ทำดาเมจพื้นที่ด้านหน้าเป็นวงกว้าง",
  str_skill_name_501057 = "โคลอสซัส: โซนิกบลาสต์",
  str_skill_desc_501057 = "ชูมเมอร์ควบคุมโคลอสซัสให้โจมตีเป้าหมายทุกตัวในสนามรบ และเรียกคริสตัลสายฟ้าฟาดให้ปรากฏในสนามรบแบบสุ่มตำแหน่ง เมื่อออโรเรียนเดินผ่านคริสตัลสายฟ้าฟาด คริสตัลจะหายไป",
  str_skill_name_501058 = "เรียกรูนสายฟ้า",
  str_skill_desc_501058 = "ชูมเมอร์เรียกคริสตัลสายฟ้าฟาดให้ปรากฏในสนามรบแบบสุ่มตำแหน่ง ถ้าไม่ทำลายคริสตัล รอบถัดไปชูมเมอร์จะเรียกสายฟ้าให้ผ่าลงมาที่คริสตัลเพื่อทำดาเมจ",
  str_skill_name_501059 = "ฟ้าคำรนกึกก้อง",
  str_skill_desc_501059 = "ชูมเมอร์เรียกสายฟ้าให้ผ่าลงมาที่คริสตัลสายฟ้าฟาด ทำดาเมจรุนแรงและทำให้เกิดสถานะอัมพาต เมื่อออโรเรียนเดินผ่านคริสตัลสายฟ้าฟาด คริสตัลจะหายไป",
  str_skill_name_501061 = "สนามพลัง",
  str_skill_desc_501061 = "ชูมเมอร์ใช้จู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี",
  str_skill_name_501062 = "บลาสต์เวฟ",
  str_skill_desc_501062 = "ชูมเมอร์ปล่อยคลื่นพลังจู่โจมเป้าหมายรอบตัวเธอ ทำดาเมจรุนแรงขึ้นกว่าปกติ",
  str_skill_name_501063 = "สอดประสาน",
  str_skill_desc_501063 = "ปรับ HP ของชูมเมอร์ทุกร่างให้ใกล้เคียงกัน โดยฟื้นฟู HP ได้สูงสุดไม่เกิน 30%",
  str_skill_desc_511063 = "ชูมเมอร์ซิงโครไนซ์พลังชีวิตของเธอ เพิ่ม HP ของชูมเมอร์ทุกร่างให้เท่ากับชูมเมอร์ร่างที่มี HP เหลืออยู่มากที่สุด หากไม่มีชูมเมอร์ร่างอื่นในสนามรบ เธอจะฟื้นฟู 20% ของ Max HP",
  str_skill_name_501082 = "เรียกลูกสมุน",
  str_skill_desc_501082 = "เกิร์ตเซิร์ดเรียกข้ารับใช้ที่เคลื่อนไหวไม่ได้ 2 ตัวลงมาในสนามรบแบบสุ่มตำแหน่ง",
  str_skill_name_501083 = "กราวด์เบรกเกอร์",
  str_skill_desc_501083 = "Gertzurde โจมตีเป้าหมายภายในพื้นที่ของเอฟเฟกต์และใช้ 1 Penetrability Mark ซึ่งจะลด DEF ของเป้าหมายทุกคนในแต่ละกองซ้อน",
  str_skill_name_501084 = "คำรามคลั่ง",
  str_skill_desc_501084 = "Gertzurde คำรามและใช้ 2 Penetrability Marks กับเป้าหมายภายในพื้นที่ที่ส่งผล ลด ATK ของทุกเป้าหมายในแต่ละกองซ้อน",
  str_skill_name_501085 = "จุดระเบิดพลัง",
  str_skill_desc_501085 = "Gertzurde ระเบิด Penetrability Mark บนเป้าหมายเพื่อสร้างความเสียหายมหาศาล พร้อมสร้างความเสียหายเพิ่มขึ้นสำหรับแต่ละกองซ้อน",
  str_skill_name_501087 = "เรียกลูกสมุนระดับสูง",
