  str_skill_name_501113 = "หินร้าว",
  str_skill_desc_501113 = "เฮอร์เครอสทำดาเมจใส่เป้าหมายในระยะโจมตี และผลักเป้าหมายให้กระเด็นถอยหลัง",
  str_skill_name_501114 = "เรียกคริสตัล",
  str_skill_desc_501114 = "เฮอร์เครอสเรียกคริสตัลทวีคูณ 2 อันลงมาในสนามรบแบบสุ่มตำแหน่ง",
  str_skill_name_501115 = "ผ่าปฐพี",
  str_skill_desc_501115 = "เฮอร์เครอสทำดาเมจใส่เป้าหมายในระยะโจมตี\nและผลักเป้าหมายให้กระเด็นถอยหลัง สร้างกองหินพลังธาตุ\n1 กองขึ้นมาด้านหน้าเป้าหมายแต่ละตัวที่ถูกผลัก",
  str_skill_name_501116 = "ก้อนหินร่วงหล่น",
  str_skill_desc_501116 = "เฮอร์เครอสผสานกองหินพลังธาตุทุกกองเข้าด้วยกันเพื่อทำดาเมจใส่เป้าหมาย ยิ่งมีกองหินพลังธาตุมากเท่าใด ดาเมจก็จะยิ่งแรงขึ้น",
  str_skill_name_501141 = "เรียกกองหิน",
  str_skill_desc_501141 = "คริสตัลทวีคูณ",
  str_skill_name_515002 = "แผ่บริเวณ",
  str_skill_desc_515002 = "โซลมอร์ฟระเบิดพลังขนาด 2 ช่องที่ตำแหน่งเป้าหมาย ทำดาเมจใส่เป้าหมายระหว่างทาง",
  str_skill_name_515003 = "กับดักแปรสภาพ",
  str_skill_desc_515003 = "โซลมอร์ฟทำดาเมจใส่เป้าหมายในระยะโจมตีและดึงเป้าหมายเข้าหาตัวเอง พร้อมเปลี่ยนสีช่องทุกช่องในวงรอบตัว 2 ชั้นเสมอ ไม่ว่าจะโจมตีโดนศัตรูหรือไม่",
  str_skill_name_534001 = "แผนหลบหนี",
  str_skill_name_510244 = "พิพากษาฉับไว",
  str_skill_desc_510244 = "ทาบาอัดเทเลพอร์ตไปยังขอบสนามรบ เตรียมพร้อมที่จะพุ่งจู่โจมตำแหน่งเป้าหมาย",
  str_skill_desc_534001 = "พวกโจรขโมยสมบัติสุดเจ้าเล่ห์รู้ดีว่าควรอยู่ให้ห่างจากผู้ตามล่า!",
  str_skill_name_500638 = "เพลิงปฐพี",
  str_skill_desc_500638 = "Nozard ฉีกพื้นดินออก ปล่อย Earthfire เพื่อสร้างความเสียหายแก่เป้าหมายทั้งหมดที่อยู่ในพื้นที่โจมตี และเรียก Slashers สองตัวออกมา",
  str_skill_desc_5006381 = "Nozard ฉีกพื้นดินออก ปล่อย Earthfire เพื่อสร้างความเสียหายแก่เป้าหมายทั้งหมดที่อยู่ในพื้นที่โจมตี",
  str_skill_name_500639 = "ดาร์กเคนนิ่ง",
  str_skill_desc_500639 = "โนซาร์ดรวบรวมและปลดปล่อยพลังออกมา ทำดาเมจเป็นแถวแนวตั้งขนาด 3 ช่องด้านหน้า",
  str_skill_name_500640 = "ปราณเพลิง",
  str_skill_desc_500640 = "Nozard กระพือปีกและปล่อยเปลวไฟสีน้ำเงิน สร้างความเสียหายแก่ศัตรูทั้งหมด",
  str_skill_desc_5006401 = "Nozard กระพือปีกและปล่อยเปลวไฟสีน้ำเงิน สร้างความเสียหายแก่ศัตรูทั้งหมด และสร้าง Immunity Barrier ให้กับตัวมันเอง",
  str_skill_desc_49005111 = "โนซาร์ด โบกปีกและปล่อยเปลวไฟสีน้ำเงิน ทำดาเมจให้กับศัตรูทั้งหมดและกระแทกพวกเขาถอยหลังไป 3 ช่อง จากนั้นเรียก Gloom Ghouls ณ ตำแหน่งที่กำหนด",
  str_skill_name_505106 = "จู่โจมด้านหลัง",
  str_skill_desc_505106 = "โฟโรชั่นโจมตีจากลูมิวอลล์\nทำดาเมจใส่เป้าหมายและรีเซ็ตสีช่องในแถวแนวนอน\nและแนวตั้งโดยมีเป้าหมายเป็นศูนย์กลาง",
  str_skill_name_505109 = "กระแสมืดมิด",
  str_skill_desc_505109 = "โฟโรชั่นเคลื่อนที่แล้วจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี และเรียกภาพมายาลงมาในสนามรบทุกรอบ",
  str_skill_name_504901 = "เงามืดจู่โจม",
  str_skill_desc_504901 = "ภาพมายาโจมตีทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_505121 = "ลูมิวอลล์",
  str_skill_desc_505121 = "โฟโรชั่นแปลงร่างตัวเองได้ และจะซ่อนตัวในลูมิวอลล์ที่อยู่ห่างจากศัตรูที่สุด (สามารถโจมตีลูมิวอลล์ได้) หากลูมิวอลล์ถูกทำลาย มันจะเรียกภาพมายาออกมาโจมตีศัตรู ถ้าคุณทำลายลูมิวอลล์ได้ 2 ทิศ ลูมิวอลล์ทั้งหมดจะหายไปและโฟโรชั่นจะปรากฏตัวออกมา",
  str_skill_name_500251 = "พายุพริบตา",
  str_skill_desc_500251 = "ใช้ขนนกของเวนดี้เพื่อเทเลพอร์ตตัวละครฝ่ายเดียวกันไปยังตำแหน่งที่ขนนกอยู่",
  str_skill_name_500252 = "เสียบแทง",
  str_skill_desc_500252 = "โจมตีเป้าหมายในระยะโจมตี 1 ครั้ง",
  str_skill_name_1002811 = "แคริเออร์อิคลิพไซท์",
  str_skill_desc_1002811 = "อิคลิพไซท์ที่รับผิดชอบในการขนส่ง ปราบพวกมันเพื่อแย่งชิงไนท์เทียมที่พวกมันขนอยู่",
  str_skill_name_515121 = "ลูมิวอลล์",
  str_skill_desc_515121 = "โฟโรชั่นแปลงร่างได้ และจะซ่อนตัวในลูมิวอลล์ที่อยู่ห่างจากศัตรูที่สุด (สามารถโจมตีลูมิวอลล์ได้) หากลูมิวอลล์ถูกทำลาย มันจะเรียกภาพมายาออกมาโจมตีศัตรู ถ้าคุณทำลายลูมิวอลล์ได้ 3 ทิศ ลูมิวอลล์ทั้งหมดจะหายไปและโฟโรชั่นจะปรากฏตัวออกมา",
  str_skill_name_1003401 = "เสริมพลังต่อสู้",
  str_skill_desc_1003401 = "เลิร์คเกอร์สิงร่างอิคลิพไซท์ในวงรอบตัว 1 ชั้น มอบโล่และเพิ่ม ATK ให้กับอิคลิพไซท์ตัวนั้น",
  str_skill_name_1003421 = "ประสาทหลอน",
  str_skill_desc_1003421 = "เลิร์คเกอร์ประสาทหลอนสิงร่างออโรเรียนในวงรอบตัว 1 ชั้นของตัวเอง ลดคะแนนสุขภาพจิตของออโรเรียนนั้นลงอย่างต่อเนื่อง",
  str_skill_name_1003501 = "ฟื้นฟูพลัง",
  str_skill_desc_1003501 = "ถ้าอยู่ในวง 1 ชั้นรอบตัวดอว์น จะผสานเข้ากับตัวเธอเพื่อฟื้นฟู HP ของเธอ",
  str_skill_name_1003502 = "การฟื้นฟูที่ดีขึ้น",
  str_skill_desc_1003502 = "ถ้าอยู่ในวง 1 ชั้นรอบตัวดอว์น จะผสานเข้ากับตัวดอว์นเพื่อฟื้นฟู HP และมอบโล่ให้เธอ",
  str_skill_name_1003601 = "เรเดียนต์สไตรก์",
  str_skill_desc_1003601 = "ทำดาเมจอย่างรุนแรงกับเป้าหมายในวงรอบตัว 2 ชั้น",
  str_skill_name_1003611 = "เฮอร์ริเคนแห่งผืนป่า",
  str_skill_desc_1003611 = "สร้างพายุเฮอร์ริเคนทำดาเมจรุนแรงใส่ศัตรูทุกตัว ยิ่งมีดอว์นสไปรท์บนกระดานมากเท่าไร ดาเมจก็ยิ่งมากขึ้นเท่านั้น",
  str_skill_name_1003621 = "เรียกดอว์นสไปรท์",
  str_skill_desc_1003621 = "เรียกดอว์นสไปรท์ที่มีพลังในการรักษา ดอว์นสไปรท์สามารถฟื้นฟู HP ของดอว์นเมื่ออยู่ในวง 1 ชั้นรอบตัวดอว์น",
  str_skill_name_1003622 = "เรียกดอว์นสไปรท์เสริมพลัง",
  str_skill_desc_1003622 = "เรียกดอว์นสไปรท์ที่มีพลังในการรักษา ฟื้นฟู HP และมอบโล่ให้ดอว์นเมื่ออยู่ในวง 1 ชั้นรอบตัวดอว์น",
  str_skill_name_1003800 = "เบี้ยแยกตัว",
  str_skill_desc_1003800 = "หลังจากเคลื่อนที่ ทำดาเมจกับช่อง 4 ช่องเป็นพื้นที่รูปบวกรอบตัว",
  str_skill_name_1003901 = "คุกคามโดยตรง",
  str_skill_desc_1003901 = "เคลื่อนที่ในแนวนอนหรือแนวตั้งในพื้นที่รูปบวก หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายในวงรอบตัว 1 ชั้น เมื่อพุ่งชนกับเป้าหมายขณะเคลื่อนที่ จะทำดาเมจกับเป้าหมายนี้รุนแรงขึ้นและผลักไปที่ขอบกระดาน",
  str_skill_name_1003902 = "เส้นแนวโจมตี",
  str_skill_desc_1003902 = "เคลื่อนที่ในแนวนอนหรือแนวตั้งในพื้นที่รูปบวก หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายในวงรอบตัว 2 ชั้น เมื่อพุ่งชนกับเป้าหมายขณะเคลื่อนที่ จะทำดาเมจกับเป้าหมายนี้รุนแรงขึ้นและผลักไปที่ขอบกระดาน",
  str_skill_name_1003912 = "แข็งตัว",
  str_skill_desc_1003912 = "อยู่นิ่งกับที่ ไม่สามารถเคลื่อนที่ โจมตี หรือรับดาเมจได้ จะเปิดใช้งานและปฏิบัติการในระลอกถัดไป",
  str_skill_name_1004001 = "พุ่งตัวจู่โจม",
  str_skill_desc_1004001 = "หลังจากลงจอด ทำดาเมจกับ 4 ช่องรอบตัวเป็นพื้นที่รูปบวก ถ้าจุดที่ลงจอดมีเป้าหมายอยู่ จะทำดาเมจกับเป้าหมายนี้อย่างรุนแรงและสตัน พร้อมกับผลักให้ถอยหลัง",
  str_skill_name_1004002 = "ก้าวกระโดด",
  str_skill_desc_1004002 = "หลังจากลงจอด ทำดาเมจในวงรอบตัว 1 ชั้น ถ้าจุดที่ลงจอดมีเป้าหมายอยู่ จะทำดาเมจกับเป้าหมายนี้อย่างรุนแรงและสตัน พร้อมกับผลักให้ถอยหลัง",
  str_skill_desc_1104002 = "หลังจากลงจอด ทำดาเมจในวงรอบตัว 1 ชั้นและตั้งสไปค์เพสต์ในพื้นที่นั้น ถ้ามีเป้าหมายอยู่ที่จุดลงจอด จะทำดาเมจอย่างรุนแรงและสตันเป้าหมาย พร้อมกับผลักให้ถอยหลัง",
  str_skill_name_1004101 = "มุมโจมตี",
  str_skill_desc_1004101 = "เคลื่อนที่ในแนวทแยง หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายเป็นพื้นที่รูปบวกไปจนสุดระยะ โดยมีศูนย์กลางที่ตัวยูนิต",
  str_skill_name_1004102 = "มุมลอบสังหาร",
  str_skill_desc_1004102 = "เคลื่อนที่ในแนวทแยง หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายเป็นพื้นที่รูปบวกไปจนสุดระยะ โดยมีศูนย์กลางที่ตัวยูนิต และลด DEF ของเป้าหมายที่ถูกโจมตี",
  str_skill_desc_1104102 = "เคลื่อนที่ในแนวทแยง หลังจากเคลื่อนที่จะทำดาเมจกับเป้าหมายเป็นพื้นที่รูปบวกไปจนสุดระยะ โดยมีศูนย์กลางที่ตัวยูนิต และลด DEF ของเป้าหมายที่ถูกโจมตีลงอย่างมาก",
  str_skill_name_1004201 = "ทีมราชินี",
  str_skill_desc_1004201 = "ทำดาเมจเท่ากับเปอร์เซ็นต์ของ HP สูงสุดของเป้าหมายเป็นพื้นที่รูปดอกจันไปจนสุดสนามรบ โดยมีศูนย์กลางที่ตัวยูนิต",
  str_skill_name_1004202 = "ป้องกันแน่นหนา",
  str_skill_desc_1004202 = "ทำดาเมจเท่ากับเปอร์เซ็นต์ของ HP สูงสุดของเป้าหมายเป็นพื้นที่รูปดอกจันไปจนสุดสนามรบ โดยมีศูนย์กลางที่ตัวยูนิต ถ้าไม่มีเป้าหมายใน 8 ทิศทางรอบยูนิต จะได้รับบาเรียป้องกันและฟื้นฟู HP ให้กับยูนิตฝ่ายเดียวกัน",
  str_skill_desc_1104202 = "ทำดาเมจเท่ากับเปอร์เซ็นต์ของ HP สูงสุดของเป้าหมายเป็นพื้นที่รูปดอกจันไปจนสุดสนามรบ โดยมีศูนย์กลางที่ตัวยูนิต ถ้าไม่มีเป้าหมายใน 8 ทิศทางรอบยูนิต จะได้รับบาเรียป้องกัน ลดสุขภาพจิตของผู้เล่น และฟื้นฟู HP ให้กับยูนิตฝ่ายเดียวกัน",
  str_skill_name_1004301 = "บัญชาราชวงศ์",
  str_skill_desc_1004301 = "สั่งให้เบี้ยทำดาเมจกับเป้าหมายในวงรอบตัว 1 ชั้น",
  str_skill_name_1004302 = "ป้องปราม",
  str_skill_desc_1004302 = "ผลักเป้าหมายในระยะให้กระเด็นถอยหลัง จนกระทั่งเป้าหมายออกนอกระยะโจมตี",
  str_skill_name_1004303 = "อาณาจักรราชัน",
  str_skill_desc_1004303 = "ทำดาเมจกับศัตรูทุกตัวในสนามรบ",
  str_skill_name_1006511 = "พุ่งชน",
  str_skill_desc_1006511 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_1006521 = "แตกแยก",
  str_skill_desc_1006521 = "ระเบิดพลังงานภายในร่างกาย ทำดาเมจใส่เป้าหมายในระยะโจมตีและทำลายช่องที่มันยืนอยู่",
  str_skill_name_1007001 = "ขุดหลุม",
  str_skill_desc_1007001 = "เมื่อมีช่องที่เสียหายอยู่ในระยะของเป้าหมาย จะขุดหลุมโผล่ขึ้นมาจากช่องที่แตกข้าง ๆ เป้าหมายและทำดาเมจ พร้อมกับทำลายช่องที่ติดกัน เมื่อออโรเรียนเดินผ่านช่องที่เสียหาย จะไม่นับคอมโบเพิ่ม",
  str_skill_name_1007011 = "กราวด์เบรกเกอร์",
  str_skill_desc_1007011 = "เมื่อไม่มีช่องที่เสียหายอยู่ในระยะของเป้าหมาย จะเคลื่อนที่ไปยังตำแหน่ง 2 ช่องถัดไปแล้วทำลาย 8 ช่องในวงรอบตัว 1 ชั้น เมื่อออโรเรียนเดินผ่านช่องที่เสียหาย จะไม่นับคอมโบเพิ่ม",
  str_skill_name_29010011 = "กรีดร้อง",
  str_skill_desc_29010011 = "เมื่อเป้าหมายยืนติดกับช่องที่เสียหาย จะย้ายไปยังช่องที่เสียหายนั้นและทำดาเมจกับเป้าหมายพร้อมกับผลักให้ถอยหลัง",
  str_skill_name_29010012 = "ภัยคุกคาม",
  str_skill_desc_29010012 = "เมื่อเป้าหมายอยู่ภายในระยะรูปดอกจัน จะย้ายไปยืนติดกันแล้วทำดาเมจกับเป้าหมายพร้อมกับผลักให้ถอยหลังและตีช่องให้แตกตามแนวเส้นตรงระหว่างเป้าหมายกับผู้โจมตี",
  str_skill_name_1007102 = "เฆี่ยน",
  str_skill_desc_1007102 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_desc_10071021 = "สังหารเป้าหมายทั้งหมดในระยะโจมตีทันที",
  str_skill_desc_220091202 = "ทำลายช่องในระยะและทำดาเมจใส่เป้าหมายในระยะ",
  str_skill_name_1007103 = "กระแสพิฆาต",
  str_skill_desc_1007103 = "ปล่อยคลื่นกระแทกไปยังตำแหน่งของเป้าหมายในรอบสุดท้ายภายในวงรอบตัว 1 ชั้น ถ้าเป้าหมายอยู่ในระยะโจมตีของคลื่นกระแทก เป้าหมายจะได้รับดาเมจอย่างรุนแรง",
  str_skill_desc_1107103 = "ปล่อยการจู่โจมไปยังตำแหน่งของเป้าหมายในรอบสุดท้ายภายในวงรอบตัว 1 ชั้น เอาชนะเป้าหมายในระยะทันที",
  str_skill_desc_220091201 = "เข้าโจมตีตำแหน่งของเป้าหมายภายในวงรอบตัว 1 ชั้นในรอบสุดท้าย ทำลายช่องในระยะและกำจัดเป้าหมายในระยะทันที",
  str_skill_name_1007104 = "ระเบิดพลังเสียง",
  str_skill_desc_1007104 = "ทำดาเมจใส่เป้าหมายในระยะโจมตีและผลักให้กระเด็นถอยหลัง",
  str_skill_desc_10071041 = "ทำดาเมจใส่เป้าหมายในระยะโจมตีและผลักให้กระเด็นถอยหลัง ขณะเดียวกันก็เรียกกรงเล็บหนวดจำนวนมากซึ่งจะลดสุขภาพจิตของออโรเรียน",
  str_skill_name_1007112 = "ลำแสงปะทะ",
  str_skill_desc_1007112 = "ปล่อยลำแสงอันทรงพลังไปยังตำแหน่งของเป้าหมายในรอบสุดท้าย ทำดาเมจใส่เป้าหมายที่อยู่ในเส้นทางของลำแสง และที่ตำแหน่งของเป้าหมาย (มอนสเตอร์จะคืนชีพในตำแหน่งของตัวเอง 2 รอบหลังจากตาย)",
  str_skill_desc_10071121 = "ปล่อยลำแสงปะทะไปยังตำแหน่งของเป้าหมายในรอบสุดท้าย ทำดาเมจใส่เป้าหมายที่อยู่ในเส้นทางของลำแสง และที่ตำแหน่งของเป้าหมาย",
  str_skill_name_1007113 = "ปลิวลม",
  str_skill_desc_1007113 = "ผลักเป้าหมายที่อยู่ในระยะให้ไปอยู่กลางกระดาน (มอนสเตอร์จะคืนชีพในตำแหน่งของตัวเอง 2 รอบหลังจากตาย)",
  str_skill_name_39004511 = "กระแสมืดมิด",
  str_skill_desc_39004511 = "โฟโรชั่นจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตีหลังจากเคลื่อนที่ และเรียกภาพลวงตา 2 ชุดเข้ามาในสนามรบจากทางด้านข้าง",
  str_skill_name_39004512 = "จู่โจมด้านหลัง",
  str_skill_desc_39004512 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมาย ทำดาเมจกับเป้าหมายและเรียกภาพลวงตามาใกล้ ๆ",
  str_skill_name_20005011 = "ตึงเครียด",
  str_skill_desc_20005011 = "กำหนดรูปแบบการต่อสู้ขึ้นอยู่กับระยะห่างจากตัวเป้าหมาย จากนั้นวางสไปค์เพสต์รอบตัว ทำดาเมจรุนแรงเมื่ออยู่ใกล้เป้าหมาย และจะดึงเป้าหมายเข้าหาตัวเมื่ออยู่ไกลจากเป้าหมาย",
  str_skill_name_20002441 = "เรียกอิคลิพไซท์",
  str_skill_desc_20002441 = "ลาชองเรียกอิคลิพไซท์ที่ทรงพลังยิ่งขึ้นมาที่สนามรบในทุกรอบ",
  str_skill_desc_20002411 = "อัญเชิญอิคลิพไซท์ทรงพลังสู่สนามรบทุกรอบ",
  str_skill_name_200024211 = "เรียกเดรดเบลด",
  str_skill_desc_200024211 = "เรียกเดรดเบลดมาต่อสู้ทุกรอบ",
  str_skill_name_200024221 = "เรียกเดรดเบลดและสเปลล์ฮาวนด์",
  str_skill_name_200024231 = "เรียกเดรดเบลดและไวน์สมาร์ก",
  str_skill_desc_200024221 = "เรียกเดรดเบลดและสเปลล์ฮาวนด์มาต่อสู้ทุกรอบ",
  str_skill_desc_200024231 = "เรียกเดรดเบลดและไวน์สมาร์กมาที่สนามรบในแต่ละรอบ",
  str_skill_name_10000021 = "เรียกสเปลล์ฮาวนด์",
  str_skill_desc_10000021 = "เรียกสเปลล์ฮาวนด์มาต่อสู้ทุกรอบ",
  str_skill_name_28002411 = "กดขี่",
  str_skill_desc_28002411 = "ฟอร์เซคินผลักคุณให้กระเด็นถอยหลังทุกรอบ",
  str_skill_name_390041101 = "กราวด์เบรกเกอร์ทมิฬ",
  str_skill_desc_390041101 = "Gertzurde โจมตีเป้าหมายภายในพื้นที่โจมตี 2 ครั้ง และใช้ Vulnerability Mark 2 แต้ม ยิ่งแต้มสะสมมากเท่าไหร่ ATK ของทีมก็จะยิ่งลดลงเท่านั้น จากนั้น Gertzurde จะเรียกบริวารของ Gertzurde 4 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_390041102 = "กราวด์เบรกเกอร์ทมิฬ",
  str_skill_desc_390041102 = "Gertzurde โจมตีเป้าหมายภายในพื้นที่โจมตี 2 ครั้ง และใช้ Vulnerability Mark 2 แต้ม ยิ่งแต้มสะสมมากเท่าไหร่ ATK ของทีมก็จะยิ่งลดลงเท่านั้น จากนั้น Gertzurde จะเรียกบริวารของ Gertzurde 4 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_390041103 = "คำรามคลั่งระดับสูงทมิฬ",
  str_skill_desc_390041103 = "เสียงคำรามครั้งสุดท้ายของ Gertzurde ทำให้แต้ม Vulnerability Mark 3 แต้มแก่เป้าหมายที่อยู่ในพื้นที่โจมตี ยิ่งมีกองซ้อนมาก ค่า DEF เป้าหมายยิ่งต่ำ",
  str_skill_name_390041104 = "ระเบิดพลังทมิฬ",
  str_skill_desc_390041104 = "Gertzurde ระเบิด Vulnerability Marks บนเป้าหมายเพื่อสร้างความเสียหายอย่างหนัก ความเสียหายจะขึ้นอยู่กับจำนวนของเครื่องหมายบนเป้าหมาย เครื่องหมายช่องโหว่จะไม่ถูกล้างหลังจากการระเบิด",
  str_skill_name_300045101 = "คำรามคลั่งทมิฬ",
  str_skill_desc_300045101 = "ข้ารับใช้ของเกิร์ตเซิร์ดร่ายตราทะลวงใส่เป้าหมายในวงรอบตัว 2 ชั้น ตราแต่ละสแต็กจะลด DEF ของเป้าหมาย",
  str_skill_name_391028101 = "กางเขนแห่งความมืด",
  str_skill_desc_391028101 = "ดาร์กซัมมอนเนอร์ทำดาเมจใส่เป้าหมายเป็นพื้นที่รูปบวกไปจนสุดสนามรบ และเรียกประภาคาร 2 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_391028102 = "เก็บพลังงาน",
  str_skill_desc_391028102 = "ดาร์กซัมมอนเนอร์เก็บพลังงานที่ตำแหน่งปัจจุบัน และเรียกประภาคาร 4 ตัวมายังตำแหน่งที่เลือก จากนั้นฟื้นฟู HP ให้ประภาคารทั้งหมด",
  str_skill_name_391028103 = "ไร้ตัวตน",
  str_skill_desc_391028103 = "ดาร์กซัมมอนเนอร์จุดระเบิดพลังงานที่ชาร์จไว้ ทำดาเมจกับทั้งสนามรบ",
  str_skill_name_391028104 = "กางเขนแห่งความมืด",
  str_skill_desc_391028104 = "ดาร์กซัมมอนเนอร์ทำดาเมจใส่เป้าหมายเป็นพื้นที่รูปบวกไปจนสุดสนามรบ และเรียกประภาคาร 2 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_300040101 = "พลังงานโอเวอร์โหลด",
  str_skill_desc_300040101 = "ประภาคารให้พลังงานกับดาร์กซัมมอนเนอร์ผ่านทางลิงก์พลังงาน ประภาคารแต่ละตัวเพิ่ม ATK ของดาร์กซัมมอนเนอร์ 5%",
  str_skill_name_390026401 = "เรเดียนต์สไตรก์ทมิฬ",
  str_skill_desc_390026401 = "หลังจากเคลื่อนที่ ทำดาเมจอย่างรุนแรงกับเป้าหมายในวงรอบตัว 2 ชั้น และเรียกดอว์นสไปรท์ 2 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_390026402 = "เรเดียนต์สไตรก์ทมิฬ",
  str_skill_desc_390026402 = "หลังจากเคลื่อนที่ ทำดาเมจอย่างรุนแรงกับเป้าหมายในวงรอบตัว 2 ชั้น และเรียกดอว์นสไปรท์ 2 ตัวมายังตำแหน่งที่เลือก",
  str_skill_name_390026403 = "เฮอร์ริเคนแห่งผืนป่าทมิฬ",
  str_skill_desc_390026403 = "สร้างพายุเฮอร์ริเคนทำดาเมจรุนแรงใส่ศัตรูทุกตัว ยิ่งมีดอว์นสไปรท์ในสนามรบมากเท่าไร ดาเมจก็ยิ่งมากขึ้นเท่านั้น",
  str_skill_name_300060201 = "ปรสิตทมิฬ",
  str_skill_desc_300060201 = "ค่อย ๆ เคลื่อนที่เข้าหาศัตรู เมื่อเคลื่อนที่เข้าไปหาศัตรูในระยะ 1 ชั้น จะทำดาเมจกับศัตรู",
  str_skill_name_390064101 = "แสงจันทร์ทมิฬ",
  str_skill_desc_390064101 = "หลังจากคาราคาลูนเคลื่อนที่ มันจะทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_390064102 = "คาราคาลูนทมิฬ",
  str_skill_desc_390064102 = "คาราคาลูนปล่อยระเบิดพลัง ทำดาเมจกับเป้าหมายใน 2 แถวแนวตั้งและแนวนอน และล็อกช่องในตำแหน่งที่มันอยู่",
  str_skill_name_390064103 = "ลูเมนทมิฬ",
  str_skill_desc_390064103 = "คาราคาลูนกลายเป็นเพิลนาลูน ชนกับเป้าหมายโดยตรงและทำดาเมจกับเป้าหมาย",
  str_skill_name_390066101 = "ทุบกระหน่ำทมิฬ",
  str_skill_desc_390066101 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี",
  str_skill_name_390066102 = "พลังล้นหลั่งทมิฬ",
  str_skill_desc_390066102 = "ทำดาเมจกับเป้าหมายใน 2 แถวแนวตั้งและแนวนอน และทำลายช่องในตำแหน่งที่มันอยู่",
  str_skill_name_390066103 = "พลังพายุทมิฬ",
  str_skill_desc_390066103 = "ทำดาเมจรุนแรงกับทั้งสนามรบ",
  str_skill_name_390021101 = "พสุธาสะเทือนทมิฬ",
  str_skill_desc_390021101 = "ทำดาเมจกับเป้าหมาย 4 ทิศทางในระยะ 1 ช่อง และเรียกกองหิน 4 กองมายังตำแหน่งที่กำหนด",
  str_skill_name_390021102 = "พสุธาสะเทือนทมิฬ",
  str_skill_desc_390021102 = "ทำดาเมจกับเป้าหมาย 4 ทิศทางในระยะ 1 ช่อง และเรียกกองหิน 4 กองมายังตำแหน่งที่กำหนด",
  str_skill_name_390021103 = "หินผาอัดกระแทกทมิฬ",
  str_skill_desc_390021103 = "อัมบราฮัลก์ผลักศัตรูรอบตัวให้กระเด็นถอยหลังไปไกลที่สุดเท่าที่จะทำได้ จากนั้นเรียกกองหินขึ้นมาด้านหน้าเป้าหมายแต่ละตัว",
  str_skill_name_390021104 = "ฝนศิลาทมิฬ",
  str_skill_desc_390021104 = "อัมบราฮัลก์ดูดกองหินในสนามรบเข้าไปและทำดาเมจใส่ศัตรูเป็นอัตราส่วนตามจำนวนกองหินที่ดูดเข้าไป",
  str_skill_name_390025101 = "เคียวทมิฬ",
  str_skill_desc_390025101 = "แฟนท่อมโจมตี 1 ครั้ง ทำดาเมจธาตุ",
  str_skill_name_390025102 = "กฎของเมอร์ฟีทมิฬ",
  str_skill_desc_390025102 = "แฟนท่อมทำดาเมจธาตุเป็นพื้นที่รูปบวก",
  str_skill_name_390025103 = "เรียกภาพมายา",
  str_skill_desc_390025103 = "เรียกภาพหลอนเกรี้ยวกราด 1 ชุด และสั่งให้ทำดาเมจกับศัตรูทุกตัวในสนามรบ ยิ่งเป้าหมายมี HP น้อย ก็ยิ่งทำดาเมจได้มาก",
  str_skill_name_1007211 = "พลังความมืดโซลัส",
  str_skill_desc_1007211 = "ม้อดปล่อยคลื่นกระแทกออกไปข้างหน้าในรูปสามเหลี่ยม 2 ช่องที่ไปได้ไกลถึงระยะสูงสุด ทำดาเมจให้กับเป้าหมายที่โดนโจมตี",
  str_skill_name_1007221 = "หุ่นเชิดโซลัส",
  str_skill_desc_1007221 = "ม้อดเรียกอิคลิพไซท์บางตัวมาช่วยจำกัดการกระทำของออโรเรียน",
  str_skill_name_290120101 = "ค่ำคืนที่มืดมิดที่สุด",
  str_skill_desc_290120101 = "หากเคลย์มอร์ไม่สามารถเคลื่อนที่ไปหาเป้าหมายได้ด้วยช่องที่เชื่อมต่อกัน เคลย์มอร์จะปฏิบัติการเหมือนอิคลิพไซต์ หลังจากเคลื่อนที่ มันจะฟันเป้าหมายในระยะ ทำดาเมจใส่พวกมันพร้อมสร้างบาร์เรียที่สามารถทนการโจมตีได้ 1 ครั้ง",
  str_skill_name_290120102 = "แสงลวง",
  str_skill_desc_290120102 = "หากเคลย์มอร์สามารถเคลื่อนที่ไปหาเป้าหมายได้ด้วยช่องที่เชื่อมต่อกัน เคลย์มอร์จะปฏิบัติการเหมือนออโรเรียน ทำดาเมจอย่างรุนแรงใส่เป้าหมายหลังจากเชื่อมต่อช่องและเคลื่อนที่เข้าหามัน",
  str_skill_name_290120103 = "อัมบรัล สตอล์กเกอร์",
  str_skill_desc_290120103 = "เคลย์มอร์หายตัวไปปรากฏตัวกลางแผนที่และปลดปล่อยพลังอันน่ากลัวเพื่อทำลายช่องในแนวกากบาทจากจุดศูนย์กลางของแผนที่ พร้อมใช้พลังงานความมืดเพื่อปกคลุม 3 ส่วนของแผนที่ ทำให้ลูมินาทั้งหมดในพื้นที่เหล่านั้นถูกกลืนกินชั่วคราว",
  str_skill_name_290130101 = "ถอยทัพ",
  str_skill_desc_290130101 = "เฟียร์มองเกอร์โจมตีศัตรูเป้าหมายทั้งหมดในระยะของสกิล ทำดาเมจและผลักให้ถอยหลัง",
  str_skill_name_290130102 = "ฝันร้าย",
  str_skill_desc_290130102 = "เฟียร์มองเกอร์ทำดาเมจกับเป้าหมายทั้งหมดในทุกพื้นที่",
  str_skill_name_290130103 = "เสื่อมทราม",
  str_skill_desc_290130103 = "Fearmonger สร้างความเสียหายให้กับเป้าหมายภายใน 2 กลุ่มรอบ ๆ และแปลงสีบนกระเบื้องภายในระยะทักษะ นอกจากนี้ยังล็อคไทล์บางส่วนในช่วงเดียวกัน หลังจากนั้น Fearmonger เรียกมินเนี่ยน 3 ตัว",
  str_skill_desc_290130113 = "Fearmonger สร้างความเสียหายให้กับเป้าหมายภายใน 2 กลุ่มรอบ ๆ และแปลงสีบนกระเบื้องภายในระยะทักษะ นอกจากนี้ยังล็อคไทล์บางส่วนในช่วงเดียวกัน หลังจากนั้น Fearmonger เรียกมินเนี่ยน 2 ตัว",
  str_skill_desc_290130123 = "Fearmonger สร้างความเสียหายให้กับเป้าหมายภายใน 2 กลุ่มรอบ ๆ และเปลี่ยนสีบนกระเบื้องในขณะที่ล็อคกระเบื้องไว้ในระยะ หลังจากนั้น Fearmonger เรียกมินเนี่ยน 4 ตัว",
  str_skill_name_290134101 = "ถอยทัพ",
  str_skill_desc_290134101 = "เฟียร์มองเกอร์โจมตีศัตรูเป้าหมายทั้งหมดในระยะของสกิล ทำดาเมจและผลักให้ถอยหลัง จากนั้นเรียกสมุนเฟียร์มองเกอร์เข้ามาในสนามรบ",
  str_skill_name_290134102 = "ฝันร้าย",
  str_skill_desc_290134102 = "เฟียร์มองเกอร์ทำดาเมจกับเป้าหมายทั้งหมดในทุกพื้นที่ และสร้างช่องอ่อนแอขึ้นในสนามรบ",
  str_skill_name_290134103 = "เสื่อมทราม",
  str_skill_desc_290134103 = "เฟียร์มองเกอร์เปลี่ยนสีช่องทั้งหมดในวงรอบตัว 2 ชั้น และล็อกบางช่องที่อยู่ในระยะ",
  str_skill_desc_290130104 = "??? โจมตีศัตรูเป้าหมายทั้งหมดในระยะของสกิล ทำดาเมจและผลักให้ถอยหลัง",
  str_skill_desc_290130105 = "??? ทำดาเมจกับเป้าหมายทั้งหมดในทุกพื้นที่",
  str_skill_desc_290130106 = "??? ทำดาเมจกับเป้าหมายในวงรอบตัว 2 ชั้น และแปลงสีช่องพร้อมกับล็อกช่องที่อยู่ในระยะของสกิล",
  str_skill_name_200130101 = "ลอบโจมตี",
  str_skill_desc_200130101 = "ทำดาเมจอย่างสูงกับศัตรูเป้าหมายหนึ่งตัว หนึ่งครั้ง",
  str_skill_name_200134101 = "ลอบโจมตี",
  str_skill_desc_200134101 = "ทำดาเมจรุนแรง 1 ครั้ง กับเป้าหมายศัตรูในระยะโจมตี",
  str_skill_name_200134105 = "ลอบโจมตี",
  str_skill_desc_200134105 = "ทำดาเมจอย่างสูงกับศัตรูเป้าหมายหนึ่งตัว หนึ่งครั้ง",
  str_skill_desc_200130102 = "ทำดาเมจอย่างสูงกับศัตรูเป้าหมายหนึ่งตัวในสนามรบหนึ่งครั้ง และติดเครื่องหมายเฟียร์มองเกอร์ให้เป้าหมาย แต่ละสแต็กของเครื่องหมายนี้จะลด DEF ของเป้าหมาย (ยิ่งมีสแต็กมาก DEF ของเป้าหมายก็ยิ่งลดลงมาก) เมื่อเข้าสู่ออโรราไทม์จะล้างเครื่องหมายเฟียร์มองเกอร์ทั้งหมด",
  str_skill_name_290180101 = "คำสั่ง - ขับไล่",
  str_skill_desc_290180101 = "โจมตีระยะไกลใส่เป้าหมายในระยะโจมตี",
  str_skill_name_290180201 = "คำสั่ง - คุ้มกัน",
  str_skill_desc_290180201 = "โจมตีระยะไกลใส่เป้าหมายในระยะโจมตี จากนั้นเรียกเครื่องก่อกวนมายังสนามรบ (เครื่องก่อกวนมีจำนวนจำกัด)",
  str_skill_name_290180301 = "คำสั่ง - ทำลาย",
  str_skill_desc_290180301 = "โจมตีระยะไกลใส่เป้าหมายในระยะโจมตี จากนั้นเรียกหอปริซึมมายังสนามรบ",
  str_skill_name_290180401 = "คำสั่ง - กวาดล้าง",
  str_skill_desc_290180401 = "โจมตีระยะไกลใส่เป้าหมายในระยะโจมตี จากนั้นเรียกหอปริซึมและเครื่องก่อกวนมายังสนามรบ (เครื่องก่อกวนมีจำนวนจำกัด)",
  str_skill_name_51104811 = "กลลวง",
  str_skill_desc_51104811 = "เรียกภาพลวงตามาที่ช่องด้านหน้า",
  str_skill_desc_39104512 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมาย ทำดาเมจกับเป้าหมายและเรียกภาพลวงตามาใกล้ ๆ ยิ่งกำแพงเหลือน้อย ภาพลวงตาก็ยิ่งแกร่ง",
  str_skill_desc_39204512 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมายและทำดาเมจพร้อมกับเรียกภาพลวงตามาใกล้ ๆ และล็อกช่องในวงรอบตัว 1 ชั้น ยิ่งกำแพงเหลือน้อย ภาพลวงตาก็ยิ่งแกร่ง",
  str_skill_desc_39104522 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมาย ทำดาเมจและเรียกภาพลวงตา 1–2 ตัวเข้ามาในสนามตามจำนวนกำแพงที่เหลืออยู่ ยิ่งกำแพงเหลือน้อย ภาพลวงตาก็ยิ่งแกร่ง",
  str_skill_desc_39204522 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมาย ทำดาเมจและเรียกภาพลวงตา 1–2 ตัวเข้ามาในสนามตามจำนวนกำแพงที่เหลืออยู่ พร้อมกับล็อกช่องในวงรอบตัว 1 ชั้น ยิ่งกำแพงเหลือน้อย ภาพลวงตาก็ยิ่งแกร่ง",
  str_skill_desc_39104511 = "โฟโรชั่นจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตีของมันหลังจากเคลื่อนที่",
  str_skill_desc_290039101 = "โบว์ลิงเกอร์ยิงเดธไรเดอร์ 5 นัดเข้าสู่สนามรบ",
  str_skill_desc_290039102 = "โบว์ลิงเกอร์ปาระเบิดใส่กระดานในพื้นที่ 2×2 ช่อง จำนวน 7 จุด และทำให้เดธไรเดอร์ทั้งหมดที่อยู่ในระยะเกิดการระเบิด",
  str_skill_desc_290139102 = "โบว์ลิงเกอร์ปาระเบิดใส่กระดานในพื้นที่ 2×2 ช่อง จำนวน 7 จุด รีเซ็ตช่องและทำให้เดธไรเดอร์ทั้งหมดที่อยู่ในระยะเกิดการระเบิด",
  str_skill_desc_291139102 = "โบว์ลิงเกอร์ปาระเบิดใส่กระดานในพื้นที่ 2×2 ช่อง จำนวน 7 จุด รีเซ็ตช่องและทำให้เดธไรเดอร์ทั้งหมดที่อยู่ในระยะเกิดการระเบิด",
  str_skill_name_13005802 = "ธงแห่งรุ่งอรุณ",
  str_skill_desc_13005802 = "วางธงของเอมี่ในช่องที่เลือก 1 ช่อง ยิ่งออโรเรียนอยู่ใกล้ธงเท่าใด DEF ก็จะยิ่งเพิ่มขึ้น (สูงสุด <color=#00F6FF>30%</color>) ธงจะหายไปเมื่อศัตรูแตะต้อง",
  str_skill_name_13008001 = "เสบียงช่วยเหลือครอบคลุม",
  str_skill_desc_13008001 = "<color=#00F6FF>ปล่อยสกิลได้รอบละ 1 ครั้ง</color> ขว้างกระป๋องไปยังช่องใดก็ได้ที่เลือกเพื่อทำให้เกิดไอเทมป้องกันที่ช่องนั้น",
  str_skill_name_14006701 = "อัศวิน & ราชินี",
