  str_skill_desc_304041 = "เปลี่ยน<color=#00F6FF>ช่อง 4 ช่องรูปบวก</color>ให้เป็นสีน้ำเงิน และมีโอกาสเกิด<link=\"20001\"><#FFAE07><u>ช่องเสริมพลัง</u></color></link>สูงสุด 2 ช่อง",
