  str_skill_desc_310021 = "รีเซ็ตสีของทุกช่องในสนามรบ แต่ยังเก็บ<link=\"20001\"><#FFAE07><u>ช่องเสริมพลัง</u></color></link>เอาไว้เพื่อจัดสรรใหม่",
  str_skill_desc_330021 = "รีเซ็ตสีของทุกช่องในสนามรบ แต่ยังเก็บ<link=\"20001\"><#FFAE07><u>ช่องเสริมพลัง</u></color></link>เอาไว้เพื่อจัดสรรใหม่ ช่องสีเขียวมีโอกาสที่จะเกิดเป็น<link=\"20001\"><#FFAE07>ช่องเสริมพลัง</u></color></link>มากขึ้น",
