  str_skill_desc_200411 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 1 ชั้น</color>",
  str_skill_desc_200211 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>8 ช่องรูปบวก</color> และทำให้เกิดสถานะ<link=\"10001\"><#FFAE07><u>พิษ</u></color></link> 1 สแต็ก นาน 2 รอบ",
  str_skill_desc_204211 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>8 ช่องรูปบวก</color> ทำให้เกิดสถานะ<link=\"10001\"><#FFAE07><u>พิษ</u></color></link> 1 สแต็ก และมีโอกาส <color=#00F6FF>30%</color> ที่จะเพิ่มสถานะพิษอีก 1 สแต็ก นาน 2 รอบ",
  str_skill_desc_200041 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 1 ชั้น</color>",
