  str_skill_desc_221003 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 4 ตัว ดาเมจนี้จะไม่สนใจ DEF หากเป้าหมายถูกเกี่ยววิญญาณ",
  str_skill_desc_200983 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูทุกตัวใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color>",
  str_skill_desc_200963 = "ทำดาเมจ <color=#00F6FF>150%</color> เป็นจำนวน 5 ครั้ง กับศัตรูแบบสุ่มใน <color=#00F6FF>วงรอบตัว 3 ชั้น</color> ถ้าเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง",
  str_skill_desc_2001033 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด ใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color>",
  str_skill_desc_2201033 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด ใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color>",
  str_skill_desc_2301093 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 1 ตัว และได้รับ Vis 3 หน่วย",
  str_skill_desc_2361093 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 1 ตัว และได้รับ Vis 3 หน่วย มีโอกาส <color=#00F6FF>30%</color> ที่จะเพิ่มดาเมจ <color=#00F6FF>50%</color> (ค่า Vis +1 หน่วยจะเพิ่มโอกาสอีก 1%)",
  str_skill_desc_2301103 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ถ้ามีการทำดาเมจ จะปล่อยสายฟ้าผ่าศัตรูที่อยู่ไกลที่สุดอีก 1 ครั้งเพื่อทำดาเมจด้วยความรุนแรงเท่ากัน",
