  str_skill_desc_2001451 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>8 ช่องรูปบวก</color>",
  str_skill_desc_2001452 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> และเรียกคาตานะ <color=#00F6FF>1</color> เล่ม สุ่มลงบน 1 ช่องที่เดินไปถึงได้",
