  str_skill_passive_name_420156 = "ผู้พิทักษ์กรุสมบัติลับ",
  str_skill_desc_2001561 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 1 ชั้น</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>150%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2001562 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>160%</color> กับศัตรูที่อยู่ใกล้ที่สุด 3 ตัว",
  str_skill_desc_2001563 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ใน <color=#00F6FF>วงรอบตัว 2 ชั้น</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>170%</color> กับศัตรูที่อยู่ใกล้ที่สุด 4 ตัว",
  str_skill_desc_2001564 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 1 ชั้น</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>150%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2001565 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>160%</color> กับศัตรูที่อยู่ใกล้ที่สุด 3 ตัว",
  str_skill_desc_2001566 = "<color=#00F6FF>โหมดถือร่ม</color>: ทำดาเมจ <color=#00F6FF>{1}%</color> ใน <color=#00F6FF>วงรอบตัว 2 ชั้น</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: ทำดาเมจ <color=#00F6FF>170%</color> กับศัตรูที่อยู่ใกล้ที่สุด 4 ตัว",
  str_skill_desc_300156 = "<color=#00F6FF>โหมดถือร่ม</color>: เลือก 1 ช่องที่เดินไปถึงได้แล้วปาร่มลงบนช่องนั้น ทำดาเมจ <color=#00F6FF>80%</color> ไปตามเส้นทาง แล้วสลับเป็น<color=#00F6FF>โหมดมือเปล่า</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: เก็บร่มกลับมา ทำดาเมจ <color=#00F6FF>640%</color> ไปตามเส้นทาง แล้วสลับเป็น<color=#00F6FF>โหมดถือร่ม</color>\nทุกครั้งที่ร่มถูกทับหรือเอาออก จะสลับเป็น<color=#00F6FF>โหมดถือร่ม</color> เมื่อถูกศัตรูทับ คูลดาวน์สกิลจะ <color=#00F6FF>+1</color> รอบ",
  str_skill_desc_3001560 = "<color=#00F6FF>โหมดถือร่ม</color>: เลือก 1 ช่องที่เดินไปถึงได้แล้วปาร่มลงบนช่องนั้น ทำดาเมจ <color=#00F6FF>80%</color> ไปตามเส้นทาง แล้วสลับเป็น<color=#00F6FF>โหมดมือเปล่า</color>\n<color=#00F6FF>โหมดมือเปล่า</color>: เก็บร่มกลับมา ทำดาเมจ <color=#00F6FF>640%</color> ไปตามเส้นทาง แล้วสลับเป็น<color=#00F6FF>โหมดถือร่ม</color>\nทุกครั้งที่ร่มถูกทับหรือเอาออก จะสลับเป็น<color=#00F6FF>โหมดถือร่ม</color> เมื่อถูกศัตรูทับ คูลดาวน์สกิลจะ <color=#00F6FF>+1</color> รอบ",
