  str_skill_upgrade_desc_16016713 = "สุ่มรับ<link=\"30059\"><#FFAE07><u>ไพ่แห่งต้นกำเนิด</u></color></link> <color=#00F6FF>2</color> ใบเมื่อเริ่มการต่อสู้",
  str_skill_upgrade_desc_16016716 = "เสริมพลังสกิลสำรับไพ่ต้นกำเนิด: สีสันผันแปรฟื้นฟูสุขภาพจิต <color=#00F6FF>25%</color>",
  str_skill_name_3001670 = "ทางผ่านดารา",
  str_skill_desc_3001670 = "ออโรเรียน<color=#00F6FF>ที่อยู่ตำแหน่งสุดท้ายของทีม</color>จะเพิ่ม ATK เท่ากับ <color=#00F6FF>7%</color> ของ ATK พื้นฐานของเจโน่",
