  str_skill_desc_2001712 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปบวก</color>",
  str_skill_desc_2001713 = "ทำดาเมจ <color=#00F6FF>{1}%</color> <color=#00F6FF>เป็นรูปบวกไปจนสุดสนามรบ</color>",
  str_skill_desc_2201711 = "สร้างความเสียหาย <color=#00F6FF>{1}%</color> ให้กับ <color=#00F6FF>8 ไทล์ในรูปกากบาท</color> ซึ่งจะกระจายไปยังอีก 1 ไทล์ทางด้านซ้ายและด้านขวาเมื่อถูกบล็อก .",
  str_skill_desc_2201712 = "สร้างความเสียหาย <color=#00F6FF>{1}%</color> ให้กับ <color=#00F6FF>12 ไทล์ในรูปกากบาท</color> ซึ่งจะกระจายไปยังอีก 1 ไทล์ทางด้านซ้ายและด้านขวาเมื่อถูกบล็อก .",
  str_skill_desc_2201713 = "สร้างความเสียหาย <color=#00F6FF>{1}%</color> ดาเมจ <color=#00F6FF>เป็นรูปกากบาทจนถึงระยะสูงสุด</color> ซึ่งจะกระจายไปยังอีก 1 ไทล์ทางด้านซ้ายและด้านขวาเมื่อ ถูกบล็อก",
  str_skill_desc_3001711 = "ค่าใช้จ่าย <color=#00F6FF>2</color> <link=\"30063\"><#FFAE07><u>Trigger Points</u></color></link> และล้างคะแนนที่เหลือ สร้างความเสียหาย <color=#00F6FF>200%</color> ให้กับ <color=#00F6FF>คลัสเตอร์รอบข้าง 1 อัน</color> หลังจากการโจมตีแบบ Chain Combo ของรอบนี้สิ้นสุดลง ความเสียหายสุดท้ายเพิ่มขึ้น <color=#00F6FF>20%</color> สำหรับทุกจุดทริกเกอร์ที่เคลียร์",
  str_skill_desc_3021711 = "ค่าใช้จ่าย <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Trigger Points</u></color></link> และล้างคะแนนที่เหลือ สร้างความเสียหาย <color=#00F6FF>200%</color> ให้กับ <color=#00F6FF>คลัสเตอร์รอบข้าง 1 อัน</color> หลังจากการโจมตีแบบ Chain Combo ของรอบนี้สิ้นสุดลง ความเสียหายสุดท้ายเพิ่มขึ้น <color=#00F6FF>20%</color> สำหรับทุกจุดทริกเกอร์ที่เคลียร์",
  str_skill_desc_3051711 = "ค่าใช้จ่าย <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Trigger Points</u></color></link> และล้างคะแนนที่เหลือ สร้างความเสียหาย <color=#00F6FF>200%</color> ให้กับ <color=#00F6FF>คลัสเตอร์รอบข้าง 1 อัน</color> หลังจากการโจมตีแบบ Chain Combo ของรอบนี้สิ้นสุดลง ความเสียหายสุดท้ายเพิ่มขึ้น <color=#00F6FF>25%</color> สำหรับทุกจุดทริกเกอร์ที่เคลียร์",
  str_skill_passive_desc_400171 = "พบ 1 <color=#00F6FF>จุดอ่อนของฝ่ายตรงข้าม</color> เมื่อเชื่อมต่อ 1 ไทล์สีเขียวหรือไทล์ Enhanced หลังจากตรวจพบจุดอ่อน 6 จุด การโจมตีปกติครั้งต่อไปจะสร้างความเสียหายคริติคอลแบบสุ่มจาก <color=#00F6FF>120%-{1}</color> รีเซ็ตสแต็คของ <color=#00F6FF>จุดอ่อนของคู่ต่อสู้</color>",
  str_skill_passive_desc_430171 = "จุด 1 <color=#00F6FF>จุดอ่อน</color> เมื่อเชื่อมต่อ 1 ไทล์สีเขียวหรือไทล์ที่ปรับปรุง หลังจากตรวจพบจุดอ่อน 6 จุด การโจมตีปกติครั้งถัดไปจะสร้างความเสียหายคริติคอลแบบสุ่มจาก <color=#00F6FF>120%-{1}</color> รีเซ็ตสแต็คของ <color=#00F6FF>จุดอ่อน</color> และได้รับ 1 จุดทริกเกอร์",
  str_skill_upgrade_desc_15017112 = "การปรับปรุงทักษะที่ใช้งาน: ได้รับ <color=#00F6FF>2</color> จุดทริกเกอร์เพิ่มเติมเมื่อเริ่มการต่อสู้แต่ละครั้ง",
  str_skill_upgrade_desc_15017115 = "Active Skill Enhancement: ความเสียหายสุดท้ายเพิ่มขึ้น <color=#00F6FF>25%</color> สำหรับทุกจุดทริกเกอร์ที่เคลียร์",
  str_skill_name_2001701 = "ไฟไหม้หนัก",
