  str_skill_desc_212005011 = "สร้างความเสียหายแก่เป้าหมายที่อยู่ในระยะและกระเด็นกลับ",
  str_skill_name_212005012 = "คมเขี้ยวสังหารหมู่",
  str_skill_desc_212005012 = "ทำดาเมจใส่เป้าหมายในระยะโจมตี",
