  str_skill_desc_30017511 = "สิ้นเปลือง1 <link=\"30069\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส",
  str_skill_desc_30317511 = "สิ้นเปลือง1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่มีอยู่แล้วบนสนามและดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่ในสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส",
  str_skill_desc_30617511 = "บริโภค 1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30073\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่มีอยู่แล้วบนสนามและดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่ในสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส",
  str_skill_desc_32017511 = "สิ้นเปลือง1 <link=\"30069\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่มีอยู่แล้วบนสนามและดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่ในสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์",
  str_skill_desc_32317511 = "สิ้นเปลือง1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์",
  str_skill_desc_32617511 = "สิ้นเปลือง1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30073\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์",
  str_skill_desc_33017511 = "สิ้นเปลือง1 <link=\"30069\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์ Axelia สามารถใช้ <link=\"30071\"><#FFAE07><u>โมดูลสิทธิ์</u></color></link> เพื่ออัญเชิญวัตถุอัญเชิญของทักษะเรียกใช้ของ Thunder Aurorians อื่น ๆ",
  str_skill_desc_33317511 = "สิ้นเปลือง1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30072\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์ Axelia สามารถใช้ <link=\"30071\"><#FFAE07><u>โมดูลสิทธิ์</u></color></link> เพื่ออัญเชิญวัตถุอัญเชิญของทักษะเรียกใช้บางอย่างของ Thunder Aurorians",
  str_skill_desc_33617511 = "สิ้นเปลือง1 <link=\"30070\"><#FFAE07><u>พลังงานลูกบาศก์</u></color></link> อัญเชิญ 1 <link=\"30073\"><#FFAE07><u>ฮีลลิ่งออร์บ</u></color></link> บนไทล์ที่เคลื่อนที่ได้ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP ตามจำนวนรอบที่อยู่บนสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์ Axelia สามารถใช้ <link=\"30071\"><#FFAE07><u>โมดูลสิทธิ์</u></color></link> เพื่ออัญเชิญวัตถุอัญเชิญของทักษะเรียกใช้ของ Thunder Aurorians อื่น ๆ",
  str_skill_desc_330175111 = "สิ้นเปลือง1 <color=#D1970C><b>พลังงานลูกบาศก์</b></color> เพื่อเรียก Healing Orb 1 ชิ้นบนไทล์ที่เคลื่อนที่ได้ ซึ่งจะฟื้นฟู HP เท่ากับ <color=#D1970C><b>40%/100%/200%</b></color> ของ ATK ของ Axelia ต่อ Aurorians ที่ผ่านลูกกลมนี้หลังจากที่มันอยู่ในสนามเป็นเวลา <color=#D1970C><b>0/1/2</b></color> รอบ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP เท่ากับ <color=#D1970C><b>40%/100%/200%</b></color> ของ ATK ของ Axelia ตามจำนวนรอบที่ลงสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์",
  str_skill_desc_336175111 = "สิ้นเปลือง1 <color=#D1970C><b>พลังงานลูกบาศก์</b></color> เพื่อเรียก Healing Orb 1 ชิ้นบนไทล์ที่เคลื่อนที่ได้ ซึ่งจะฟื้นฟู HP เท่ากับ <color=#D1970C><b>40%/100%/250%</b></color> ของ ATK ของ Axelia ต่อ Aurorians ที่ผ่านลูกกลมนี้หลังจากที่มันอยู่ในสนามเป็นเวลา <color=#D1970C><b>0/1/2</b></color> รอบ หรือเลือก Healing Orb ที่อยู่ในสนามแล้วดูดซับเพื่อฟื้นฟู HP เท่ากับ <color=#D1970C><b>80%/180%/400%</b></color> ของ ATK ของ Axelia ตามจำนวนรอบที่ลงสนาม Healing Orb จะหายไปเมื่อถูกศัตรูสัมผัส โดยคืนพลังงาน 1 ลูกบาศก์ต่อลูกบาศก์",
  str_skill_passive_name_4101751 = "ลูกบาศก์สวิตช์",
  str_skill_passive_desc_4101751 = "หลังจากที่ Thunder Aurorian ในทีมใช้ Active Skill Axelia จะได้รับ <color=#00F6FF>1</color> กองพลังงานการแปลง การใช้คอมโบแบบต่อเนื่องจะล้างกองพลังงานการแปลงและข้อเสนอทั้งหมด <color=#00F6FF>{1}</color> สร้างความเสียหายต่อศัตรูที่มี HP สูงสุดในสนาม",
  str_skill_name_2001751 = "พรสวรรค์",
  str_skill_name_2001752 = "พรสวรรค์",
  str_skill_name_2001753 = "พรสวรรค์",
  str_skill_desc_2001751 = "ฟื้นฟู HP ของทีมโดย <color=#00F6FF>135%</color> ATK ของ Axelia",
  str_skill_desc_2001752 = "ฟื้นฟู HP ของทีมโดย <color=#00F6FF>160%</color> ATK ของ Axelia",
  str_skill_desc_2001753 = "ฟื้นฟู HP ของทีมโดย <color=#00F6FF>190%</color> ATK ของ Axelia",
  str_skill_name_29036011 = "การกัดกร่อน",
  str_skill_desc_29036011 = "สร้างความเสียหายรุนแรงแก่เป้าหมายเมื่อ Aurorian อยู่ใน 1 กลุ่มรอบๆ ของ Diavola และสร้างพิษ",
  str_skill_name_29036012 = "ล่อหนอน",
  str_skill_desc_29036012 = "เมื่อ Aurorians ออกห่างจาก Diavola เหล่า Dawn Sprite จะถูกอัญเชิญไปยังตำแหน่งสุ่มบนสนาม",
  str_skill_name_20006091 = "การเสริมพลัง",
  str_skill_desc_20006091 = "เมื่ออยู่ใน 1 กลุ่มรอบๆ ของ Diavola เพิ่มการโจมตีของ Diavola โดยการรวมเข้ากับมัน",
  str_skill_name_200190101 = "วิญญาณโคมไฟ: ลิงค์",
  str_skill_desc_200190101 = "หาก Lantern Spirit สามารถเคลื่อนที่ผ่าน Aurorian เมื่อมันโจมตี มันจะสร้างความเสียหายและสร้างการเชื่อมโยงกับ Aurorian มิฉะนั้นจะสร้างความเสียหายให้กับ Aurorian เท่านั้น และได้รับ ACT boost",
  str_skill_name_290340101 = "Asmodeus: ห่วงโซ่แห่งฝันร้าย",
  str_skill_desc_290340101 = "Asmodeus โจมตี Aurorian ทั้งหมดที่อยู่ในระยะ เชื่อมโยงตัวเองเข้ากับพวกเขาด้วย Chain of Nightmares Aurorians ที่เชื่อมโยงกับ Chain of Nightmares จะได้รับความเสียหายทุกๆ 1 ช่องที่พวกเขาสำรวจ หาก Aurorian เชื่อมโยงกับ Chain of Nightmares อยู่แล้วเมื่อ Asmodeus โจมตี เธอจะสร้างความเสียหายได้มากขึ้นและได้รับ Life Drain",
  str_skill_name_290341101 = "Asmodeus: ห่วงโซ่แห่งฝันร้าย",
  str_skill_desc_290341101 = "Asmodeus โจมตี Aurorians ทั้งหมดที่อยู่ในระยะ เชื่อมโยงตัวเองเข้ากับพวกเขาด้วย Chain of Nightmares เมื่อ Chain of Nightmares ถูกทำลาย มันจะสร้างความเสียหายอย่างสูงต่อ Aurorians หาก Aurorian เชื่อมโยงกับ Chain of Nightmares อยู่แล้วเมื่อ Asmodeus โจมตี เธอจะสร้างความเสียหายได้มากขึ้นและได้รับ Life Drain",
  str_skill_name_290340102 = "Asmodeus: การทำให้เข้มข้นขึ้น",
  str_skill_desc_290340102 = "หาก Asmodeus ไม่สามารถโจมตี Aurorian ใด ๆ ได้ ACT ของเธอจะเพิ่มขึ้นเรื่อย ๆ จนกว่าเธอจะโจมตี Aurorian",
  str_skill_name_290340201 = "Asmodeus: เปลวเพลิง",
  str_skill_desc_290340201 = "Asmodeus เทเลพอร์ตไปยังช่องที่ไกลที่สุดที่เธอสามารถโจมตี Aurorians และโจมตีพวกมันได้",
