  str_skill_name_22017713 = "เวอร์ทูโอซิกเรโซแนนซ์",
  str_skill_name_300177 = "โซปราโนกะ",
  str_skill_name_303177 = "โซปราโนกะ",
  str_skill_name_306177 = "โซปราโนกะ",
  str_skill_name_3061771 = "โซปราโนกะ",
  str_skill_name_330177 = "โซปราโนกะ",
  str_skill_name_333177 = "โซปราโนกะ",
  str_skill_name_336177 = "โซปราโนกะ",
  str_skill_name_3361771 = "โซปราโนกะ",
  str_skill_passive_name_410177 = "Euphonic Aria",
  str_skill_desc_2001771 = "<color=#00F6FF>โหมดไอดอล (5 เชน)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>140%</color> ของ ATK ของ Goldie\n<color=#00F6FF>โหมด Warsong (7-Chain)</color>: ข้อเสนอ <color=#00F6FF>120%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_2001772 = "<color=#00F6FF>โหมดไอดอล (9 เชน)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>170%</color> ของ ATK ของ Goldie\n<color=#00F6FF>โหมดวอร์ซอง (11-Chain)</color>: ข้อเสนอ <color=#00F6FF>150%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_2001773 = "<color=#00F6FF>โหมดไอดอล (13-Chain)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>210%</color> ของ ATK ของ Goldie\n<color=#00F6FF>โหมด Warsong (15-Chain)</color>: ข้อเสนอ <color=#00F6FF>180%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_2201771 = "<color=#00F6FF>โหมดไอดอล (5 เชน)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>140%</color> ของ ATK ของ Goldie และสร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>1</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>.\n<color=#00F6FF>โหมด Warsong (7-Chain)</color>: ข้อเสนอ <color=#00F6FF>120%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_2201772 = "<color=#00F6FF>โหมดไอดอล (9 เชน)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>170%</color> ของ ATK ของ Goldie และสร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>.\n<color=#00F6FF>โหมดวอร์ซอง (11-Chain)</color>: ข้อเสนอ <color=#00F6FF>150%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_2201773 = "<color=#00F6FF>โหมดไอดอล (13-Chain)</color>: ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>210%</color> ของ ATK ของ Goldie และสร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>3</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>.\n<color=#00F6FF>โหมด Warsong (15-Chain)</color>: ข้อเสนอ <color=#00F6FF>180%</color> สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>.",
  str_skill_desc_300177 = "ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>.\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถโจมตีปกติได้ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_303177 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>.\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถจัดการการโจมตีปกติ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_306177 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>. หาก Active Skill ของเธอพร้อมในรอบที่แล้ว เอฟเฟกต์ที่กล่าวถึงข้างต้นจะมีผลในช่วง Aurora Time ด้วย\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถจัดการการโจมตีปกติ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_3061771 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>. หาก Active Skill ของเธอพร้อมในรอบที่แล้ว เอฟเฟกต์ที่กล่าวถึงข้างต้นจะมีผลในช่วง Aurora Time ด้วย\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถโจมตีปกติได้ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_330177 = "ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>และไทล์ที่ได้รับการปรับปรุงทั้งหมดจะถือว่าเป็นไทล์สีชั่วคราว\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถจัดการการโจมตีปกติ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_333177 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>และไทล์ที่ได้รับการปรับปรุงทั้งหมดจะถือว่าเป็นไทล์สีชั่วคราว\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถโจมตีปกติได้ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_336177 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>และไทล์ที่ได้รับการปรับปรุงทั้งหมดจะถือว่าเป็นไทล์สีชั่วคราว หาก Active Skill ของเธอพร้อมในรอบที่แล้ว เอฟเฟกต์ที่กล่าวถึงข้างต้นจะมีผลในช่วง Aurora Time ด้วย\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถโจมตีปกติได้ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_desc_3361771 = "สร้าง <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> บน <color=#00F6FF>2</color> สุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>. ถ้าโกลดี้เปลี่ยนจาก <color=#00F6FF>โหมดไอดอล</color> ถึง <color=#00F6FF>โหมดวอร์ซอง</color> รอบนี้กระเบื้องที่ศัตรูยืนอยู่ <color=#00F6FF>สามารถเชื่อมต่อ</color>และไทล์ที่ได้รับการปรับปรุงทั้งหมดจะถือว่าเป็นไทล์สีชั่วคราว หาก Active Skill ของเธอพร้อมในรอบที่แล้ว เอฟเฟกต์ที่กล่าวถึงข้างต้นจะมีผลในช่วง Aurora Time ด้วย\n<color=#00F6FF>โหมดไอดอล</color>: ไม่สามารถจัดการการโจมตีปกติได้ Chain Combo จะฟื้นฟู HP\n<color=#00F6FF>โหมดวอร์ซอง</color>: สามารถจัดการการโจมตีปกติ Chain Combo สร้างความเสียหายให้กับ <color=#00F6FF>ศัตรูทั้งหมด</color>แต่ต้องใช้ไทล์ +2 เพื่อเปิดใช้งาน",
  str_skill_passive_desc_410177 = "เมื่อใดก็ตามที่ทีมได้รับ <color=#00F6FF>{1}</color> <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> (รวมถึงทาง <link=\"30065\"><#FFAE07><u>การดูดซึม</u></color></link>) สร้างไทล์ที่ปรับปรุงแล้ว 1 อันในที่ใกล้ที่สุด <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>.",
  str_skill_upgrade_desc_16017713 = "Active Skill Enhancement: เปลี่ยน Active Skill เป็น <color=#FFFF00>การนัดหยุดงานล่วงหน้า</color>. ใช้ได้เมื่อเข้าสู่การต่อสู้ สร้าง <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link> แบบสุ่ม <color=#00F6FF>กระเบื้องที่ไม่ใช่สีเขียว</color>.",
  str_skill_upgrade_desc_16017716 = "Active Skill Enhancement: คูลดาวน์สกิล <color=#FFFF00>-1</color> หาก Active Skill พร้อมในรอบที่แล้ว ในโหมด Warsong กระเบื้องที่ศัตรูยืนอยู่จะเชื่อมต่อได้ในช่วง <color=#00F6FF>Aurora Time</color> และ <link=\"20001\"><#FFAE07 <u>ไทล์ที่ปรับปรุงแล้ว</u></color></link>จะถือว่าเป็นไทล์สี (ใช้ได้สำหรับการเสด็จขึ้นสู่สวรรค์ III)",
  str_skill_desc_290420101 = "เคลื่อนเข้าหา Aurorians และเหวี่ยงแขนของมันเพื่อสร้างความเสียหายแก่ศัตรูในระยะ 2 ช่องด้านหน้า",
  str_skill_desc_290420102 = "สร้างความเสียหายแก่ศัตรูทั้งหมดในสนาม",
  str_skill_name_200200101 = "Venomex Ball",
  str_skill_desc_200200101 = "พ่น Venomex Ball ออกมา สร้างความเสียหายแก่เป้าหมายที่อยู่ในระยะ ลูกบอลกระเด็นข้ามแผ่นกระเบื้อง 4 แผ่นเป็นรูปกากบาท ทำให้ศัตรูและพันธมิตรทั้งหมดในระยะสาดพิษเป็นพิษ",
  str_skill_name_200210001 = "การลอบสังหารโคเซ็น",
  str_skill_desc_200210001 = "เมื่อการนับถอยหลังของ Crud สิ้นสุดลง Cozen ก็กระโดดออกมาเพื่อโจมตี Aurorian ก่อนจะกลับเข้าไปซ่อนตัว",
  str_skill_name_200210101 = "การลอบสังหารโคเซ็น",
  str_skill_desc_200210101 = "เมื่อการนับถอยหลังของ Crud สิ้นสุดลง Cozen ก็กระโดดออกมาเพื่อโจมตี Aurorian ก่อนจะกลับเข้าไปซ่อนตัว",
  str_skill_name_200210102 = "การลอบสังหารโคเซ็น",
  str_skill_desc_200210102 = "เมื่อการนับถอยหลังของ Crud สิ้นสุดลง Cozen ก็กระโดดออกมาเพื่อโจมตี Aurorian ก่อนจะกลับเข้าไปซ่อนตัว",
  str_skill_name_290400101 = "เบนนู แบช",
  str_skill_desc_290400101 = "Bennuguardian ใช้กรงเล็บของมันสร้างความเสียหายแก่เป้าหมายที่อยู่ในพื้นที่โจมตี",
  str_skill_name_290400102 = "เบนนู ลีป",
  str_skill_desc_290400102 = "Bennuguardian กระโดดเข้าหาเป้าหมาย ทุบพื้นเมื่อมันตกลงมา สร้างความเสียหายอย่างใหญ่หลวงแก่เป้าหมายใน 1 กลุ่มรอบๆ",
  str_skill_name_290400103 = "เบนนู ฟิวรี่",
  str_skill_desc_290400103 = "Bennuguardian ที่โกรธเกรี้ยวปลดปล่อยทักษะอันทรงพลังที่สร้างความเสียหายให้กับทุกเป้าหมายในสนาม",
  str_skill_name_5220012 = "ฮีลลิ่งเจล",
  str_skill_desc_5220012 = "คืนค่า <color=#00F6FF>20%</color> Max HP ของทีม",
  str_skill_name_5220013 = "ตัววิเคราะห์เส้นทาง",
  str_skill_desc_5220013 = "เปิดใช้งานอุปกรณ์และเทเลพอร์ตไปยังไทล์ที่สำรวจได้",
  str_skill_name_290430101 = "Regal: ความวุ่นวาย",
  str_skill_desc_290430101 = "Regal เคลื่อนที่เข้าใกล้เป้าหมายโดยเชื่อมต่อชิ้นส่วนของสององค์ประกอบ: ของเขาเองและของ Aurorian ในตำนานอีกคนในสนาม จากนั้นเขาจะโจมตีปกติใน 8 ทิศทาง จากนั้นหลังจากโซ่สิ้นสุด สร้างความเสียหายให้กับ 1 กลุ่มที่อยู่รอบๆ",
  str_skill_name_290440101 = "บังสุกุล: หอกศักดิ์สิทธิ์",
  str_skill_desc_290440101 = "Requiem เคลื่อนที่เข้าใกล้เป้าหมายโดยเชื่อมต่อชิ้นส่วนของสององค์ประกอบ: ของเธอเองและของ Aurorian ในตำนานอีกคนในสนาม จากนั้นเธอจะทำการโจมตีปกติใน 4 ทิศทาง จากนั้นหลังจากโซ่สิ้นสุดลง จะสร้างความเสียหายให้กับ 1 กลุ่มที่อยู่รอบๆ ทุก ๆ การโจมตีปกติ 3 ครั้ง เธอสร้างความเสียหายเพิ่มเติมเท่ากับเปอร์เซ็นต์ของ Max HP ของเป้าหมาย",
  str_skill_name_290450101 = "Frostfire: การสูญพันธุ์",
  str_skill_desc_290450101 = "Frostfire เคลื่อนที่ออกห่างจากเป้าหมายโดยการเชื่อมต่อชิ้นส่วนของสององค์ประกอบ: ของเธอเองและของ Aurorian ในตำนานอีกคนในสนาม หลังจากเคลื่อนไหว เธอจะสร้างความเสียหายให้กับเป้าหมายทั้งหมดบนสนาม",
  str_skill_name_290460101 = "มิธอส: เรือนยอดสูงตระหง่าน",
  str_skill_desc_290460101 = "มิธอสเคลื่อนที่ออกห่างจากเป้าหมายโดยเชื่อมต่อชิ้นส่วนของสององค์ประกอบ: ของเธอเองและของ Aurorian ในตำนานอีกคนหนึ่งบนสนาม หลังจากเคลื่อนที่ สร้างความเสียหายให้กับเป้าหมายทั้งหมดบนสนาม",
  str_skill_name_2801101 = "เครื่องหมายคำสั่ง",
  str_skill_desc_2801101 = "ดูดซับโดย Aurorians เมื่อพวกเขาผ่าน เพิ่มจำนวนครั้งที่สามารถเปลี่ยนกัปตันได้",
  str_skill_name_5000881 = "คมดาบ",
  str_skill_desc_5000881 = "ดูดซับโดย Aurorians เมื่อผ่านมัน เพิ่ม Aurorian ATK",
  str_skill_name_5000891 = "โล่",
  str_skill_desc_5000891 = "ดูดซับโดย Aurorians เมื่อผ่านมัน เพิ่ม Aurorian DEF",
  str_skill_name_2002101 = "บัฟดาบ",
  str_skill_desc_2002101 = "หลังจากหยิบขึ้นมา ทำให้ติดสถานะ Silence แต่เพิ่ม ATK อย่างมาก",
  str_skill_desc_2002201 = "หลังจากหยิบขึ้นมาแล้ว เพิ่มความเสียหายของ Chain Combo 8%",
  str_skill_upgrade_desc_15018312 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_15018315 = "Active Skill Enhancement: จำนวนครั้งของเอฟเฟกต์ซ้ำจะเพิ่มขึ้นเป็น <color=#00F6FF>2-5</color> ครั้ง. (ใช้ได้สำหรับ Ascension III)",
  str_skill_name_3001831 = "ระหว่างชีวิตและความตาย",
  str_skill_name_3051831 = "ระหว่างชีวิตและความตาย",
  str_skill_name_3201831 = "ระหว่างชีวิตและความตาย",
  str_skill_name_3251831 = "ระหว่างชีวิตและความตาย",
  str_skill_desc_3001831 = "เลือกศัตรู 1 ตัวและบังคับให้ HP เป็น <color=#00F6FF>ไม่น้อยกว่า 1</color> ก่อนที่รอบศัตรูจะเริ่มขึ้น ศัตรูที่เป็นเป้าหมายจะสุ่มได้รับผลอย่างใดอย่างหนึ่งต่อไปนี้: ความเสียหายสุดท้ายที่ได้รับจาก <color=#00F6FF>การโจมตีปกติ/คอมโบต่อเนื่อง/สกิลเรียกใช้</color> เพิ่มขึ้นโดย <color=#00F6FF>5%/5%/7%</color>.",
  str_skill_desc_3201831 = "เลือกศัตรู 1 ตัวและบังคับให้ HP เป็น <color=#00F6FF>ไม่น้อยกว่า 1</color> ก่อนที่รอบศัตรูจะเริ่มขึ้น ศัตรูที่เป็นเป้าหมายจะสุ่มได้รับผลอย่างใดอย่างหนึ่งต่อไปนี้: ความเสียหายสุดท้ายที่ได้รับจาก <color=#00F6FF>การโจมตีปกติ/คอมโบต่อเนื่อง/สกิลใช้งาน</color> เพิ่มขึ้นโดย <color=#00F6FF>5%/5%/7%</color>. เอฟเฟ็กต์ซ้ำ <color=#00F6FF>1 ถึง 3</color> ครั้ง.",
  str_skill_desc_3251831 = "เลือกศัตรู 1 ตัวและบังคับให้ HP เป็น <color=#00F6FF>ไม่น้อยกว่า 1</color> ก่อนที่รอบศัตรูจะเริ่มขึ้น ศัตรูที่เป็นเป้าหมายจะสุ่มได้รับผลอย่างใดอย่างหนึ่งต่อไปนี้: ความเสียหายสุดท้ายที่ได้รับจาก <color=#00F6FF>การโจมตีปกติ/คอมโบต่อเนื่อง/สกิลใช้งาน</color> เพิ่มขึ้นโดย <color=#00F6FF>5%/5%/7%</color>. เอฟเฟ็กต์ซ้ำ <color=#00F6FF>2 ถึง 5</color> ครั้ง.",
  str_skill_name_2001831 = "เที่ยวบินรักษา",
  str_skill_name_2001832 = "เที่ยวบินรักษา",
  str_skill_name_2001833 = "เที่ยวบินรักษา",
  str_skill_desc_2001831 = "ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>155%</color> ของ ATK ของ Liqing",
  str_skill_desc_2001832 = "ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>190%</color> ของ ATK ของ Liqing",
  str_skill_desc_2001833 = "ฟื้นฟู HP ของทีมเป็นจำนวนเท่ากับ <color=#00F6FF>225%</color> ของ ATK ของ Liqing",
  str_skill_passive_desc_410183 = "การโจมตีปกติของ Liqing จะไม่สร้างความเสียหายโดยตรงอีกต่อไป แต่จะใช้ Moxa 1 กองกับเป้าหมายแทน ในตอนท้ายของเทิร์น Moxa จะระเบิดและจัดการ <color=#00F6FF>{1}</color> ความเสียหายต่อกอง Moxa ใช้งานได้นาน <color=#00F6FF>2 รอบ</color>. แต่ละกองจะคำนวณแยกกัน",
  str_skill_passive_desc_430183 = "การโจมตีปกติของ Liqing จะไม่สร้างความเสียหายโดยตรงอีกต่อไป แต่จะใช้ Moxa 1 กองกับเป้าหมายแทน ในตอนท้ายของเทิร์น Moxa จะระเบิดและจัดการ <color=#00F6FF>{1}</color> ความเสียหายต่อกอง แต่ละกองของ Moxa บนเป้าหมายจะเพิ่มความเสียหายขั้นสุดท้ายที่ทำได้ <color=#00F6FF>3%</color>. Moxa ใช้งานได้นาน <color=#00F6FF>2 รอบ</color>. แต่ละกองจะคำนวณแยกกัน",
  str_skill_passive_name_410183 = "ม็อกซาแห่งความตาย",
