  str_skill_name_20019333 = "กระแสเรเดียล",
  str_skill_name_2201931 = "กระแสเรเดียล",
  str_skill_name_2201932 = "กระแสเรเดียล",
  str_skill_name_2201933 = "กระแสเรเดียล",
  str_skill_name_3001931 = "สู่สรวงสวรรค์",
  str_skill_name_3051931 = "สู่สรวงสวรรค์",
  str_skill_name_3301931 = "สู่สรวงสวรรค์",
