  str_skill_desc_2201992 = "ข้อเสนอ <color=#00F6FF>{1}%</color> สร้างความเสียหายให้กับศัตรูที่มี HP สูงสุดและมีบาดแผลเปิดมากที่สุด หรือโจมตีศัตรูที่ใกล้ที่สุด",
  str_skill_desc_2201993 = "ข้อเสนอ <color=#00F6FF>{1}%</color> สร้างความเสียหายให้กับศัตรูที่มี HP สูงสุดและมีบาดแผลเปิดมากที่สุด หรือโจมตีศัตรูที่ใกล้ที่สุด",
  str_skill_name_3001991 = "เสียงสะท้อนของสวรรค์",
  str_skill_desc_3001991 = "แปลงกระเบื้องที่เลือก 1 แผ่นเป็นสีเหลือง <link=\"30080\"><#FFAE07><u>กระเบื้องปริซึมรูปกากบาท</u></color></link>.",
  str_skill_passive_name_410199 = "โหลดซ้ำพิเศษ",
  str_skill_passive_name_420199 = "โหลดซ้ำพิเศษ",
  str_skill_passive_name_430199 = "โหลดซ้ำพิเศษ",
  str_skill_passive_name_436199 = "โหลดซ้ำพิเศษ",
  str_skill_passive_desc_410199 = "การโจมตีปกติของ Yingel สร้างความเสียหายทุกๆ <color=#00F6FF>ที่สอง</color> การโจมตีปกติ ตัวคูณความเสียหายเพิ่มขึ้นเป็น <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420199 = "การโจมตีปกติของ Yingel สร้างความเสียหายทุกๆ <color=#00F6FF>ที่สอง</color> การโจมตีปกติ ตัวคูณความเสียหายเพิ่มขึ้นเป็น <color=#00F6FF>{1}</color> และทำดาเมจ 1 Open Wound สูงสุด 20 สแต็ค สำหรับทุกๆ บาดแผลเปิดที่เป้าหมายมี ดาเมจสุดท้ายของ Yingel's Chain Combo จะเพิ่มขึ้น <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430199 = "การโจมตีปกติของ Yingel สร้างความเสียหายทุกๆ <color=#00F6FF>ที่สอง</color> การโจมตีปกติ ตัวคูณความเสียหายเพิ่มขึ้นเป็น <color=#00F6FF>{1}</color> และทำดาเมจ 1 Open Wound สูงสุด 20 สแต็ค ทุก ๆ บาดแผลเปิดที่เป้าหมายมี การโจมตีของ Yingel จะเพิกเฉย <color=#00F6FF>3%</color> ค่า DEF ของพวกเขาและความเสียหายสุดท้ายของ Chain Combo จะเพิ่มขึ้น <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_436199 = "การโจมตีปกติของ Yingel สร้างความเสียหายทุกๆ <color=#00F6FF>ที่สอง</color> การโจมตีปกติ ตัวคูณความเสียหายเพิ่มขึ้นเป็น <color=#00F6FF>{1}</color> และทำดาเมจ 1 Open Wound สูงสุด 20 สแต็ค ทุก ๆ บาดแผลเปิดที่เป้าหมายมี การโจมตีของ Yingel จะเพิกเฉย <color=#00F6FF>5%</color> ค่า DEF ของพวกเขาและความเสียหายสุดท้ายของ Chain Combo จะเพิ่มขึ้น <color=#00F6FF>3%</color>.",
  str_skill_desc_1601751002 = "กระเบื้องปริซึมรูปกากบาท",
  str_skill_desc_160175102 = "บริโภค <color=#00F6FF>3</color> พลังงานลูกบาศก์เพื่อแปลงไทล์ 1 อันใด ๆ ให้เป็นไทล์ปริซึมรูปกากบาท",
  str_skill_name_3400231 = "โซนาตาแห่ง Abyss Variant I",
  str_skill_name_3430231 = "โซนาตาแห่ง Abyss Variant I",
  str_skill_name_3400232 = "โซนาตาแห่ง Abyss Variant II",
  str_skill_name_3430232 = "โซนาตาแห่ง Abyss Variant II",
  str_skill_desc_3400231 = "<color=#FFFF00>คูลดาวน์สกิล -2 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>250%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด ตัวแปรนี้ไม่สามารถเรียกใช้เอฟเฟคที่ทำให้ตกใจของสกิลอุปกรณ์ได้",
  str_skill_desc_3430231 = "<color=#FFFF00>คูลดาวน์สกิล -2 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>250%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด ตัวแปรนี้ไม่สามารถเรียกใช้เอฟเฟคที่ทำให้ตกใจของสกิลอุปกรณ์ได้",
  str_skill_desc_3400232 = "<color=#FFFF00>คูลดาวน์สกิล +2 หลังจากร่าย</color>. <color=#FFFF00>สร้างความเสียหายแก่ศัตรูทั้งหมดด้วย <link=\"10003\"><#FFAE07><u>ขู่</u></color></link> เป็นเวลา 1 รอบ</color> และข้อตกลง <color=#FFFF00>550%</color> สร้างความเสียหายให้กับพวกเขา",
  str_skill_desc_3430232 = "<color=#FFFF00>คูลดาวน์สกิล +2 หลังจากร่าย</color>. <color=#FFFF00>สร้างความเสียหายแก่ศัตรูทั้งหมดด้วย <link=\"10003\"><#FFAE07><u>ขู่</u></color></link> เป็นเวลา 1 รอบ</color> และข้อตกลง <color=#FFFF00>550%</color> สร้างความเสียหายให้กับพวกเขา",
  str_skill_passive_desc_440023 = "ได้รับ Shiver Mark 1 Stack เมื่อใช้ Chain Combo สูงสุด <color=#00F6FF>5</color> กอง แต่ละกองจะเพิ่มความเสียหายของ Active Skill โดย <color=#00F6FF>20%</color>. การใช้ Active Skill จะสร้างความเสียหาย <link=\"10003\"><#FFAE07><u>ขู่</u></color></link> ในจำนวนศัตรูที่เทียบเท่ากับจำนวนกองสำหรับ <color=#00F6FF>1</color> กลม. การเปิดใช้งาน Active Skill <color=#00F6FF>ไม่ล้างสแต็ค</color>. หากมีสแต็คครบ 5 อันก่อนที่จะปล่อยสกิล Chain Combo มันจะสร้างความเสียหายเพิ่มเติมให้กับศัตรูที่อยู่ใกล้ที่สุด Connolly สร้างความเสียหายขั้นสุดท้ายเพิ่มอีก 15% <link=\"10003\"><#FFAE07><u>ตระหนก</u></color></link> ศัตรู",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>ใหม่ Active Skill Variant I</color>: <color=#FFFF00>คูลดาวน์สกิล -2 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>250%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด ตัวแปรนี้ไม่สามารถเรียกใช้เอฟเฟคที่ทำให้ตกใจของสกิลอุปกรณ์ได้",
  str_skill_upgrade_refine_desc_16002312 = "การเสริมทักษะอุปกรณ์: ข้อตกลงคอนนอลลี่ <color=#00F6FF>เพิ่มความเสียหายขั้นสุดท้ายอีก 15%</color> ให้กับศัตรูที่ติด Frighten",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>ใหม่ Active Skill Variant II</color>: <color=#FFFF00>คูลดาวน์สกิล +2 หลังจากร่าย</color>. <color=#FFFF00>สร้างความเสียหายแก่ศัตรูทั้งหมดด้วย <link=\"10003\"><#FFAE07><u>ขู่</u></color></link> เป็นเวลา 1 รอบ</color> และข้อตกลง <color=#FFFF00>550%</color> สร้างความเสียหายให้กับพวกเขา",
  str_skill_name_290520101 = "สายฟ้าแลบอันดุร้าย",
  str_skill_desc_290520101 = "เคลื่อนเข้าหา Aurorians และสร้างความเสียหายจำนวนมาก จากนั้นถอยห่างจากเป้าหมาย",
  str_skill_name_290520102 = "สายฟ้าแลบดุร้าย",
  str_skill_desc_290520102 = "สร้างความเสียหายให้กับ Aurorians ทั้งหมดที่อยู่ในระยะหลังจากเคลื่อนที่",
  str_skill_name_200250101 = "วิธีการดับเพลิง",
  str_skill_desc_200250101 = "โจมตีระยะไกลใส่เป้าหมายในระยะโจมตี",
  str_skill_name_200250102 = "มีดจู่โจม",
