  str_skill_name_3420901 = "Sweet Kiss ตัวแปร I",
  str_skill_name_3400902 = "ตัวแปร Sweet Kiss II",
  str_skill_name_3420902 = "ตัวแปร Sweet Kiss II",
  str_skill_desc_3400901 = "<color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>{1}%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด <color=#FFFF00>และทำให้พวกเขามึนงง</color>.",
  str_skill_desc_3420901 = "<color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>{1}%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด <color=#FFFF00>และทำให้พวกเขามึนงง</color>.",
  str_skill_desc_3400902 = "<color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>{1}%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด",
  str_skill_desc_3420902 = "<color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>{1}%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด",
  str_skill_passive_desc_440090 = "เพิ่มความเสียหายของ Barbara ต่อศัตรูที่ครอบครองกระเบื้องสีแดงโดย <color=#00F6FF>10%</color>. สำหรับกระเบื้องสีแดงแต่ละแผ่นที่เท้าของศัตรู โบนัสความเสียหายจะเพิ่มขึ้น <color=#00F6FF>1%</color>. ให้เพื่อนร่วมทีม Fire Aurorian <color=#00F6FF>50%</color> ของโบนัสนี้",
  str_skill_upgrade_refine_desc_15009011 = "การเสริมทักษะอุปกรณ์: ทุกๆ 1 แผ่นสีแดงที่เท้าของศัตรู โบนัสความเสียหายจะเพิ่มขึ้น <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>ใหม่ Active Skill Variant I</color>: <color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>600%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด <color=#FFFF00>และทำให้พวกเขามึนงง</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>ใหม่ Active Skill Variant II</color>: <color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. ข้อเสนอ <color=#FFFF00>450%</color> สร้างความเสียหายแก่ศัตรูทั้งหมด",
  str_skill_name_5000961 = "ผูก",
  str_skill_desc_5000961 = "เมื่อ Aurorians เข้าไปภายใน 2 กลุ่มที่อยู่รอบๆ Spikepest การเชื่อมโยงจะถูกสร้างขึ้นโดยอัตโนมัติระหว่างพวกเขา การเชื่อมโยงขาดเมื่อ Aurorians ย้ายกลุ่มที่อยู่รอบๆ 4 กลุ่มออกจาก Spikepest ในขณะที่เชื่อมโยง Spikepest แบ่งปัน 50% ของความเสียหายที่ผู้เล่นได้รับ",
  str_skill_desc_4001531 = "ร่ายสกิลเพื่อล้มศัตรูภายใน 3 กลุ่มโดยรอบด้วย 1 แผ่นกระเบื้อง และแปลงแผ่นกระเบื้องใต้ศัตรูเป็นแผ่นสีเหลือง",
  str_skill_desc_4001751 = "เมื่อร่ายสกิล ทุกครั้งที่ผู้เล่นได้รับความเสียหายในรอบนี้ กระเบื้อง 1 แผ่นที่มีธาตุเดียวกันกับกัปตันจะถูกรีเฟรช และ HP ของทีมจำนวนเล็กน้อยจะถูกฟื้นฟู",
  str_skill_name_2001921 = "การโจมตีของดาบ",
