  str_skill_desc_2002002 = "ข้อเสนอ <color=#00F6FF>{1}%</color> สร้างความเสียหายแก่ศัตรู 3 ตัวภายใน <color=#00F6FF>4 กระจุกรอบ</color>.",
  str_skill_desc_2002003 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่่อยู่ใกล้ที่สุด",
  str_skill_desc_2102001 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color>",
  str_skill_desc_2102002 = "ข้อเสนอ <color=#00F6FF>{1}%</color> สร้างความเสียหายแก่ศัตรู 3 ตัวภายใน <color=#00F6FF>4 กระจุกรอบ</color>.",
  str_skill_desc_2102003 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่่อยู่ใกล้ที่สุด",
  str_skill_desc_300200 = "เลือกศัตรูได้สูงสุด 2 ตัวผ่านแผ่นกระเบื้องด้านล่าง จัดการ <color=#00F6FF>{1}%</color> สร้างความเสียหายให้กับพวกเขา ศัตรูทั้งหมดบนกระเบื้องที่เลือกและกระเบื้องที่อยู่ระหว่างนั้น <link=\"30081\"><#FFAE07><u>ดึง</u></color></link> สู่ใจกลางของบริเวณนี้ หากเลือกศัตรูเพียงตัวเดียว พวกมันจะได้รับความเสียหายเท่านั้น และจะไม่ถูกดึง",
  str_skill_desc_305200 = "เลือกศัตรูได้สูงสุด 2 คนผ่านไทล์ที่พวกเขาครอบครองและสร้างความเสียหาย <color=#00F6FF>{1}%</color> ให้กับพวกเขา ศัตรูทั้งหมดบนชิ้นส่วนที่เลือกและชิ้นส่วนที่อยู่ระหว่างนั้นจะถูก <link=\"30081\"><#FFAE07><u>ดึง</u></color></link>เข้าหาศูนย์กลางของพื้นที่ที่ก่อตัวขึ้น หากเลือกศัตรูเพียง 1 ตัว พวกเขาจะได้รับความเสียหายเท่านั้น แต่จะไม่ถูกดึง ความเสียหายขั้นสุดท้ายเพิ่มขึ้น <color=#00F6FF>10%</color> สำหรับทุก ๆ กระเบื้อง <color=#00F6FF>1</color> ที่ศัตรูถูกดึงเข้ามา",
  str_skill_desc_320200 = "เลือกศัตรูได้สูงสุด 2 คนผ่านไทล์ที่พวกเขาครอบครองและสร้างความเสียหาย <color=#00F6FF>{1}%</color> ให้กับพวกเขา ศัตรูทั้งหมดบนชิ้นส่วนที่เลือกและชิ้นส่วนที่อยู่ระหว่างนั้นจะถูก <link=\"30081\"><#FFAE07><u>ดึง</u></color></link>เข้าหาศูนย์กลางของพื้นที่ที่ก่อตัวขึ้น หากเลือกศัตรูเพียง 1 ตัว อนาโตลีจะเปลี่ยนเป็นเป้าหมายที่สองและรวมตัวกันที่จุดศูนย์กลาง",
  str_skill_desc_325200 = "เลือกศัตรูได้สูงสุด 2 คนผ่านไทล์ที่พวกเขาครอบครองและสร้างความเสียหาย <color=#00F6FF>{1}%</color> ให้กับพวกเขา ศัตรูทั้งหมดบนชิ้นส่วนที่เลือกและชิ้นส่วนที่อยู่ระหว่างนั้นจะถูก <link=\"30081\"><#FFAE07><u>ดึง</u></color></link>เข้าหาศูนย์กลางของพื้นที่ที่ก่อตัวขึ้น หากเลือกศัตรูเพียง 1 ตัว อนาโตลีจะเปลี่ยนเป็นเป้าหมายที่สองและรวมตัวกันที่จุดศูนย์กลาง ความเสียหายขั้นสุดท้ายเพิ่มขึ้น <color=#00F6FF>10%</color> สำหรับทุก ๆ กระเบื้อง <color=#00F6FF>1</color> ที่ศัตรูถูกดึงเข้ามา",
  str_skill_passive_desc_410200 = "Chain Combos ของ Anatoli นั้นมีประโยชน์เพิ่มเติม <color=#00F6FF>{1}</color> สร้างความเสียหายแก่ศัตรูแบบสุ่มที่อยู่ติดกับเป้าหมาย",
  str_skill_passive_desc_430200 = "Chain Combos ของ Anatoli นั้นเพิ่มขึ้น <color=#00F6FF>{1}</color> สร้างความเสียหายแก่ศัตรูแบบสุ่มที่อยู่ติดกับเป้าหมาย <color=#00F6FF>เป้าหมายเดียว</color> คอมโบต่อเนื่องของพันธมิตรทั้งหมด <color=#00F6FF>7%</color> เพิ่มความเสียหายขั้นสุดท้ายให้กับ <link=\"30082\"><#FFAE07><u>กระจุก</u></color></link> ศัตรู",
  str_skill_upgrade_desc_15020012 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_15020015 = "Active Skill Enhancement: เพิ่มความเสียหายขั้นสุดท้ายโดย <color=#00F6FF>10%</color> สำหรับทุกๆ <color=#00F6FF>1</color> ศัตรูกระเบื้องถูกดึง",
  str_skill_name_290530101 = "เครื่องหมายความหวาดกลัว",
  str_skill_desc_290530101 = "สร้างความเสียหายแก่เป้าหมายโดยตรงและสร้างเครื่องหมายบนไทล์ที่เป้าหมายอยู่",
  str_skill_name_290530102 = "เดรด รัช",
  str_skill_desc_290530102 = "เคลื่อนไปยังเป้าหมายได้สูงสุด 2 ช่อง สร้างความเสียหายให้กับเป้าหมายตลอดทางและภายในช่องสี่เหลี่ยม 4 ช่องเป็นรูปกากบาทที่ปลายทาง หาก Dread Rush พลาดเป้าหมาย Helios จะปล่อย Terror Mark เพิ่มเติม",
  str_skill_desc_290530312 = "เลื่อนแผ่นกระเบื้องเข้าหาเป้าหมายสูงสุด 2 แผ่น สร้างความเสียหายแก่เป้าหมายตามทางและแผ่นกระเบื้อง 4 แผ่นเป็นรูปกากบาทที่ปลายทาง",
  str_skill_name_290530103 = "กระโดดแห่งความหวาดกลัว",
  str_skill_desc_290530103 = "หากเป้าหมายอยู่ในระยะ Helios จะกระโดดไปข้างๆ เป้าหมาย สร้างความเสียหายอย่างหนักแก่พวกเขาและกระแทกพวกเขาให้ถอยหลังเมื่อลงสู่พื้น หาก Leap of Terror พลาดเป้าหมายหรือเป้าหมายไม่ได้อยู่ในระยะ Helios จะปล่อย Terror Mark เพิ่มเติม",
  str_skill_name_290530104 = "โกรธเกรี้ยว",
  str_skill_desc_290530104 = "Helios เคลื่อนที่ไปยังตำแหน่งของ Terror Marks ตามลำดับที่สร้างขึ้น จากนั้นพุ่งเข้าไปใกล้เป้าหมาย สร้างความเสียหายอย่างใหญ่หลวงแก่เป้าหมายระหว่างทางและภายในระยะที่กำหนดที่ปลายทาง ในเวลาเดียวกัน เฮลิออสจะแปลงส่วนที่เป็นรอยช้ำที่สะสมไว้เป็น HP",
  str_skill_name_215009011 = "โจมตีปกติ",
  str_skill_desc_215009011 = "โจมตีศัตรูในระยะหนึ่งครั้งหลังจากเคลื่อนที่",
  str_skill_name_11150713 = "แหล่งที่มาของอันตราย",
  str_skill_desc_11150713 = "กลับสู่พื้นที่อันตราย ฟื้นฟู HP บางส่วน และเพิ่มพลังให้ตัวเองอย่างถาวร",
  str_skill_name_290530302 = "เดรด รัช",
  str_skill_desc_290530302 = "เลื่อนแผ่นกระเบื้องเข้าหาเป้าหมายสูงสุด 2 แผ่น สร้างความเสียหายแก่เป้าหมายตามทางและแผ่นกระเบื้อง 4 แผ่นเป็นรูปกากบาทที่ปลายทาง",
  str_skill_desc_11150313 = "คริสตัลแสงลึกลับที่สามารถกระตุ้นได้โดยการผ่านมัน เรียกสายฟ้าออกมาโจมตีเป้าหมายทั้งหมด รวมถึงพวกออโรเรียนด้วย",
  str_skill_name_290500102 = "เหยื่อ",
