  str_skill_name_3232021 = "Days Without End",
  str_skill_name_3402021 = "Days Without End",
  str_skill_name_3432021 = "Days Without End",
  str_skill_name_3402023 = "Days Without End",
  str_skill_name_3432023 = "Days Without End",
  str_skill_name_3302022 = "ความมืดแตกสลาย",
  str_skill_name_3362022 = "ความมืดแตกสลาย",
  str_skill_desc_2002021 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color>",
  str_skill_desc_2002022 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>24 ช่องรูปดอกจัน</color>",
  str_skill_desc_2002023 = "ข้อเสนอ <color=#00F6FF>{1}%</color> ความเสียหายใน <color=#00F6FF>รูปร่างรัศมีจนถึงช่วงสูงสุด</color> และสร้าง 1 Blade of Dawn บน 1 แผ่นใดก็ได้ที่สำรวจได้ไกลที่สุด เรียกใช้ได้สูงสุด 1 ครั้งต่อรอบ\n\n",
  str_skill_desc_3002021 = "เมื่อเริ่มการต่อสู้ ลดคูลดาวน์สกิลลง <color=#00F6FF>3</color>. เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกโดยรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย. จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาจะลดคูลดาวน์สกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3032021 = "เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกโดยรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย. จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาจะลดคูลดาวน์สกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3202021 = "เมื่อเริ่มการต่อสู้ ลดคูลดาวน์สกิลลง <color=#00F6FF>3</color>. เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมที่เป็น <color=#00F6FF>4%</color> ของเป้าหมาย <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาจะลดคูลดาวน์สกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3232021 = "เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมที่เป็น <color=#00F6FF>4%</color> ของพวกเขา <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์เคลื่อนที่แบบสุ่มภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาจะลดคูลดาวน์สกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3402021 = "เมื่อเริ่มการต่อสู้ ลดคูลดาวน์สกิลลง <color=#00F6FF>3</color>. เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมนั่นคือ <color=#00F6FF>4%</color> ของเป้าหมาย <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์เคลื่อนที่แบบสุ่มภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3432021 = "เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>500%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมที่เป็น <color=#00F6FF>4%</color> ของพวกเขา <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์เคลื่อนที่แบบสุ่มภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3402022 = "เมื่อเริ่มการต่อสู้ ลดคูลดาวน์สกิลลง <color=#00F6FF>3</color>. เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>650%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมนั่นคือ <color=#00F6FF>4%</color> ของเป้าหมาย <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3432022 = "เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>650%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมที่เป็น <color=#00F6FF>4%</color> ของพวกเขา <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3402023 = "เมื่อเริ่มการต่อสู้ ลดคูลดาวน์สกิลลง <color=#00F6FF>3</color>. เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>650%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมที่เป็น <color=#00F6FF>4%</color> ของเป้าหมาย <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์ที่สุ่มผ่านได้ภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก เมื่อสังหารเป้าหมายได้ จะสร้าง Blade of Dawn เพิ่ม 1 อันที่ตำแหน่งของเป้าหมาย Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3432023 = "เลือก 1 กระเบื้องภายใน <color=#00F6FF>3 กระจุกโดยรอบ</color> ที่ศัตรูยืนอยู่และทำข้อตกลง <color=#00F6FF>650%</color> ความเสียหาย, บวกความเสียหายเพิ่มเติมนั่นคือ <color=#00F6FF>4%</color> ของพวกเขา <color=#00F6FF>สูงสุด</color> HP (ได้รับผลกระทบจากตัวนับองค์ประกอบ) จากนั้นสร้าง Blade of Dawn บน <color=#00F6FF>3</color> ไทล์เคลื่อนที่แบบสุ่มภายใน 2 กลุ่มรอบ ๆ ของไทล์ที่เลือก เมื่อสังหารเป้าหมายได้ จะสร้าง Blade of Dawn เพิ่ม 1 อันที่ตำแหน่งของเป้าหมาย Blade of Dawn แต่ละอันที่หยิบขึ้นมาหรือดึงมาจะลดคูลดาวน์ของสกิลลง <color=#00F6FF>1</color>.",
  str_skill_desc_3302022 = "เลือกใด ๆ <color=#00F6FF>1</color> Blade of Dawn และดึงมันกลับมา",
  str_skill_desc_3362022 = "เลือกใด ๆ <color=#00F6FF>1</color> Blade of Dawn และดึงมันกลับมา",
  str_skill_passive_name_410202 = "ที่แสงส่อง",
  str_skill_passive_name_420202 = "ที่แสงส่อง",
  str_skill_passive_name_430202 = "ที่แสงส่อง",
  str_skill_passive_desc_410202 = "สำหรับทุก ๆ Blade of Dawn ที่ดึงมา สะสม Ode to Ephemeral Night 1 กอง การโจมตีปกติต่อไปนี้ใช้ Ode ถึง Ephemeral Night 1 กองซ้อน และสร้างความเสียหายเพิ่มเติมแก่เป้าหมายเท่ากับ <color=#00F6FF>{1}</color> ของพวกเขา <color=#00F6FF>ปัจจุบัน</color> HP (ความเสียหายเพิ่มเติมจะไม่น้อยกว่า <color=#00F6FF>{2}</color> และไม่เกิน <color=#00F6FF>{3}</color> ของ ATK พื้นฐาน)",
  str_skill_passive_desc_420202 = "สำหรับทุก ๆ Blade of Dawn ที่ดึงมา สะสม Ode to Ephemeral Night 1 กอง การโจมตีปกติต่อไปนี้ใช้ Ode ถึง Ephemeral Night 1 กองซ้อน และสร้างความเสียหายเพิ่มเติมแก่เป้าหมายเท่ากับ <color=#00F6FF>{1}</color> ของพวกเขา <color=#00F6FF>ปัจจุบัน</color> HP (ความเสียหายเพิ่มเติมจะไม่น้อยกว่า <color=#00F6FF>{2}</color> และไม่เกิน <color=#00F6FF>{3}</color> ของ ATK พื้นฐาน)",
  str_skill_passive_desc_430202 = "สำหรับทุก ๆ Blade of Dawn ที่หยิบขึ้นมาหรือเรียกคืนมา สะสม Ode to Ephemeral Night 1 กอง การโจมตีปกติต่อไปนี้ใช้ Ode ถึง Ephemeral Night 1 กองซ้อน และสร้างความเสียหายเพิ่มเติมแก่เป้าหมายเท่ากับ <color=#00F6FF>{1}</color> ของพวกเขา <color=#00F6FF>ปัจจุบัน</color> HP (ความเสียหายเพิ่มเติมจะไม่น้อยกว่า <color=#00F6FF>{2}</color> และไม่เกิน <color=#00F6FF>{3}</color> ของ ATK พื้นฐาน)",
  str_skill_passive_desc_440202 = "สำหรับทุกๆ ดาบแห่งรุ่งอรุณที่ดึงมาได้ สะสม Ode to Ephemeral Night 1 กอง การโจมตีปกติต่อไปนี้ใช้ Ode ถึง Ephemeral Night 1 กองซ้อน และสร้างความเสียหายเพิ่มเติมแก่เป้าหมายเท่ากับ <color=#00F6FF>4%</color> ของ <color=#00F6FF>ปัจจุบัน</color> HP (ความเสียหายเพิ่มเติมจะไม่น้อยกว่า <color=#00F6FF>150%</color> และไม่เกิน <color=#00F6FF>600%</color> ของ ATK พื้นฐาน)",
  str_skill_upgrade_desc_16020213 = "การเสริมทักษะเชิงรุก: การเปลี่ยนแปลง <color=#FFFF00>วันไม่มีที่สิ้นสุด</color> ถึง <color=#FFFF00>การนัดหยุดงานล่วงหน้า</color>. ใช้ได้เมื่อเข้าสู่การต่อสู้",
  str_skill_upgrade_desc_16020216 = "Active Skill Enhancement: ลดคูลดาวน์สกิลของ <color=#FFFF00>ความมืดแตกสลาย</color> โดย <color=#FFFF00>1</color> รอบ (ใช้ได้สำหรับ Ascension III)",
  str_skill_upgrade_refine_desc_16020211 = "การเสริมทักษะอุปกรณ์: เพิ่มขีดจำกัดความเสียหายเพิ่มเติมสูงสุด <color=#00F6FF>600%</color> ของ ATK",
  str_skill_upgrade_refine_desc_16020212 = "Active Skill Enhancement: เพิ่มความเสียหายให้กับ <color=#00F6FF>650%</color>.",
  str_skill_upgrade_refine_desc_16020213 = "Active Skill Enhancement: เมื่อสังหารเป้าหมายได้ จะสร้าง Blade of Dawn เพิ่ม 1 อันในตำแหน่งของเป้าหมาย",
  str_skill_upgrade_refine_desc_15007811 = "การเสริมทักษะอุปกรณ์: ทุกๆ 1 แผ่นสีเขียวที่เท้าของศัตรู โบนัสความเสียหายจะเพิ่มขึ้น <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15007812 = "Active Skill Enhancement: สร้างความเสียหายสองเท่าให้กับไทล์ที่อยู่ตรงกลางของระยะสกิล",
  str_skill_upgrade_refine_desc_15007813 = "Active Skill Enhancement: หาก Active Skill พร้อมในรอบที่แล้ว ช่วงการเลือกจะกลายเป็น <color=#00F6FF>2 กระจุกรอบ</color>.",
  str_skill_passive_desc_4400781 = "เพิ่มความเสียหายของ Robyn ต่อศัตรูที่ครอบครอง Green tile โดย <color=#00F6FF>10%</color>. สำหรับแต่ละแผ่นสีเขียวที่เท้าของศัตรู โบนัสความเสียหายจะเพิ่มขึ้น <color=#00F6FF>1%</color>. มอบให้เพื่อนร่วมทีม Forest Aurorian ด้วย <color=#00F6FF>50%</color> ของโบนัสนี้",
  str_skill_name_3400782 = "ลมหายใจเลื้อยเลาะ",
  str_skill_name_3420782 = "ลมหายใจเลื้อยเลาะ",
  str_skill_name_3400783 = "ลมหายใจเลื้อยเลาะ",
  str_skill_name_3420783 = "ลมหายใจเลื้อยเลาะ",
  str_skill_desc_3400782 = "ข้อเสนอ <color=#00F6FF>250%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 13 แผ่นเป็นรูปเพชร</color> โดยเน้นที่กระเบื้องที่เลือกไว้ 1 แผ่น ความเสียหายที่ทำกับกระเบื้องกลางที่เลือกจะเพิ่มเป็นสองเท่า",
  str_skill_desc_3420782 = "ข้อเสนอ <color=#00F6FF>250%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 13 แผ่นเป็นรูปเพชร</color> โดยเน้นที่กระเบื้องที่เลือกไว้ 1 แผ่น ความเสียหายที่ทำกับไทล์ที่เลือกจะเพิ่มเป็นสองเท่า แปลงกระเบื้องใต้ศัตรูได้สูงสุด 1 แผ่น <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link>.",
  str_skill_desc_3400783 = "ข้อเสนอ <color=#00F6FF>250%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 13 แผ่นเป็นรูปเพชร</color> โดยเน้นที่กระเบื้องที่เลือกไว้ 1 แผ่น ความเสียหายที่กระทำต่อกระเบื้องกลางที่เลือกจะเพิ่มเป็นสองเท่า หาก Active Skill นี้พร้อมในรอบที่แล้ว ช่วงการเลือกจะกลายเป็น <color=#00F6FF>2 กระจุกรอบ</color>.",
  str_skill_desc_3420783 = "ข้อเสนอ <color=#00F6FF>250%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 13 แผ่นเป็นรูปเพชร</color> โดยเน้นที่กระเบื้องที่เลือกไว้ 1 แผ่น ความเสียหายที่ทำกับไทล์ที่เลือกจะเพิ่มเป็นสองเท่า แปลงกระเบื้องใต้ศัตรูได้สูงสุด 1 แผ่น <link=\"20001\"><#FFAE07><u>กระเบื้องที่ปรับปรุงแล้ว</u></color></link>. หาก Active Skill นี้พร้อมในรอบที่แล้ว ช่วงการเลือกจะกลายเป็น <color=#00F6FF>2 กระจุกรอบ</color>.",
  str_skill_upgrade_refine_desc_15007511 = "การเสริมทักษะอุปกรณ์: โอกาสที่การโจมตีปกติจะสร้างพิษเพิ่มขึ้นเป็น <color=#00F6FF>80%</color>.",
  str_skill_upgrade_refine_desc_15007512 = "Active Skill Enhancement: ปัจจัยความเสียหายของ Active Skill เพิ่มขึ้นเป็น <color=#00F6FF>500%</color>.",
  str_skill_upgrade_refine_desc_15007513 = "Active Skill Enhancement: คูลดาวน์ของสกิลจะลดลง <color=#00F6FF>2</color> ในช่วงเริ่มต้นของการรบแต่ละครั้ง",
  str_skill_name_340075 = "สายไฟรัดพัน",
  str_skill_name_342075 = "สายไฟรัดพัน",
  str_skill_name_345075 = "สายไฟรัดพัน",
  str_skill_desc_340075 = "สร้างความเสียหาย 500% แก่ศัตรูภายใน <color=#00F6FF>3 กระจุกโดยรอบ</color> และสร้างความเสียหาย <link=\"10006\"><#FFAE07><u>ช้า</u></color></link> สำหรับ 2 รอบและ 2 กอง <link=\"10001\"><#FFAE07><u>พิษ</u></color></link> เป็นเวลา 2 รอบ",
