  str_skill_desc_2002052 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color>",
  str_skill_desc_2002053 = "ข้อเสนอ <color=#00F6FF>{1}%</color> สร้างความเสียหายแก่เป้าหมายใน <color=#00F6FF>24 แผ่นในรูปทรงรัศมี</color>.",
