  str_skill_desc_2002063 = "ทำความเสียหาย <color=#00F6FF>{1}%</color> ให้กับ <color=#00F6FF>1 กลุ่มรอบ ๆ</color> และช่องสีแดง <color=#00F6FF>ขยายออกไปในทิศทางทั้ง 8</color>",
