  str_skill_name_2302083 = "ทรายพุ่ง",
  str_skill_desc_2002081 = "ทำดาเมจ <color=#00F6FF>{1}%</color> เป็นพื้นที่ <color=#00F6FF>1 แถวแนวตั้ง</color>",
  str_skill_desc_2002082 = "ทำดาเมจ <color=#00F6FF>{1}%</color> เป็นพื้นที่ <color=#00F6FF>3 แถวแนวตั้ง</color>",
  str_skill_desc_2002083 = "ทำดาเมจ <color=#00F6FF>{1}%</color> เป็นพื้นที่ <color=#00F6FF>3 แถวแนวตั้ง</color>",
  str_skill_desc_300208 = "เรียก<link=\"30087\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก <color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูที่อยู่ภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าหาตัวเอง 1 ช่อง",
  str_skill_desc_305208 = "เรียก<link=\"30087\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก ตอนที่กิ้งก่าเหล็ก<color=#00F6FF>เพิ่งเกิด</color> และ<color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูที่อยู่ภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าหาตัวเอง 1 ช่อง",
  str_skill_desc_310208 = "เรียก<link=\"30087\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก <color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูที่อยู่ภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าหาตัวเอง 1 ช่อง",
  str_skill_desc_315208 = "เรียก<link=\"30087\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก ตอนที่กิ้งก่าเหล็ก<color=#00F6FF>เพิ่งเกิด</color> และ<color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูที่อยู่ภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าหาตัวเอง 1 ช่อง",
  str_skill_desc_320208 = "เรียก<link=\"30088\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก <color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> เข้าหาตัวเอง 1 ช่อง กิ้งก่าเหล็กได้รับสกิล<link=\"30089\"><#FFAE07><u>แม่เหล็ก</u></color></link>",
  str_skill_desc_325208 = "เรียก<link=\"30088\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก ตอนที่กิ้งก่าเหล็ก<color=#00F6FF>เพิ่งเกิด</color> และ<color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าใกล้ตัวเอง 1 ช่อง กิ้งก่าเหล็กได้รับสกิล<link=\"30089\"><#FFAE07><u>แม่เหล็ก</u></color></link>",
  str_skill_desc_330208 = "เรียก<link=\"30088\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก <color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าหาตัวเอง 1 ช่อง กิ้งก่าเหล็กได้รับสกิล<link=\"30089\"><#FFAE07><u>แม่เหล็ก</u></color></link> และ <link=\"30090\"><#FFAE07><u>วอร์ลพูล</u></color></link>",
  str_skill_desc_335208 = "เรียก<link=\"30088\"><#FFAE07><u>กิ้งก่าเหล็ก</u></color></link> ลงบนช่องที่เดินได้ที่เลือก ตอนที่กิ้งก่าเหล็ก<color=#00F6FF>เพิ่งเกิด</color> และ<color=#00F6FF>ก่อนรอบของศัตรู</color> กิ้งก่าเหล็กจะดึงศัตรูที่อยู่ภายใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color> ให้เข้าใกล้ตัวเอง 1 ช่อง กิ้งก่าเหล็กได้รับสกิล<link=\"30089\"><#FFAE07><u>แม่เหล็ก</u></color></link> และ<link=\"30090\"><#FFAE07><u>วอร์ลพูล</u></color></link>",
  str_skill_passive_name_410208 = "ลมประทุกกิ้งก่า",
  str_skill_passive_desc_410208 = "เมื่อ Iron Lizard หายไป มันจะตกลง <color=#00F6FF>{1}</color> สร้างความเสียหายให้กับ 2 กลุ่มที่อยู่โดยรอบ",
  str_skill_upgrade_desc_15020812 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_15020815 = "การเสริมทักษะการใช้งาน: เมื่อ Iron Lizard <color=#FFFF00>เกิดขึ้น</color> จะดึงศัตรูภายใน <color=#00F6FF>2 กลุ่มรอบ ๆ</color> มาที่ตัวเอง 1 กระเบื้อง",
  str_skill_name_1522081 = "Magnetix",
  str_skill_desc_1522081 = "เมื่อร่าย จะดึงศัตรูภายใน 2 กลุ่มที่อยู่รอบๆ เข้ามาใกล้กัน 1 ช่อง แล้วหายไป",
  str_skill_name_1532081 = "วินาที",
  str_skill_desc_1532081 = "หลังจากร่าย Bopper's Chain Combo จะถูกเปลี่ยนให้เผชิญหน้ากับ Iron Lizard โดยตรง ซึ่งจะขยายออกไปถึงขอบสนามในรอบนี้",
  str_skill_name_99039011 = "ฟอร์เซคิน: ซิงเกิลสไตรค์",
  str_skill_name_99039012 = "ย้ายเข้าหาออโรเรียนและโจมตีเมื่ออยู่ในระยะ 4 ช่องที่ติดกันของออโรเรียน",
  str_skill_desc_99039011 = "ผู้ถูกทอดทิ้ง: ปืนยิง",
  str_skill_desc_99039012 = "ย้ายไปที่ออโรเรียนและโจมตีเมื่ออยู่ภายใน 1 กลุ่มที่อยู่ใกล้กับออโรเรียน",
  str_skill_name_52200232 = "ตื่นขึ้น",
  str_skill_desc_52200232 = "แปลงกระเบื้องที่เลือก 1 ชิ้นให้กลายเป็นกระเบื้องสีครบทุกสี",
  str_skill_name_290600103 = "ความเศร้าโศก: ลบออก",
