  str_skill_name_290600106 = "ความเศร้าโศก: ความไม่มีตัวตน",
  str_skill_desc_290600103 = "Grieving Eve เทเลพอร์ตไปยังไทล์ที่ไกลที่สุดภายในระยะสูงสุดของพื้นที่รูปกากบาทที่มีศูนย์กลางอยู่รอบๆ เป้าหมาย และโจมตีเป้าหมาย",
  str_skill_desc_290600104 = "Grieving Eve สร้างความเสียหายในพื้นที่ส่วนกลางขนาดใหญ่ของสนามรบ",
  str_skill_desc_290600105 = "อีฟที่กำลังเศร้าได้รับจำนวนมากของสแต็กพลังความมืด ลดปริมาณความเสียหายที่เธอได้รับตามจำนวนสแต็ก ทุกครั้งที่เธอถูกโจมตี สแต็กพลังความมืดจะลดลง",
  str_skill_desc_290600106 = "Grieving Eve ล็อคเป้าหมายและสร้างความเสียหาย จากนั้นฟื้นฟู HP จำนวนมากตามกองซ้อน Darkflow ที่เหลืออยู่",
  str_skill_name_291600103 = "Grieving Eve เทเลพอร์ตไปยังตำแหน่งที่ใกล้กับเป้าหมายที่สุดแล้วโจมตีเป้าหมายนั้น",
  str_skill_name_291600104 = "Grieving Eve สร้างความเสียหายในพื้นที่ส่วนกลางขนาดใหญ่ของสนามรบ",
  str_skill_name_291600105 = "Grieving Eve ได้รับ Darkflow stack ตามจำนวนที่กำหนด และได้รับการลด DMG ตามจำนวน stack ทุกครั้งที่เธอถูกโจมตี สแต็คของ Darkflow จะลดลง",
  str_skill_name_291600106 = "Grieving Eve ล็อคเป้าหมายและสร้างความเสียหาย จากนั้นฟื้นฟู HP จำนวนมากตามกองซ้อน Darkflow ที่เหลืออยู่",
  str_skill_name_20060011 = "ดอกรุ่งอรุณ",
  str_skill_desc_20060011 = "มอบโบนัสฟื้นฟู HP สำหรับ Grieving Eve",
  str_skill_name_200310102 = "เป็นแบบอย่างให้ตาม",
  str_skill_desc_200310102 = "ปล่อยการตัดที่ทำให้เสียหายในครั้งแรก และตามมาด้วยการเตะทันที สร้างความเสียหายเล็ก ๆ ให้กับศัตรูอีกครั้งและกระเด็นพวกเขากลับไป",
  str_skill_name_200310103 = "ปลุกกำลังใจ",
  str_skill_desc_200310103 = "ให้ทหารอิลลูมิน่าในวงรอบตัว 2 ชั้นเพิ่ม ACT และแปลงส่วนหนึ่งของค่าฟกช้ำที่สะสมเป็น HP สำหรับทหารที่อยู่ในระยะและตัวเอง",
  str_skill_name_200290103 = "ยิงสกัดกั้นปืนกล L5",
  str_skill_desc_200290103 = "ทำดาเมจใส่ศัตรูภายในระยะ 20 ช่องรอบตัวด้วยปืนกลเครื่อง",
  str_skill_name_200290104 = "L5 จู่โจมชาร์จ",
  str_skill_desc_200290104 = "เมื่อศัตรูไม่อยู่ภายใน 20 ช่องรอบ ๆ รีบพุ่งเข้าหาช่องในพื้นที่กากบาทที่ใกล้กับศัตรูที่สุด เมื่อถึงที่หมาย สร้างความเสียหายให้กับศัตรูที่อยู่ด้านหน้าปลายทางและกระเด็นพวกเขากลับไป 2 ช่อง",
  str_skill_name_200300101 = "พ่นเปลวไฟแฟนเชิ้บ",
  str_skill_desc_200300101 = "ทำดาเมจให้กับเป้าหมายทั้งหมดในพื้นที่รูปพัดด้านหน้า และทำให้ติดสถานะเผาไหม้ 1 ชั้น พร้อมสร้างไฟบนช่องที่สามารถเดินผ่านได้ภายในระยะ",
  str_skill_name_200340103 = "กวาดล้างความเสื่อมทราม",
  str_skill_desc_200340103 = "เหวี่ยงอาวุธเพื่อทำดาเมจใส่ศัตรูที่อยู่ด้านหน้า",
  str_skill_name_200340104 = "การแทงที่ทำให้เสื่อมทราม",
  str_skill_desc_200340104 = "แทงอาวุธเพื่อทำดาเมจใส่ศัตรูที่อยู่ด้านหน้า",
  str_skill_name_200270101 = "การปฐมพยาบาลในสนามรบอิลลูมินา",
  str_skill_desc_200270101 = "ฟื้นฟู HP ให้ทหารอิลลูมินาที่มี HP ต่ำที่สุดภายใน 4 ช่องในรูปกากบาท และแปลงส่วนหนึ่งของรอยฟกช้ำที่สะสมเป็น HP",
  str_skill_name_200280101 = "เรียกขอกำลังเสริม",
  str_skill_desc_200280101 = "เรียก 1 ทหารอิลลูมินาเข้าสู่สนามรบ",
  str_skill_upgrade_desc_16020913 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_16020916 = "เสริมพลังสกิลใช้งาน: ลดคูลดาวน์ของสกิล <color=#FFFF00>1</color> รอบ",
  str_skill_name_2002091 = "อิมแพ็กต์อาร์เรย์",
  str_skill_name_2002092 = "อิมแพ็กต์อาร์เรย์",
  str_skill_name_2002093 = "อิมแพ็กต์อาร์เรย์",
  str_skill_name_2002094 = "อิมแพ็กต์อาร์เรย์",
  str_skill_desc_2002091 = "กระโดดเข้าหาศัตรูที่ใกล้ที่สุดซึ่งมี HP สูงสุดอยู่ภายใน <color=#00F6FF>กระเบื้อง 12 แผ่นเป็นรูปเพชร</color>จากนั้นข้อตกลง <color=#00F6FF>150%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 9 แผ่นเป็นรูปสี่เหลี่ยมจัตุรัส</color>.",
  str_skill_desc_2002092 = "กระโดดเข้าหาศัตรูที่ใกล้ที่สุดซึ่งมี HP สูงสุดอยู่ภายใน <color=#00F6FF>กระเบื้อง 12 แผ่นเป็นรูปเพชร</color>จากนั้นข้อตกลง <color=#00F6FF>160%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 13 แผ่นเป็นรูปเพชร</color>.",
  str_skill_desc_2002093 = "กระโดดเข้าหาศัตรูที่ใกล้ที่สุดซึ่งมี HP สูงสุดอยู่ภายใน <color=#00F6FF>12 แผ่นในรูปทรงเพชร</color>จากนั้นข้อตกลง <color=#00F6FF>170%</color> สร้างความเสียหายให้กับ <color=#00F6FF>กระเบื้อง 17 แผ่นในรูปทรงรัศมี</color>.",
  str_skill_desc_2002094 = "กระโดดเข้าหาศัตรูที่ใกล้ที่สุดซึ่งมี HP สูงสุดอยู่ภายใน <color=#00F6FF>12 แผ่นในรูปทรงเพชร</color> จากนั้นข้อตกลง <color=#00F6FF>200%</color> สร้างความเสียหายให้กับ <color=#00F6FF>25 แผ่นเป็นรูปสี่เหลี่ยมจัตุรัส</color>. ในระหว่างการเชื่อมต่อแต่ละช่อง การสร้างความเสียหายแต่ละครั้งจะลดเงื่อนไขการเริ่มต้นลง 1 ครั้ง",
  str_skill_name_3002091 = "ลาดตระเวนสายฟ้า",
  str_skill_name_3002092 = "ตัวแปรธาตุสายฟ้าตรวจตราระดับ II",
  str_skill_name_3002093 = "ลาดตระเวนธาตุสายฟ้า ประเภท I",
  str_skill_name_3062091 = "ลาดตระเวนสายฟ้า",
  str_skill_name_3062092 = "ตัวแปรธาตุสายฟ้าตรวจตราระดับ II",
  str_skill_name_3062093 = "ลาดตระเวนธาตุสายฟ้า ประเภท I",
  str_skill_desc_3002091 = "เลือกช่อง 1 ช่องเพื่อทำความเสียหาย <color=#00F6FF>200%</color> ให้กับ 25 ช่องในรูปสี่เหลี่ยมจัตุรัส หากตัวละครผู้ใช้สกิลอยู่ในระยะของสกิล ความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_desc_3002092 = "<color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. เลือก 1 ไทล์เพื่อสร้างความเสียหาย <color=#00F6FF>100%</color> ให้กับ 9 ไทล์ในรูปสี่เหลี่ยม. หากผู้ใช้สกิลอยู่ในระยะของสกิล ความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_desc_3002093 = "<color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. สร้างความเสียหาย 300% แก่ทุกช่อง และความเสียหายขั้นสุดท้ายเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_desc_3062091 = "เลือกช่อง 1 ช่องเพื่อทำความเสียหาย <color=#00F6FF>200%</color> ให้กับ 25 ช่องในรูปสี่เหลี่ยมจัตุรัส หากตัวละครผู้ใช้สกิลอยู่ในระยะของสกิล ความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_desc_3062092 = "<color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. เลือก 1 ไทล์เพื่อสร้างความเสียหาย <color=#00F6FF>100%</color> ให้กับ 9 ไทล์ในรูปสี่เหลี่ยม. หากผู้ใช้สกิลอยู่ในระยะของสกิล ความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_desc_3062093 = "<color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. สร้างความเสียหาย <color=#00F6FF>300%</color> แก่ทุกช่อง และความเสียหายขั้นสุดท้ายเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_passive_name_410209 = "สายฟ้าโกรธแค้น",
  str_skill_passive_name_420209 = "สายฟ้าโกรธแค้น",
  str_skill_passive_name_430209 = "สายฟ้าโกรธแค้น",
  str_skill_passive_desc_410209 = "ศัตรูที่ถูกโจมตีด้วย Active Skill จะเข้าสู่สถานะ Thunderous Echo สำหรับ <color=#00F6FF>2 รอบ</color> สร้างความเสียหาย <color=#00F6FF>{1}</color> ให้กับเป้าหมายภายใต้สถานะ Thunderous Echo ภายใน <color=#00F6FF>กระเบื้อง 12 แผ่นเป็นรูปเพชร</color> สำหรับแต่ละไทล์ที่ทีมเดินทางผ่าน",
  str_skill_passive_desc_420209 = "ศัตรูที่ถูกโจมตีด้วย Active Skill จะเข้าสู่สถานะ Thunderous Echo สำหรับ <color=#00F6FF>2 รอบ</color> สร้างความเสียหาย <color=#00F6FF>{1}</color> ให้กับเป้าหมายภายใต้สถานะ Thunderous Echo ภายใน <color=#00F6FF>กระเบื้อง 12 แผ่นเป็นรูปเพชร</color> สำหรับแต่ละไทล์ที่ทีมเดินทางผ่าน",
  str_skill_passive_desc_430209 = "การโจมตีปกติสามารถตั้งเป้าศัตรูภายใน <color=#00F6FF>8 กระเบื้องเป็นรูปกากบาท</color> ศัตรูที่ถูกโจมตีด้วย Active Skill จะเข้าสู่สถานะ Thunderous Echo สำหรับ <color=#00F6FF>2 รอบ</color> สร้างความเสียหาย <color=#00F6FF>{1}</color> ให้กับเป้าหมายภายใต้สถานะ Thunderous Echo ภายใน <color=#00F6FF>12 กระเบื้องเป็นรูปเพชร</color> สำหรับแต่ละกระเบื้องที่ทีมเดินผ่าน",
  str_skill_passive_desc_440209 = "การโจมตีปกติสามารถตั้งเป้าหมายศัตรูภายใน <color=#00F6FF>8 กระเบื้องเป็นรูปกากบาท</color> ศัตรูที่ถูกโจมตีด้วย Active Skill จะเข้าสู่สถานะ Thunderous Echo สำหรับ <color=#00F6FF>2 รอบ</color> สร้างความเสียหาย <color=#00F6FF>50%</color> ให้กับเป้าหมายภายใต้สถานะ Thunderous Echo ภายใน <color=#00F6FF>12 กระเบื้องเป็นรูปเพชร</color> สำหรับแต่ละกระเบื้องที่ทีมเดินผ่าน",
  str_skill_upgrade_refine_desc_16020911 = "เสริมพลังสกิลอุปกรณ์: ปัจจัยความเสียหายเพิ่มขึ้นเป็น <color=#00F6FF>50%</color>",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>ใหม่ Active Skill Variant I</color>: <color=#FFFF00>คูลดาวน์สกิล +1 หลังจากร่าย</color>. สร้างความเสียหาย <color=#00F6FF>300%</color> ให้กับทุกไทล์ และความเสียหายขั้นสุดท้ายเพิ่มขึ้น <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>ใหม่ Active Skill Variant II</color>: <color=#FFFF00>คูลดาวน์สกิล -1 หลังจากร่าย</color>. เลือก 1 ไทล์เพื่อสร้างความเสียหาย <color=#00F6FF>100%</color> ให้กับ 9 ไทล์ในรูปที่เป็นสี่เหลี่ยม หากตัวร่ายอยู่ในระยะของสกิล ความเสียหายสุดท้ายจะเพิ่มขึ้น 30%",
  str_skill_desc_320116 = "เฟลอร์ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 1 ตัวที่เลือก\nและทำเครื่องหมายใส่เป้าหมาย และสามารถทำดาเมจเพิ่มอีก 1 ครั้ง\nกับเป้าหมายที่มีตราเมื่อใช้คอมโบต่อเนื่องในรอบนี้ \nถ้าสกิลใช้งานพร้อมใช้ในรอบที่แล้ว ดาเมจสุดท้ายในรอบนี้จะเพิ่มขึ้น <color=#00F6FF>35%</color>",
  str_skill_desc_323116 = "เฟลอร์ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 1 ตัวที่เลือกและทำเครื่องหมายใส่เป้าหมาย และสามารถทำดาเมจเพิ่มอีก 1 ครั้งกับเป้าหมายที่มีตราเมื่อใช้คอมโบต่อเนื่องในรอบนี้ ถ้าสกิลใช้งานพร้อมใช้ในรอบที่แล้ว ดาเมจสุดท้ายในรอบนี้จะเพิ่มขึ้น <color=#00F6FF>35%</color>",
  str_skill_upgrade_desc_16011113 = "การเพิ่มประสิทธิภาพทักษะอุปกรณ์: ระยะการสร้างคริสตัลเพิ่มขึ้นเป็น<color=#00F6FF>วงรอบตัว 1/2/3 ชั้น</color>",
  str_skill_upgrade_desc_16011116 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_desc_300111 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู<color=#00F6FF>ทุกตัว</color> ยิ่งศัตรูมีน้อยเท่าไหร่ ดาเมจก็จะยิ่งแรงขึ้น สูงสุดถึง 2 เท่าของดาเมจเดิม",
  str_skill_desc_303111 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู<color=#00F6FF>ทุกตัว</color> ยิ่งศัตรูมีน้อยเท่าไหร่ ดาเมจก็จะยิ่งแรงขึ้น สูงสุดถึง 2 เท่าของดาเมจเดิม",
  str_skill_desc_320111 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู<color=#00F6FF>ทั้งหมด</color> ยิ่งศัตรูน้อยลง ดาเมจที่ทำให้ยิ่งมากขึ้น สูงสุด 2 เท่าของตัวเดิม ติดตราตำแหน่งปัจจุบัน <color=#00F6FF>หลังจากใช้สกิลใช้งาน</color> และเมื่อ<color=#00F6FF>เข้าสู่ออโรราไทม์</color> หากสกิลอุปกรณ์สร้างคริสตัลในรอบนี้ จะทำให้สกิลเรียกใช้งานครั้งเดียวที่ตำแหน่งที่ติดตรา",
  str_skill_desc_323111 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู<color=#00F6FF>ทั้งหมด</color> ยิ่งศัตรูน้อยลง ดาเมจที่ทำให้ยิ่งมากขึ้น สูงสุด 2 เท่าของตัวเดิม ติดตราตำแหน่งปัจจุบัน <color=#00F6FF>หลังจากใช้สกิลใช้งาน</color> และเมื่อ<color=#00F6FF>เข้าสู่ออโรราไทม์</color> หากสกิลอุปกรณ์สร้างคริสตัลในรอบนี้ จะทำให้สกิลเรียกใช้งานครั้งเดียวที่ตำแหน่งที่ติดตรา",
  str_skill_passive_name_416111 = "สัมผัสคริสตัล",
  str_skill_passive_name_436111 = "สัมผัสคริสตัล",
  str_skill_passive_desc_410111 = "ก่อนที่ศัตรูจะลงมือ ถ้าเบริลใช้คอมโบต่อเนื่องในรอบนี้ จะเกิดคริสตัลภายใน<color=#00F6FF>ระยะคอมโบต่อเนื่อง</color>ของเธอ และจะยังคงอยู่ต่อไปนาน 1 รอบ เมื่อศัตรู<link=\"30091\"><#FFAE07><u>แตะต้อง</u></color></link>ถูกคริสตัลของเธอ พวกเขาจะได้รับความเสียหายที่ไม่สนใจ DEF <color=#00F6FF>{1}</color> (ได้รับผลกระทบจากตัวนับธาตุ)",
  str_skill_passive_desc_430111 = "ก่อนที่ศัตรูจะลงมือ ถ้าเบริลใช้คอมโบต่อเนื่องในรอบนี้ จะเกิดคริสตัลภายใน<color=#00F6FF>ระยะคอมโบต่อเนื่อง</color>ของเธอ และจะยังคงอยู่ต่อไปนาน 1 รอบ เมื่อศัตรู<link=\"30091\"><#FFAE07><u>แตะต้อง</u></color></link>ถูกคริสตัลของเธอ พวกเขาจะได้รับความเสียหายที่ไม่สนใจ DEF <color=#00F6FF>{1}</color> (ได้รับผลกระทบจากตัวนับธาตุ) ความเสียหายนี้เพิ่มขึ้น <color=#00F6FF>10%</color> สำหรับแต่ละช่องที่เชื่อมต่อ สูงสุดไม่เกิน 20 ช่อง",
  str_skill_passive_desc_416111 = "ก่อนที่ศัตรูจะลงมือ ถ้าเบริลใช้คอมโบต่อเนื่องในรอบนี้ จะเกิดคริสตัลใน<color=#00F6FF>วงรอบตัว 1/2/3 ชั้น</color> และจะยังคงอยู่ต่อไปนาน 1 รอบ เมื่อศัตรู<link=\"30091\"><#FFAE07><u>แตะต้อง</u></color></link>ถูกคริสตัลของเธอ จะได้รับดาเมจที่ไม่สนใจ DEF เท่ากับ <color=#00F6FF>{1}</color> (ได้รับผลกระทบจากตัวนับธาตุ)",
  str_skill_passive_desc_436111 = "ก่อนที่ศัตรูจะลงมือ ถ้าเบริลใช้คอมโบต่อเนื่องในรอบนี้ จะเกิดคริสตัลภายใน <color=#00F6FF>1/2/3 วงรอบตัว</color> และจะยังคงอยู่ต่อไปนาน 1 รอบ เมื่อศัตรู<link=\"30091\"><#FFAE07><u>แตะต้อง</u></color></link>ถูกคริสตัลของเธอ พวกเขาจะได้รับความเสียหายที่ไม่สนใจ DEF <color=#00F6FF>{1}</color> (ได้รับผลกระทบจากตัวนับธาตุ) ความเสียหายนี้เพิ่มขึ้น <color=#00F6FF>10%</color> สำหรับแต่ละช่องที่เชื่อมต่อ สูงสุดถึง 20 ช่อง",
  str_skill_desc_2001161 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว และทำดาเมจ <link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF> 4 ช่องรูปบวก</color>รอบศัตรู",
  str_skill_desc_2001162 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว และทำดาเมจ <link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF> 4 ช่องรูปบวก</color>รอบศัตรู",
  str_skill_desc_2001163 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว และทำดาเมจ <link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF> 4 ช่องรูปบวก</color>รอบศัตรู",
  str_skill_desc_2061161 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color>รอบศัตรู การโจมตีนี้จะไม่สนใจค่า DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_desc_2061162 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color>รอบศัตรู การโจมตีนี้จะไม่สนใจค่า DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_desc_2061163 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color>รอบศัตรู การโจมตีนี้จะไม่สนใจค่า DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_desc_2201161 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color> รอบ ๆ พวกเขา การโจมตีนี้ละเว้น 40% ของ DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_desc_2201162 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color> รอบ ๆ พวกเขา การโจมตีนี้ละเว้น 40% ของ DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_desc_2201163 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 2 ตัวที่อยู่ใกล้ที่สุด และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ในพื้นที่ <color=#00F6FF>4 ช่องรูปบวก</color> รอบ ๆ พวกเขา การโจมตีนี้ละเว้น 40% ของ DEF หากเป้าหมายถูกทำเครื่องหมาย",
  str_skill_name_2201161 = "กำปั้นเหล็ก",
  str_skill_name_2201162 = "กำปั้นเหล็ก",
  str_skill_name_2201163 = "กำปั้นเหล็ก",
  str_skill_desc_300116 = "เลือกศัตรู 1 ตัว และทำดาเมจ <color=#00F6FF>{1}%</color> พร้อมทิ้งเครื่องหมาย เฟลอร์จะทำดาเมจเพิ่ม 1 ครั้งให้เป้าหมายที่มีเครื่องหมายเมื่อใช้คอมโบต่อเนื่องในรอบนี้",
  str_skill_desc_303116 = "เลือกศัตรู 1 ตัว ทำดาเมจ <color=#00F6FF>{1}%</color> พร้อมทำเครื่องหมาย คอมโบต่อเนื่องของเฟลอร์จะทำดาเมจเพิ่มอีก 1 ครั้งกับเป้าหมายที่มีตราในรอบนี้ เฟลอร์สามารถใช้สกิลใช้งานอีกครั้งหลังจาก<color=#00F6FF>เข้าสู่ออโรราไทม์</color> หรือเมื่อ<color=#00F6FF>เป้าหมายที่มีตราถูกคว่ำ</color>",
  str_skill_passive_name_400116 = "ช่างซ่อมบำรุง",
  str_skill_passive_name_410116 = "ช่างซ่อมบำรุง",
  str_skill_passive_name_430116 = "ช่างซ่อมบำรุง",
  str_skill_passive_desc_410116 = "เมื่อเฟลอร์ทำดาเมจกับศัตรูที่มี Max HP ต่ำกว่า 50% ดาเมจทั้งหมดจะเพิ่มขึ้น <color=#00F6FF>{1}</color> (หากเป้าหมายไม่มีค่า Max HP การเพิ่มดาเมจนี้จะมีผลทันที)",
  str_skill_passive_desc_430116 = "เมื่อเฟลอร์ทำดาเมจกับศัตรูที่มี Max HP ต่ำกว่า 50% ดาเมจทั้งหมดจะเพิ่มขึ้น <color=#00F6FF>{1}</color> (หากเป้าหมายไม่มีค่า Max HP การเพิ่มดาเมจนี้จะมีผลทันที) ให้โบนัสเพิ่มเติม <color=#00F6FF>{2}</color> เมื่อโจมตีเป้าหมายที่มีเครื่องหมาย",
  str_skill_upgrade_desc_16011613 = "เสริมความสามารถคอมโบต่อเนื่อง: เมื่อโจมตีเป้าหมายที่ถูกทำเครื่องหมาย การโจมตีด้วยคอมโบต่อเนื่องจะไม่สนใจ DEF ของเป้าหมายเลย (ใช้ได้เฉพาะขั้นสูงที่ II)",
  str_skill_upgrade_desc_16011616 = "เสริมพลังสกิลใช้งาน: สามารถร่ายอีกครั้งหลังจากเข้าสู่ Aurora Time หรือเมื่อเป้าหมายที่ถูกทำเครื่องหมายถูกคว่ำบาตร",
  str_skill_name_20021011 = "ทำลายล้างดาวห้าแฉก",
