  str_skill_desc_2001882 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>",
  str_skill_desc_2001883 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color>",
  str_skill_desc_300188 = "เลือก <color=#00F6FF>2</color> ช่องใดก็ได้เพื่อเปลี่ยนเป็นช่องสีแดง ทำดาเมจ <color=#00F6FF>{1}%</color> ให้กับช่องที่อยู่ระหว่างทางและช่องที่ติดกัน",
  str_skill_desc_306188 = "เลือก <color=#00F6FF>2</color> ช่องใดก็ได้เพื่อเปลี่ยนเป็นช่องสีแดง ทำดาเมจ <color=#00F6FF>{1}%</color> ให้กับช่องที่อยู่ระหว่างทางและช่องที่ติดกัน สามารถฆ่าศัตรูที่ไม่ใช่บอสที่อยู่ในระยะที่มี HP ต่ำกว่า <color=#00F6FF>15%</color>",
  str_skill_passive_desc_410188 = "ในรอบนี้ การโจมตีปกติครั้งแรกในแต่ละทิศทางจะทำให้เกิดการโจมตีอย่างรุนแรง ทำดาเมจ <color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420188 = "ในรอบนี้ การโจมตีปกติครั้งแรกในแต่ละทิศทางจะทำให้เกิดการโจมตีอย่างรุนแรง ทำดาเมจ <color=#00F6FF>{1}</color> เมื่อเข้าสู่ออโรราไทม์ จำนวนการโจมตีอย่างรุนแรงสำหรับทิศทางการโจมตีปกติทั้งหมดจะรีเซ็ต",
  str_skill_passive_desc_430188 = "การโจมตีปกติ<color=#00F6FF>สามารถเริ่มต้นในแนวทแยง</color> ระหว่างรอบนี้ การโจมตีปกติครั้งแรกในแต่ละทิศทางจะทำให้เกิดการโจมตีอย่างรุนแรง ทำดาเมจ <color=#00F6FF>{1}</color> เมื่อเข้าสู่ Aurora Time จำนวนการโจมตีอย่างรุนแรงสำหรับทิศทางการโจมตีปกติทั้งหมดจะรีเซ็ต",
  str_skill_upgrade_desc_16018813 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_16018816 = "เสริมพลังสกิลใช้งาน: ตัวคูณความเสียหายเพิ่มเป็น <color=#FFFF00>360%</color> สังหารศัตรูที่ไม่ใช่บอสในระยะที่มี HP ต่ำกว่า 15%",
  str_skill_desc_1501301061 = "หลังจากเคลื่อนที่ ทำดาเมจให้กับศัตรูที่ใกล้ที่สุด",
  str_skill_desc_1501301062 = "ใช้ HP ปัจจุบันเป็นการโจมตีศัตรู โดยคำนวณจาก HP ที่สูญเสีย พร้อมทั้งทำให้เกิดผลของเลือดออกในศัตรู",
  str_skill_desc_1500921061 = "หลังจากเคลื่อนที่ ทำดาเมจให้กับ 8 ช่องในรูปกากบาท",
  str_skill_desc_1500921062 = "ทำดาเมจในพื้นที่รูปกากบาทไปจนสุดสนามรบ",
  str_skill_desc_1500921063 = "เปลี่ยนช่องสีแดงที่อยู่ใกล้สุด 5 ช่องให้กลายเป็นสีเขียว",
  str_skill_desc_1601201061 = "หลังจากเคลื่อนที่ ทำดาเมจในระยะ 12 ช่องรูปข้าวหลามตัดรอบตัว พร้อมทำดาเมจเพิ่มเติมในวงรอบตัว 1 ชั้น",
  str_skill_desc_1601201062 = "ทำดาเมจในวงรอบตัว 2 ชั้น พร้อมทั้งเสียหายเพิ่มเติมในวงรอบตัว 1 ชั้น",
  str_skill_desc_1500091061 = "เข้าใกล้ศัตรูเป้าหมายและโจมตี",
  str_skill_desc_1500091062 = "หลังจากเคลื่อนที่ ทำดาเมจในระยะ 12 ช่องรูปข้าวหลามตัด",
  str_skill_desc_1500091063 = "ทำดาเมจในพื้นที่รูปดอกจันไปจนสุดสนามรบ สร้างความหวาดกลัวให้เป้าหมายที่ถูกโจมตี",
  str_skill_desc_1601031061 = "หลังจากเคลื่อนที่ ทำดาเมจให้กับศัตรูที่ใกล้ที่สุด",
