  str_skill_name_22013431 = "ฟ้าผ่าฟาดเปรี้ยง",
  str_skill_name_30013411 = "แสงบาดตา",
  str_skill_desc_2201341 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใส่ศัตรู 2 ตัวภายใน <color=#00F6FF>3 วงรอบตัว</color>. หลังจาก Kanna ใช้ Active Skill ระยะทางจะขยายออกไป <color=#00F6FF>1</color> กลุ่มในรอบเดียวกัน",
  str_skill_desc_2201342 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู <color=#00F6FF>3</color> ตัวใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> หลังจากคันนะใช้ทักษะที่ใช้งานได้ ระยะขยายออกไป <color=#00F6FF>1</color> ชั้นในรอบเดียวกัน",
  str_skill_desc_2201343 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวใน <color=#00F6FF>วงรอบตัว 3 ชั้น</color>. หลังจากคันนะใช้สกิลใช้งาน ระยะของสกิลจะขยายออกไป <color=#00F6FF>1</color> ชั้นในรอบเดียวกัน",
  str_skill_desc_22013411 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใส่ศัตรู 2 ตัวภายใน <color=#00F6FF>3 วงรอบตัว</color>. หลังจาก Kanna ใช้ Active Skill ระยะทางจะขยายออกไป <color=#00F6FF>1</color> กลุ่มในรอบเดียวกัน",
  str_skill_desc_22013421 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู <color=#00F6FF>3</color> ตัวใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> หลังจากคันนะใช้ทักษะที่ใช้งานได้ ระยะขยายออกไป <color=#00F6FF>1</color> ชั้นในรอบเดียวกัน",
  str_skill_desc_22013431 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวใน <color=#00F6FF>วงรอบตัว 3 ชั้น</color>. หลังจากคันนะใช้สกิลใช้งาน ระยะของสกิลจะขยายออกไป <color=#00F6FF>1</color> ชั้นในรอบเดียวกัน",
  str_skill_desc_30013411 = "เลือกช่องที่สามารถเดินทางได้ 1 ช่องเป็นจุดเริ่มต้นของสกิล จากนั้นเลือกช่องใด ๆ 1 ช่องแล้วทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู<color=#00F6FF>ระหว่างทาง</color>และช่องที่<color=#00F6FF>อยู่ติดกัน</color> พร้อมกับผลักศัตรูถอยหลังไปไกลที่สุดเท่าที่จะทำได้ ศัตรู<color=#00F6FF>ระหว่างทาง</color>จะได้รับดาเมจ<color=#00F6FF>×1.3</color>",
  str_skill_name_2301331 = "หลอมละลายนิวเคลียร์",
  str_skill_name_2301332 = "หลอมละลายนิวเคลียร์",
  str_skill_name_2301333 = "หลอมละลายนิวเคลียร์",
  str_skill_name_2361331 = "หลอมละลายนิวเคลียร์",
  str_skill_name_2361332 = "หลอมละลายนิวเคลียร์",
  str_skill_name_2361333 = "หลอมละลายนิวเคลียร์",
  str_skill_desc_2301331 = "ทำดาเมจ <color=#00F6FF>130%</color> เป็นจำนวน 2 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>25%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color>",
  str_skill_desc_2301332 = "ทำดาเมจ <color=#00F6FF>140%</color> เป็นจำนวน 3 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>25%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color>",
  str_skill_desc_2301333 = "ทำดาเมจ <color=#00F6FF>145%</color> เป็นจำนวน 4 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>25%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color> ครั้ง",
  str_skill_desc_2361331 = "ทำดาเมจ <color=#00F6FF>130%</color> เป็นจำนวน 2 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color> ครั้ง",
  str_skill_desc_2361332 = "ทำดาเมจ <color=#00F6FF>140%</color> เป็นจำนวน 3 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color>",
  str_skill_desc_2361333 = "ทำดาเมจ <color=#00F6FF>145%</color> เป็นจำนวน 4 ครั้ง กับศัตรูแบบสุ่มใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color> และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> <color=#00F6FF>30%</color> ใน <color=#00F6FF>4 ช่องรูปบวก</color> เมื่อเป้าหมายได้รับดาเมจมากกว่าหนึ่งครั้ง ดาเมจตั้งแต่ครั้งที่สองเป็นต้นไปจะลดลงครึ่งหนึ่ง ทุกครั้งที่โทรุใช้สกิลในการต่อสู้ จำนวนครั้งที่ Chain Combos ทำดาเมจจะเพิ่มขึ้น <color=#00F6FF>1</color>",
  str_skill_desc_16013311 = "สกิลร่ายสร้างความเสียหาย 5 ครั้งทั้งหมด รีเซ็ตกระเบื้องที่ไม่ใช่สีเหลืองภายใน <color=#00F6FF>1 คลัสเตอร์รอบๆ</color>",
  str_skill_name_16013411 = "การแปลงของความเสียหาย",
  str_skill_desc_16013411 = "เปลี่ยน 4 ช่องรอบ ๆ ให้กลายเป็นช่องสีแดงที่เสียหาย จำนวนคอมโบจะเพิ่มขึ้น 10 สำหรับแต่ละช่องที่เสียหายที่ผ่านไป",
  str_skill_name_390040311 = "การเสริมพลัง",
  str_skill_desc_390040311 = "ปล่อยสกิลเสริมพลังในที่นั้น โดยเพิ่ม DEF อย่างมาก บัฟจะหายไปเมื่อได้รับผลกระทบจากการเคลื่อนย้าย",
  str_skill_name_5362003 = "หอกมรณะ",
  str_skill_desc_5362003 = "เมื่อถูกเรียกใช้ สร้างความเสียหายแท้ให้กับเป้าหมายบนมัน",
  str_skill_desc_5362004 = "โฟโรชั่นแปลงร่างเป็นวัตถุ โฟโรชั่นซ่อนตัวในลูมิวอลล์ที่ห่างจากศัตรูที่สุด (สามารถโจมตีลูมิวอลล์ได้) ทำลายลูมิวอลล์ทั้งหมดเพื่อชนะเกม",
  str_skill_desc_5362005 = "โฟโรชั่นเคลื่อนที่แล้วจู่โจมระยะไกลใส่เป้าหมายในระยะโจมตี และเรียกภาพลวงตา 2 ตัวและทัมเปอร์เข้าสู่สนามรบทุกรอบ",
  str_skill_desc_5362006 = "โฟโรชั่นเคลื่อนที่ไปหาเป้าหมาย ทำดาเมจกับเป้าหมายและเรียกภาพลวงตา 2 ตัว และทัมเปอร์มาใกล้ ๆ กับเป้าหมาย",
  str_skill_name_5362011 = "โจมตีปกติ",
  str_skill_name_5362012 = "โจมตีปกติ",
  str_skill_desc_5362011 = "ย้ายตัวแล้วโจมตีเป้าหมายภายในวงรอบตัว 1 ชั้น",
  str_skill_desc_5362012 = "หลังจากเคลื่อนที่ ทำดาเมจกับเป้าหมายใน 3 แถวแนวตั้ง",
  str_skill_desc_5362013 = "หลังจากเคลื่อนที่ ทำดาเมจใน 3 แถวแนวตั้งและติดสถานะพิษให้กับ Aurorians",
