  str_skill_desc_2202142 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color> สร้างสถานะ <color=#00F6FF>1</color> สแต็กของการถูกกลืนลงในเป้าหมายทั้งหมดภายในระยะทาง",
  str_skill_desc_2202143 = "ทำดาเมจ <color=#00F6FF>{1}%</color> <color=#00F6FF>เป็นรูปดอกจันไปจนสุดสนามรบ</color> สร้างสถานะ<color=#00F6FF>1</color> สแต็กของ Immersion ให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_2302141 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> สร้างสถานะ<color=#00F6FF>1</color> สแต็กของการจมตัวให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_2302142 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color> สร้างสถานะ <color=#00F6FF>1</color> สแต็กของการถูกจมสนุกให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_2302143 = "ทำดาเมจ <color=#00F6FF>{1}%</color> <color=#00F6FF>เป็นรูปดอกจันไปจนสุดสนามรบ</color> สร้างสถานะ<color=#00F6FF>1</color> สแต็กของ Immersion ให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_2402141 = "ทำดาเมจ <color=#00F6FF>145%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> สร้างสถานะ<color=#00F6FF>2</color> สแต็กของ Immersion ให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_2402142 = "ทำดาเมจ <color=#00F6FF>160%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color> สร้างสถานะ<color=#00F6FF>2</color> สแต็กของการถูกกลืนกับทุกเป้าหมายในระยะทาง",
  str_skill_desc_2402143 = "ทำดาเมจ <color=#00F6FF>165%</color> <color=#00F6FF>เป็นรูปดอกจันไปจนสุดสนามรบ</color> สร้างสถานะ<color=#00F6FF>จมตัว</color> 2 สแต็กให้กับเป้าหมายทั้งหมดในระยะทาง",
  str_skill_desc_3002141 = "เปลี่ยนช่องที่เลือก 1 ช่องเป็นสีน้ำเงิน <link=\"30093\"><#FFAE07><u>กระเบื้องมืด</u></color></link> และเปลี่ยนช่องสีน้ำเงินที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นกระเบื้องมืดสีน้ำเงิน",
  str_skill_desc_3062141 = "เปลี่ยนช่องที่เลือก 1 ช่องให้เป็นช่องสีน้ำเงิน<link=\"30093\"><#FFAE07><u>ช่องมืด</u></color></link> และเปลี่ยนช่องสีน้ำเงินที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องให้กลายเป็นช่องมืดสีน้ำเงิน",
  str_skill_passive_name_410214 = "การกระจายพิษมวล",
  str_skill_passive_desc_410214 = "เมื่อผ่านที่กระเบื้องมืด สร้างสถานะ<link=\"30094\"><#FFAE07><u>จมูก</u></color></link> ให้กับ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>. ในตอนเริ่มรอบของศัตรู, แต่ละสแต็กของสถานะจมูกจะทำความเสียหายเท่ากับ <color=#00F6FF>{1}</color> ของ ATK ให้กับเป้าหมาย",
  str_skill_passive_name_430214 = "การกระจายพิษมวล",
  str_skill_passive_desc_430214 = "เมื่อผ่านที่กระเบื้องมืด ให้สถานะ<link=\"30094\"><#FFAE07><u>จมภายใน</u></color></link> กับ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> ในตอนเริ่มรอบของศัตรู สแต็ก Immersion จะทำความเสียหายเท่ากับ <color=#00F6FF>{1}</color> ของ ATK ให้กับเป้าหมาย Immersion จะทำความเสียหายที่ไม่สนใจ DEF ให้กับศัตรูที่ถูกโจมตีด้วย Chain Combo ในรอบนี้",
  str_skill_upgrade_desc_16021413 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้",
  str_skill_upgrade_desc_16021416 = "การเสริมสกิลใช้งาน: เปลี่ยน <color=#FFFF00>5</color> ช่องสีน้ำเงินที่ใกล้ที่สุดกับช่องที่เลือกเป็นช่องสีน้ำเงินเข้ม",
  str_skill_upgrade_refine_desc_16021411 = "การเสริมทักษะอุปกรณ์: แต่ละกองของ Immersion จะทำให้เสียหายเท่ากับ <color=#00F6FF>40%</color> ของ ATK ของ Rebecca ต่อเป้าหมาย",
  str_skill_upgrade_refine_desc_16021412 = "เสริมพลังคอมโบต่อเนื่อง: คอมโบต่อเนื่องทำให้เกิดสถานะ<color=#00F6FF>2</color> สแต็กของ Immersion ให้กับเป้าหมายทั้งหมดภายในระยะที่กำหนด",
  str_skill_upgrade_refine_desc_16021413 = "Active Skill Enhancement: การใช้ Active Skill จะกระตุ้นความเสียหาย 1 ครั้งให้กับเป้าหมายทั้งหมดที่มี Immersion โดยสร้างความเสียหายสองเท่า",
  str_skill_passive_desc_440214 = "เมื่อผ่านที่กระเบื้องมืด ให้สถานะ<link=\"30094\"><#FFAE07><u>จมภายใน</u></color></link> กับ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> ในตอนเริ่มรอบของศัตรู จะทำให้สแต็กของ Immersion ทำความเสียหายเท่ากับ <color=#00F6FF>40%</color> ของ ATK ให้กับเป้าหมาย สถานะ Immersion จะทำความเสียหายโดยไม่สนใจ DEF ให้กับศัตรูที่ถูกโจมตีด้วย Chain Combo ในรอบนี้",
  str_skill_desc_3402141 = "เปลี่ยนช่องที่เลือก 1 ช่องเป็นช่องสีน้ำเงิน<link=\"30093\"><#FFAE07><u>ช่องมืด</u></color></link> และเปลี่ยนช่องสีน้ำเงินที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องเป็นช่องมืดสีน้ำเงิน จากนั้นทำให้เกิดความเสียหาย 1 ครั้งต่อเป้าหมายทั้งหมดในสนามที่มีภาวะจมูก โดยทำความเสียหายสองเท่า",
  str_skill_desc_3462141 = "เปลี่ยน 1 ช่องที่เลือกเป็นช่องสีน้ำเงิน<link=\"30093\"><#FFAE07><u>ช่องมืด</u></color></link> และเปลี่ยนช่องสีน้ำเงินที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องเป็นช่องมืดสีน้ำเงิน จากนั้นทำให้เกิดความเสียหาย 1 ครั้งให้กับเป้าหมายทั้งหมดในสนามที่มีภาวะจมูก โดยทำความเสียหายสองเท่า",
  str_skill_name_80037811 = "โจมตีปกติ",
