  str_skill_name_1003431 = "กอดอ่อนแอ",
  str_skill_desc_1003431 = "ยึดติดกับ Aurorians ภายใน 1 กลุ่มรอบๆ สร้างความเสียหายให้กับพวกเขาและลดค่า ATK ของพวกเขา",
  str_skill_name_200380101 = "ยิงฉับไว",
  str_skill_desc_200380101 = "เคลื่อนตัวออกไกลจากเป้าหมายให้มากที่สุด จากนั้นสร้างความเสียหายให้กับเป้าหมาย 2 ครั้ง",
  str_skill_name_200370101 = "ลูกศรไกล",
  str_skill_desc_200370101 = "ทำดาเมจกับเป้าหมายเป็นพื้นที่รูปบวกไปจนสุดสนามรบ",
  str_skill_name_290910102 = "หมอกพิษ",
  str_skill_name_290910103 = "ผีเสื้อมีพิษ",
  str_skill_name_290910104 = "การโจมตีผีเสื้อ",
  str_skill_desc_290910102 = "เคลื่อนที่แล้วโจมตีศัตรูภายใน 2 ช่องรูปบวก สร้างความเสียหายและทำให้พวกเขาได้รับ Fusion 2 สแต็ค ที่เริ่มต้นของแต่ละรอบ แต่ละสแต็คของ Fusion จะสร้างความเสียหายตามเปอร์เซ็นต์ของ ATK ของ Rebecca Venomswamp",
  str_skill_desc_290910103 = "ย้ายออกจากเป้าหมาย จากนั้นทำความเสียหายและทำให้เกิดสถานะ Fusion 1 สแต็ก ที่เริ่มต้นของแต่ละรอบ สถานะ Fusion แต่ละสแต็กจะทำความเสียหายตามเปอร์เซ็นต์ของ ATK ของ Rebecca Venomswamp",
  str_skill_desc_290910104 = "หลังจากเคลื่อนที่ ทำดาเมจในระยะที่กำหนด ทำให้เกิดสถานะฟิวชั่น 3 สแต็ก และสุ่มเรียกตราพิษหลายตัวในระยะที่กำหนด",
  str_skill_name_200390101 = "โจมตีเครื่องจักรกล",
  str_skill_desc_200390101 = "โจมตีเป้าหมายศัตรูที่ใกล้ที่สุด หาก HP ต่ำกว่า 40% จะฟื้นฟูเปอร์เซ็นต์ของ HP หลังจากเคลื่อนที่ไกล",
  str_skill_name_200390102 = "โจมตีรักษา",
  str_skill_desc_200390102 = "ฟื้นฟูเปอร์เซ็นต์ของ HP บางส่วน",
  str_skill_name_200410101 = "การลอบสังหาร",
  str_skill_desc_200410101 = "โจมตีเป้าหมาย 2 ครั้งหลังจากเคลื่อนที่ แล้วถอยหลังสูงสุด 2 ช่อง หากไม่มีเป้าหมายในระยะ จะเพิ่ม ACT ในรอบถัดไป",
  str_skill_name_9997042 = "โดรนเพลิงแผดเผา",
  str_skill_name_9997041 = "โดรนน้ำแข็งยะเยือก",
  str_skill_name_9997043 = "โดรนพงไพรพิโรธ",
  str_skill_name_9997044 = "โดรนสายฟ้าฟาด",
  str_skill_name_9997045 = "แผ่นจานรุ่งอรุณ",
  str_skill_name_200140111 = "กรงเล็บหนวด - การหลีกเลี่ยงความเสียหาย",
  str_skill_desc_200140111 = "ดาเมจที่กรงเล็บหนวดได้รับจะส่งต่อไปยังคิตตี้พุส แต่ก่อนที่ออโรเรียนจะปล่อย Chain Combo กรงเล็บหนวดจะม้วนตัวเพื่อหลบเลี่ยงการโจมตี",
  str_skill_name_5000591 = "ไล่โกลด์เดอร์",
  str_skill_desc_5000591 = "ทำดาเมจใส่และผลักเป้าหมายทั้งหมดหนึ่งครั้ง",
  str_skill_name_5000592 = "โกลด์เดอร์ล้างตัว",
  str_skill_desc_5000592 = "ทำดาเมจใส่เป้าหมายทั้งหมดด้านหน้า 1 ครั้ง",
  str_skill_name_5000593 = "คลุ้มคลั่งหนี้",
  str_skill_desc_5000593 = "หลังจาก Aurorian ใช้ Active Skill แผ่นกระเบื้องสีเหลืองแบบสุ่มจะถูกแปลงเป็นแผ่นกระเบื้องสีแดงในขณะที่กำลังเคลื่อนที่",
  str_skill_name_5000594 = "ความอบอุ่นที่แชร์กัน",
  str_skill_desc_5000594 = "คุณจะเข้าใกล้ Goldor ไม่ว่าคุณจะอยู่ที่ไหน",
  str_skill_name_29092001 = "คีมกรีดขาด",
  str_skill_desc_29092001 = "Stinger ทำดาเมจใส่เป้าหมายภายในวงรอบตัว 1 ชั้น ของตัวเอง 2 ครั้ง และทำให้เกิดสถานะเลือดไหลให้ศัตรู",
  str_skill_desc_290920011 = "Stinger ทำดาเมจใส่เป้าหมายในวงรอบตัว 1 ชั้น ของตัวเอง 2 ครั้ง และทำให้เกิดสถานะเลือดไหลและไม่สามารถฟื้นฟูเลือดได้",
  str_skill_name_29092002 = "ปะทะภูเขา",
  str_skill_desc_29092002 = "Stinger เลือกทิศทาง 1 ทิศที่ผู้เล่นอยู่ในพื้นที่รูปบวก วิ่งไปยังขอบของสนามหรืออุปสรรคที่ใกล้ที่สุด แล้วผลักเป้าหมายทั้งหมดตามเส้นทางของมัน ทำความเสียหายเพิ่มให้กับเป้าหมายที่อยู่ในระยะ 1 ช่องที่อยู่ทั้งสองข้างของเส้นทาง และทำให้เป้าหมายเสียเลือด",
  str_skill_name_29092003 = "เผาไหม้",
  str_skill_desc_29092003 = "สติงเกอร์ยิงแสงพลังงานจากหางของมัน ทำดาเมจใหญ่ใส่เป้าหมาย 1 ครั้ง",
  str_skill_name_29092004 = "กระแทกชาร์จ",
  str_skill_desc_29092004 = "สติงเกอร์กระโดดถอยหลัง 1 ช่อง ทำความเสียหายให้เป้าหมายด้านหน้า และทำให้เป้าหมายเกิดเลือดออกและมีผลพิษ",
  str_skill_name_29092005 = "แตกตื่นอย่างรุนแรง",
  str_skill_desc_29092005 = "Stinger วิ่งหน้าไปทั้งแนวนอนและแนวตั้งอย่างต่อเนื่อง ทำดาเมจให้เป้าหมายด้านหน้าและสร้างผลกระทบจากการเลือดออกและพิษให้กับพวกมัน",
  str_skill_name_29092006 = "การสะท้อนกระจก",
  str_skill_desc_29092006 = "สติงเกอร์ยิงสายฟ้าที่ผีเสื้อกระจก สร้างเส้นทางสามเหลี่ยมด้วยแสงที่พวกมันสะท้อน และทำความเสียหายต่อทุกสิ่งที่อยู่ในทางของมัน",
  str_skill_name_2002161 = "ดึงร่มกันแดด",
  str_skill_name_2002162 = "ดึงร่มกันแดด",
  str_skill_name_2002163 = "ดึงร่มกันแดด",
  str_skill_name_2202161 = "ดึงร่มกันแดด",
  str_skill_name_2202162 = "ดึงร่มกันแดด",
  str_skill_name_2202163 = "ดึงร่มกันแดด",
  str_skill_name_300216 = "แสงสายฟ้ากระพริบ",
  str_skill_name_303216 = "แสงสายฟ้ากระพริบ",
  str_skill_passive_name_410216 = "รั้วมุมแมลงปอ",
  str_skill_passive_name_430216 = "รั้วมุมแมลงปอ",
  str_skill_desc_2002161 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2002162 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่่อยู่ใกล้ที่สุด",
  str_skill_desc_2002163 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด",
  str_skill_desc_2202161 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว จากนั้นทำดาเมจอีกครั้งให้ 1 ศัตรูสุ่มภายในอาร์เรย์สี่เหลี่ยมฟ้าผ่า",
  str_skill_desc_2202162 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่อยู่ใกล้ที่สุด แล้วทำดาเมจอีกครั้งให้ศัตรู 1 ตัวแบบสุ่มภายใน Square Thunder Array",
  str_skill_desc_2202163 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด แล้วทำดาเมจอีกครั้งให้ 1 ศัตรูสุ่มภายในอาร์เรย์สี่เหลี่ยมฟ้าผ่า",
  str_skill_desc_300216 = "ใช้ 3 <link=\"30095\"><#FFAE07><u>อะไหล่เสริม</u></color></link> เพื่อเลือก 1 กระเบื้อง และสร้างอาร์เรย์ฟ้าสี่เหลี่ยมภายใน <color=#00F6FF>9 กระเบื้องในรูปสี่เหลี่ยม</color> ที่ยืนยันเป็นเวลา <color=#00F6FF>2</color> รอบ การโจมตีปกติของ Xuan Ji <color=#00F6FF>สามารถเปิดตัวทแยง</color> ภายในอาร์เรย์ฟ้าสี่เหลี่ยม",
  str_skill_desc_303216 = "ใช้ 3 <link=\"30095\"><#FFAE07><u>อะไหล่เสริม</u></color></link> เพื่อเลือก 1 ช่อง และสร้างอาร์เรย์ฟ้าสี่เหลี่ยมภายใน <color=#00F6FF>25 ช่องที่มีรูปร่างเป็นสี่เหลี่ยม</color> ที่ยืนยันเป็นเวลา <color=#00F6FF>3</color> รอบ การโจมตีปกติของ Xuan Ji <color=#00F6FF>สามารถเริ่มต้นแนวทะแยง</color> ภายในอาร์เรย์ฟ้าสี่เหลี่ยม",
  str_skill_passive_desc_410216 = "เพิ่มดาเมจของเสี่ยวจีใน Square Thunder Array <color=#00F6FF>{1}</color>",
  str_skill_passive_desc_416216 = "เพิ่มความเสียหายของ Xuan Ji ใน Square Thunder Array โดย <color=#00F6FF>{1}</color> ความเสียหายของเธอเพิ่มขึ้นอีก <color=#00F6FF>5%</color> สำหรับทุก Square Thunder Array เพิ่มเติมในสนาม หาก Xuan Ji อยู่ภายใน Square Thunder Array เมื่อรอบสิ้นสุด เธอจะได้รับ 1 Spare Part",
  str_skill_passive_desc_430216 = "เพิ่มความเสียหายของหวงจิใน Square Thunder Array โดย <color=#00F6FF>{1}</color>. เมื่อหวงจิอยู่ภายใน Square Thunder Array หลังจากใช้ Chain Combo, Basic ATK ของเธอจะเพิ่มขึ้น <color=#00F6FF>4%</color>, สามารถสะสมได้ถึง 5 ครั้ง. หากเธอไม่อยู่ใน Square Thunder Array เมื่อรอบสิ้นสุด, จำนวนสะสมของผลกระทบนี้จะลดลงครึ่งหนึ่ง.",
  str_skill_passive_desc_436216 = "เพิ่มความเสียหายของหวานจีในอาร์เรย์ฟ้าสี่เหลี่ยม <color=#00F6FF>{1}</color> ความเสียหายเพิ่มขึ้นอีก <color=#00F6FF>5%</color> สำหรับอาร์เรย์ฟ้าสี่เหลี่ยมที่เพิ่มเติมในสนาม หากหวานจีอยู่ในอาร์เรย์ฟ้าสี่เหลี่ยมเมื่อจบรอบ เธอจะได้รับ 1 ชิ้นสำรอง ในขณะที่หวานจีอยู่ในอาร์เรย์ฟ้าสี่เหลี่ยมหลังจากใช้คอมโบต่อเนื่อง พื้นฐาน ATK เพิ่มขึ้น <color=#00F6FF>4%</color> สามารถซ้อนกันได้ถึง 5 ครั้ง หากเธอไม่อยู่ในอาร์เรย์ฟ้าสี่เหลี่ยมเมื่อจบรอบ จำนวนสแต็กของผลกระทบนี้จะลดลงครึ่งหนึ่ง",
  str_skill_upgrade_desc_16021613 = "เสริมพลังสกิลใช้งาน: ขยายพื้นที่ของ Square Thunder Array ให้เป็น <color=#00F6FF>25 ช่องเป็นรูปสี่เหลี่ยม</color> ยังคงอยู่เป็นระยะเวลา <color=#00F6FF>3</color> รอบ",
  str_skill_upgrade_desc_16021616 = "การเสริมทักษะอุปกรณ์: ความเสียหายของ Xuan Ji จะเพิ่มขึ้นเพิ่มเติม <color=#00F6FF>5%</color> สำหรับ Square Thunder Array ที่เพิ่มเติมในสนาม. ถ้า Xuan Ji อยู่ภายใน Square Thunder Array เมื่อรอบสิ้นสุด, เธอจะได้รับ 1 ชิ้นส่วนสำรอง.",
  str_skill_name_53820323 = "ระเบิดเมื่อออโรเรียนเข้าใกล้ ถ้าปล่อยไว้ มันจะระเบิดหลังจากผ่านไปจำนวนรอบที่กำหนด และสร้างเปลวไฟหลายๆ อันรอบๆ ตัวมัน",
  str_skill_name_200400103 = "ไฟท้อง",
  str_skill_name_200400104 = "ไฟท้อง",
  str_skill_desc_200400103 = "เคลื่อนที่ในแนวขวางและพ่นไฟ ทำความเสียหายให้กับศัตรูที่อยู่ด้านหน้า มันจะหยุดการเคลื่อนที่เมื่อพบอุปสรรค",
  str_skill_desc_200400104 = "เคลื่อนที่ในแนวขวางและพ่นไฟ ทำความเสียหายให้กับศัตรูที่อยู่ด้านหน้า มันจะหยุดการเคลื่อนที่เมื่อพบอุปสรรค",
  str_skill_name_290570123 = "Mudbundle: เขมือบ",
  str_skill_desc_290570123 = "Mudbundle ปรากฏขึ้นจากศูนย์กลางของหนองน้ำใหญ่ กลืนกินทุกอย่างและสร้างความเสียหายให้กับ Aurorians.",
  str_skill_name_290620102 = "สเปซคัตเตอร์: ละติจูด",
  str_skill_desc_290620102 = "Vilanor รีบเข้าไปและตัด, สร้างความเสียหายและสร้าง Forbidden Wall ยาว 3 ช่องแนวนอนข้างๆ Aurorians และโทรพอร์ตไปยังสถานที่ใหม่",
  str_skill_name_290620104 = "ตัดอวกาศ: ลองจิจูด",
  str_skill_desc_290620104 = "Vilanor รีบเข้าไปและตัด, สร้างความเสียหายและสร้าง Forbidden Wall ยาว 3 ช่องแนวตั้งข้างๆ Aurorians และโทรพอร์ตไปยังสถานที่ใหม่",
  str_skill_name_290620106 = "อยู่ห่างๆนะ",
  str_skill_desc_290620106 = "วิลานอร์ทำดาเมจให้กับศัตรูภายในวงรอบตัว 1 ชั้น และผลักพวกเขาไปยังตำแหน่งที่ไกลที่สุดที่เป็นไปได้ จากนั้นสร้างกำแพงต้องห้ามที่ขอบภายนอกของช่องภายในวงรอบตัว 1 ชั้น",
  str_skill_name_800400011 = "กับดักขับไล่วิญญาณ",
  str_skill_desc_800400011 = "การเหยียบบนกับดักไล่ผีจะลบกำแพงต้องห้ามทั้งหมดบนสนาม",
  str_skill_desc_2900273 = "ทำดาเมจใส่ออโรเรียนที่อยู่ทุกที่ในสนามรบและเรียก Goldor มา",
  str_skill_desc_2000303 = "จ่ายทองเพื่อฟื้นฟู HP ของโกลด์เดอร์ต้องสาปเมื่ออยู่ในวงรอบ 1 ชั้นของมัน",
  str_skill_desc_2000304 = "เมื่ออยู่ในวงรอบ 1 ชั้นของอีสต์วาน จ่ายทองเพื่อฟื้นฟู HP ของมัน",
  str_skill_desc_200381101 = "เพิ่มระยะการเคลื่อนที่ จากนั้นเคลื่อนที่ใกล้เป้าหมายและทำความเสียหาย 2 ครั้ง การเคลื่อนที่นี้ไม่ถูกกีดขวางโดยสิ่งกีดขวาง",
  str_skill_desc_200411101 = "โจมตีเป้าหมาย 2 ครั้งหลังจากเคลื่อนที่ ผลักเป้าหมายและวางระเบิด จากนั้นถอยหลังสูงสุด 3 ช่อง หากไม่มีเป้าหมายในระยะ จะเพิ่ม ACT ในรอบถัดไป",
  str_skill_desc_200371101 = "ทำความเสียหายต่อศัตรูภายในระยะ 3 ช่องตามรูปกากบาท ผลักพวกเขาถอยหลังและทิ้งระเบิดไว้ที่ที่พวกเขาอยู่ก่อนถูกผลักถอยหลัง",
  str_skill_upgrade_desc_16021913 = "เสริมพลังสกิลใช้งาน: ได้รับ <color=#00F6FF>5</color> การสนับสนุนจากเงาเมื่อเข้าสู่การต่อสู้\nการเพิ่มประสิทธิภาพทักษะอุปกรณ์: ขยายระยะการเลือกของการเคลื่อนที่เชสไปยัง 2 วงรอบตัว",
  str_skill_upgrade_desc_16021916 = "รับสกิลใช้งานใหม่: เลือก <color=#00F6FF>2</color> ช่องใดๆ และสลับช่องสีมืดบน 2 ช่องนี้ หากมีชิ้นเงาอยู่บนช่องที่เลือก ชิ้นเงาจะถูกสลับไปยังช่องอื่นด้วย",
  str_skill_name_2002191 = "กรงเล็บที่เผาไหม้",
  str_skill_name_2002192 = "กรงเล็บที่เผาไหม้",
  str_skill_name_2002193 = "กรงเล็บที่เผาไหม้",
  str_skill_desc_2002191 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด ใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color>",
  str_skill_desc_2002192 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด ใน<color=#00F6FF>วงรอบตัว 3 ชั้น</color>",
  str_skill_desc_2002193 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด ใน<color=#00F6FF>วงรอบตัว 4 ชั้น</color>",
  str_skill_name_3002191 = "การเขยิบเงา",
  str_skill_name_3302191 = "การเขยิบเงา",
  str_skill_name_3032191 = "การเขย่าเบี้ยเงา",
  str_skill_name_3332191 = "การเขย่าเบี้ยเงา",
  str_skill_name_3062191 = "การถ่ายโอนเงา",
  str_skill_desc_3002191 = "ใช้ <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>สิทธิพิเศษแห่งเงา</u></color></link> และเลือก <color=#00F6FF>พันธมิตรหนึ่งคน</color> เพื่อให้พวกเขาสามารถ <color=#00F6FF>ใช้คอมโบต่อเนื่องเพิ่มอีก 1 ครั้ง</color> ในรอบนี้ (ผลลัพธ์นี้ไม่สามารถซ้อนทับกัน). เมื่อใช้คอมโบต่อเนื่องเพิ่มเติม พลังโจมตีของพันธมิตรจะเท่ากับ <color=#00F6FF>100%</color> ของพลังโจมตีของอีสต์วาน: สการ์เร็ดพิธ อีสต์วาน: สการ์เร็ดพิธจะไม่ใช้คอมโบต่อเนื่องในรอบนี้ ในทุกครั้งที่สกิลใช้งานถูกใช้กับพันธมิตรคนเดียวกันในการต่อสู้นี้ ค่าใช้จ่ายของสิทธิพิเศษแห่งเงาจะเพิ่มขึ้น 1 ครั้ง",
  str_skill_desc_3302191 = "ใช้ <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>พลังแห่งเงา</u></color></link> และเลือก <color=#00F6FF>พันธมิตรหนึ่งคน</color> เพื่อให้สามารถ <color=#00F6FF>ใช้คอมโบต่อเนื่องเพิ่มอีก 1 ครั้ง</color> ในรอบนี้ (ผลลัพธ์นี้ไม่สามารถซ้อนกันได้) เมื่อใช้คอมโบต่อเนื่องเพิ่มเติม พลังโจมตีของพันธมิตรจะเท่ากับ <color=#00F6FF>100%</color> ของพลังโจมตีของอีสต์วาน: สการ์เร็ดพิธ อีสต์วาน: สการ์เร็ดพิธจะไม่ใช้คอมโบต่อเนื่องในรอบนี้ หรือใช้ <color=#00F6FF>2</color> Shadow Endowments เพื่อเลือก Shadow Piece บนสนามและใช้ Active Skill ทำให้ Shadow Piece สร้าง Chain Combo แทน Istvan: Scarred Pith ในรอบนี้ และความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>50%</color> ค่าใช้จ่ายของ Shadow Endowment จะเสมอ 2 เมื่อใช้กับ Shadow Piece ในทุกครั้งที่ Active Skill ถูกใช้กับพันธมิตรเดียวกันในการต่อสู้นี้ ค่าใช้จ่ายของ Shadow Endowment +1",
  str_skill_desc_3032191 = "ใช้ <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>สิทธิพิเศษแห่งเงา</u></color></link> และเลือก <color=#00F6FF>พันธมิตรหนึ่งคน</color> เพื่อให้พวกเขาสามารถ <color=#00F6FF>ใช้คอมโบต่อเนื่องเพิ่มอีก 1 ครั้ง</color> ในรอบนี้ (ผลลัพธ์นี้ไม่สามารถซ้อนทับกันได้) เมื่อใช้คอมโบต่อเนื่องเพิ่มเติม พันธมิตรของคุณจะมี ATK เท่ากับ <color=#00F6FF>100%</color> ของ ATK ของอีสต์วาน: สการ์เร็ดพิธ อีสต์วาน: สการ์เร็ดพิธจะไม่ใช้คอมโบต่อเนื่องในรอบนี้ ในทุกครั้งที่สกิลใช้งานถูกใช้กับพันธมิตรเดียวกันในการต่อสู้นี้ ค่าใช้จ่ายของสิทธิพิเศษแห่งเงาจะเพิ่มขึ้น 1",
  str_skill_desc_3332191 = "ใช้ <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>พลังแห่งเงา</u></color></link> และเลือก <color=#00F6FF>พันธมิตรหนึ่งคน</color> เพื่อให้สามารถ <color=#00F6FF>ใช้คอมโบต่อเนื่องเพิ่มอีก 1 ครั้ง</color> ในรอบนี้ (ผลลัพธ์นี้ไม่สามารถซ้อนทับกันได้) เมื่อใช้คอมโบต่อเนื่องเพิ่มเติม พลังโจมตีของพันธมิตรจะเท่ากับ <color=#00F6FF>100%</color> ของพลังโจมตีของอีสต์วาน: สการ์เร็ดพิธ อีสต์วาน: สการ์เร็ดพิธจะไม่ใช้คอมโบต่อเนื่องในรอบนี้ หรืออีกทางเลือก ใช้ <color=#00F6FF>2</color> Shadow Endowments เพื่อเลือก Shadow Piece บนสนามและใช้ Active Skill ทำให้ Shadow Piece สร้าง Chain Combo แทน Istvan: Scarred Pith ในรอบนี้ และความเสียหายสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>50%</color> ค่าใช้จ่ายของ Shadow Endowment จะเสมอ 2 เมื่อใช้กับ Shadow Piece ในทุกครั้งที่ Active Skill ถูกใช้กับพันธมิตรเดียวกันในการต่อสู้นี้ ค่าใช้จ่ายของ Shadow Endowment จะเพิ่ม 1",
  str_skill_desc_3062191 = "เลือก <color=#00F6FF>2</color> ช่องใดก็ได้และสลับไทล์มืดบน 2 ช่องนี้ หากมีชิ้นเงาอยู่บนช่องที่เลือก ชิ้นเงาจะถูกสลับไปยังช่องอื่นด้วย",
  str_skill_passive_name_410219 = "การเลื่อนขั้นเงา",
  str_skill_passive_name_420219 = "การเลื่อนขั้นเงา",
  str_skill_passive_name_403219 = "การเลื่อนขั้นเงา",
  str_skill_passive_name_423219 = "การเลื่อนขั้นเงา",
  str_skill_passive_desc_410219 = "เมื่อเข้าสู่การต่อสู้, อีสต์วาน: สการ์เรดพิธ จะเรียก 1 ชิ้นเงาใกล้กับ Aurorians ที่สามารถใช้สกิลได้\nการเดินหมากรุก: เทเลพอร์ตไปยังช่องที่สามารถผ่านได้ภายใน <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> และทำความเสียหาย <color=#00F6FF>{1}</color> ต่อ 4 ศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>2 วงรอบตัว</color>.",
  str_skill_passive_desc_420219 = "เมื่อเข้าสู่การต่อสู้, อีสต์วาน: สการ์ดพิธ จะเรียก 1 ชิ้นเงาใกล้กับ Aurorians ที่สามารถใช้สกิลได้ เมื่อรอบสิ้นสุด ชิ้นเงาจะสร้าง <link=\"30093\"><#FFAE07><u>กระเบื้องมืด</u></color></link> ใต้ตัว\nการเดินหมากรุก: เทเลพอร์ตไปยังตำแหน่งที่สามารถผ่านได้ภายใน <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> และทำความเสียหาย <color=#00F6FF>{1}</color> ให้กับ 4 ศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>2 วงรอบตัว</color>",
  str_skill_passive_desc_403219 = "เมื่อเข้าสู่การต่อสู้, อีสต์วาน: สการ์เรดพิธ จะเรียก 1 ชิ้นเงาใกล้กับ Aurorians ที่สามารถใช้สกิลได้\nการเดินหมากรุก: เทเลพอร์ตไปยังช่องที่สามารถผ่านได้ภายใน <color=#00F6FF>2 วงรอบตัว</color> และสร้างความเสียหาย <color=#00F6FF>{1}</color> ให้กับศัตรูที่ใกล้ที่สุด 4 ตัวภายใน <color=#00F6FF>2 วงรอบตัว</color>.",
  str_skill_passive_desc_423219 = "เมื่อเข้าสู่การต่อสู้, Istvan: Scarred Pith จะเรียก 1 ชิ้นเงาใกล้กับ Aurorians ที่สามารถใช้สกิลได้ เมื่อรอบสิ้นสุด ชิ้นเงาจะสร้าง <link=\"30093\"><#FFAE07><u>กระเบื้องมืด</u></color></link> ใต้ตัวมัน\nการเดินหมากรุก: เทเลพอร์ตไปยังกระเบื้องที่สามารถผ่านได้ภายใน <color=#00F6FF>2 วงรอบตัว</color> และทำความเสียหาย <color=#00F6FF>{1}</color> ต่อ 4 ศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>2 วงรอบตัว</color>.",
