  str_skill_desc_2002211 = "Bool ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>",
  str_skill_desc_2002212 = "Bool ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>16 ช่องรูปดอกจัน</color>",
  str_skill_desc_2002213 = "Bool ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>24 ช่องรูปดอกจัน</color>",
  str_skill_name_300221 = "อัตราภาษีมรณะ",
