  str_skill_name_29093013 = "ก้าวสู่ปีใหม่",
  str_skill_desc_29093013 = "เนี่ยนกระโดดไปข้างหน้า 3 ช่อง ทำดาเมจกับ 1 กลุ่มรอบ ๆ ที่ช่องที่ลงสู่พื้นและผลักศัตรูที่อยู่ในระยะไปทั้งสองข้าง ถ้าเนี่ยนถึงประตู ประตูจะถูกทำลาย ทำให้เนี่ยนสามารถเข้าไปได้",
  str_skill_name_7001125103 = "Forsaken: หอนโกรธ",
  str_skill_desc_7001125103 = "Forsaken: Cerritus ทำความเสียหายต่อ Aurorians ทั้งหมดที่อยู่ในสนาม พร้อมเพิ่ม ACT ของตัวเอง และเรียก Pebbles",
  str_skill_name_7001125104 = "Forsaken: ทุบแตกเป็นเสี่ยงๆ",
  str_skill_desc_7001125104 = "ถูกทอดทิ้ง: Cerritus สร้างกระเบื้องที่อ่อนแอและพุ่งเข้าใส่ Aurorians กระแทกพวกมันให้ถอยกลับและทำลาย Pebbles ที่อยู่ในทางของมัน",
  str_skill_name_7001125105 = "Forsaken: แผ่นดินไหวทำลายล้าง",
  str_skill_desc_7001125105 = "ถูกทอดทิ้ง: Cerritus ทุบกระเบื้อง 2 แผ่นที่อยู่ด้านหน้าหลังจากเคลื่อนย้าย สร้างความเสียหายอย่างใหญ่หลวงและสร้างกระเบื้องที่อ่อนแอ",
  str_skill_name_7001126103 = "ฟอร์เซคิน: ปลดปล่อยความรู้สึกด้านลบ",
  str_skill_desc_7001126103 = "ถูกทอดทิ้ง: แชนดราเคลื่อนที่ห่างจาก Aurorians แล้วสร้างความเสียหายให้กับ Aurorians ที่อยู่ภายใน 2 คลัสเตอร์รอบๆ",
  str_skill_name_7001126104 = "Forsaken: โครงการถ่ายทอดอารมณ์ด้านลบ",
  str_skill_desc_7001126104 = "ฟอร์เซเคน: แชนดราสร้างความเสียหายให้กับ Aurorians ทั้งหมดในสนามรบ",
  str_skill_name_80150311 = "ก้อนหิน",
  str_skill_desc_80150311 = "หินก้อนนี้ได้ขวางทางที่นี่มานานพอแล้ว ใช้ 2 แต้มพลังเพื่อเคลื่อนย้ายมันออกไป",
  str_skill_name_290940103 = "หอกไฟเงามืด",
  str_skill_desc_290940103 = "ไอราสร้างความเสียหายให้กับ Aurorians และสร้าง Shadowfire บนชิ้นส่วนที่อยู่ข้างนอกสุดของสนามในระยะสูงสุดในพื้นที่ที่มีรูปกากบาทที่อยู่ตรงกลางของ Aurorians",
  str_skill_name_290940104 = "ระเบิดที่ร้อนแรง",
  str_skill_desc_290940104 = "ไอราทำดาเมจใส่ออโรเรียนที่อยู่ในวงรอบตัวเอง 2 ชั้น",
  str_skill_name_290940105 = "ดาวตกที่เต็มไปด้วยวราธ",
  str_skill_desc_290940105 = "ไอราเรียกหินดาวตกมาโจมตีตำแหน่งที่ออโรเรียนอยู่ในรอบก่อนหน้า สร้างความเสียหายร้ายแรงและทำลายแผ่นกระเบื้อง ทิ้งแผ่นกระเบื้องแตก 4 แผ่นในรูปกากบาท",
  str_skill_name_200480103 = "นรกเงาไฟ",
  str_skill_desc_200480103 = "Shadowfire สร้างความเสียหายให้กับ Aurorians ที่อยู่ในระยะ และโทรพอร์ตไปที่ด้านตรงข้ามของสนาม หากไม่สามารถโจมตีผู้เล่นได้ มันจะโทรพอร์ตตามเข็มนาฬิกาในคลัสเตอร์ที่อยู่ด้านนอกสุดของสนาม โดยเคลื่อนที่ 2 ช่อง",
  str_skill_name_300226 = "มันเป็นโลกของกบ",
  str_skill_name_200226 = "กบผู้ยิ่งใหญ่จงเจริญ",
  str_skill_passive_name_400226 = "ซิมโฟนีแห่งคริ๊กคริ๊ก",
  str_skill_desc_300226 = "ในฝัน, เจ้าชายลิลิแพดมีพลังในการบรรเทาภูเขาไฟที่ระเบิดและซ่อมแซมรอยแตกที่มืดของท้องฟ้า ในโลกจริง, เขามุ่งมั่นที่จะรักษาเพื่อน ๆ ด้วยความอ่อนโยนของเขา... คุณถามว่ามันทำอะไรได้บ้าง? ทำให้คุณอุ่นใจด้วยความน่ารัก!",
  str_skill_desc_200226 = "เสียงกบก้าก้าแน่นอนของเจ้าชายลิลิแพดสะท้อนทั่วแอสตร้า! มันทำอะไรกันแน่นะคุณถาม? มันทำให้คุณถูกอุ้มด้วยความน่ารัก!",
  str_skill_passive_desc_400226 = "เสียงก้าก้าของกบคือจังหวะชีวิตของธรรมชาติ ลมหายใจของอัสตรา แสงสว่างในความมืดที่ไม่มีทางสิ้นสุด คุณได้ยินมันหรือไม่? เขากำลังเชิญทุกคนมาร่วมงานฉลองครั้งใหญ่นี้ด้วยการร้องเพลงสวดมนต์ด้วยกัน! มันทำอะไรได้บ้าง คุณถาม? ทำให้ทุกคนร้องก้าก้าไปด้วยกันเนี่ยแหละ!",
  str_skill_name_54350081 = "ยามปืนซัลโว",
  str_skill_desc_54350081 = "หน้าที่ของปืนยิงคู่คือการป้องกันกษัตริย์! พวกเขาจะออกจากสนามรบหลังจากคอมโบต่อเนื่องของ Aurorians.",
  str_skill_upgrade_desc_16022513 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้ และสร้างจุดอ่อนเพิ่ม 1 จุดให้กับศัตรูที่อยู่ในระยะทาง",
  str_skill_upgrade_desc_16022516 = "การเสริมทักษะอุปกรณ์: เมื่อผ่านผ่าน <link=\"30093\"><#FFAE07><u>ไทล์มืด</u></color></link> มีโอกาส 50% ที่จะสร้างจุดอ่อนเพิ่มเติม 1 จุด",
