  str_skill_name_3032272 = "Death Recon: Exhausted",
  str_skill_name_3062272 = "Death Recon: Exhausted",
  str_skill_name_3062271 = "Death Recon",
  str_skill_desc_2002271 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2002272 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2002273 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_20022712 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้สกิลได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 1 สแต็ก Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_20022722 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้งานได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 2 สแต็กของ Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_20022732 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้งานได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 3 สแต็กของ Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_2202271 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้สกิลได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 1 สแต็ก Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_2202272 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้งานได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 2 สแต็กของ Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_2202273 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว สามารถใช้งานได้ในขณะที่อ่อนเพลีย แต่จะทำให้ได้รับ 3 สแต็กของ Eagle Talon แทนการทำดาเมจ",
  str_skill_desc_3002271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องมืดบน <color=#00F6FF>1</color> ในช่องเหล่านี้โดยสุ่ม\nสกิลใช้งานสามารถใช้งานอีกครั้งก่อนที่จะพร้อม หลังจากใช้งาน ระยะเวลาคูลดาวน์ของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะ Exhausted จะถูกนำออกเมื่อสกิลใช้งานพร้อมใช้งานอีกครั้ง",
  str_skill_desc_3032271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>1</color> ในช่องเหล่านี้โดยสุ่ม\nสกิลใช้งานสามารถใช้ได้อีกครั้งก่อนที่จะพร้อม ทำให้เพิ่มจำนวนการเปลี่ยนช่องได้ <color=#00F6FF>2</color> และสร้างช่องสีมืดเพิ่มเติม <color=#00F6FF>1</color> ช่อง หลังจากใช้สกิล ระยะเวลาคูลดาวน์ของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะ Exhausted จะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ได้อีกครั้ง",
  str_skill_desc_3062271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>2</color> ช่องเหล่านี้โดยสุ่ม\nสกิลใช้งานสามารถใช้ได้อีกครั้งก่อนที่จะพร้อม ทำให้จำนวนการเปลี่ยนช่องเพิ่มขึ้น <color=#00F6FF>2</color> และสร้างช่องสีมืดเพิ่มเติม <color=#00F6FF>1</color> ช่อง หลังจากใช้สกิล ระยะเวลาคูลดาวน์ของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะ Exhausted จะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ได้อีกครั้ง",
  str_skill_desc_3002272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>1</color> ช่องจากช่องเหล่านี้โดยสุ่ม\nหลังจากใช้สกิล, ระยะเวลาหยุดรอของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ, และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color>, ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos. สถานะ Exhausted จะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่อีกครั้ง.",
  str_skill_desc_3032272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>2</color> ช่องเหล่านี้โดยสุ่ม\nหลังจากใช้สกิล ระยะเวลาในการรอสกิลของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และราเชลจะกลายเป็น<color=#00F6FF>อ่อนเพลีย</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือการโจมตีแบบเชื่อมโยง สภาพอ่อนเพลียจะหายไปเมื่อสกิลใช้งานพร้อมใช้ใหม่",
  str_skill_desc_3062272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>3</color> ช่องเหล่านี้โดยสุ่ม\nหลังจากใช้สกิล ระยะเวลาคูลดาวน์ของสกิลใช้งานเพิ่มขึ้น 1 รอบ และเรเชลกลายเป็น<color=#00F6FF>อ่อนเพลีย</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือการโจมตีเชื่อมโยง สภาพอ่อนเพลียจะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่",
  str_skill_passive_name_410227 = "การจัดรูปขบวนโฮโลแกรม",
  str_skill_passive_name_420227 = "Holographic Formation",
  str_skill_passive_name_430227 = "Holographic Formation",
  str_skill_passive_desc_410227 = "สร้างสแต็ก Eagle Talon <color=#00F6FF>3</color> สแต็กให้เป้าหมายที่ใกล้ที่สุดเมื่อผ่านทาง<link=\"30093\"><#FFAE07><u>กระเบื้องมืด</u></color></link> ในตอนเริ่มรอบของศัตรู ทำดาเมจเท่ากับ <color=#00F6FF>{1}</color> ของ ATK ปัจจุบันของ Rachel สำหรับแต่ละสแต็ก Eagle Talon จำนวนสแต็กจะลดลงครึ่งหนึ่งเมื่อรอบสิ้นสุด ถ้าเป้าหมายถูกฆ่า สแต็ก Eagle Talon ครึ่งหนึ่งจะถูกโอนไปยังศัตรูที่ใกล้ที่สุด",
  str_skill_passive_desc_420227 = "Inflicts <color=#00F6FF>3</color> Eagle Talon stacks on the nearest target when passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. At the start of the enemy's round, deals damage equal to <color=#00F6FF>{1}</color> of Rachel's current ATK once for each Eagle Talon stack. The number of stacks is halved when the round ends. If the target is killed, half the Eagle Talon stacks will transfer to the nearest enemy.",
  str_skill_passive_desc_430227 = "ทำให้เกิดสแต็ก <color=#00F6FF>3</color> ของ Eagle Talon ให้เป้าหมายที่ใกล้ที่สุดเมื่อผ่าน <link=\"30093\"><#FFAE07><u>กระเบื้องมืด</u></color></link> ในตอนเริ่มรอบของศัตรู จะทำดาเมจเท่ากับ <color=#00F6FF>{1}</color> ของ ATK ปัจจุบันของ Rachel สำหรับแต่ละสแต็ก Eagle Talon จำนวนสแต็กจะลดลงครึ่งหนึ่งเมื่อรอบสิ้นสุด ถ้าเป้าหมายถูกฆ่า สแต็ก Eagle Talon ครึ่งหนึ่งจะถูกโอนไปยังศัตรูที่ใกล้ที่สุด ถ้า Rachel <color=#00F6FF>อ่อนเพลีย</color> ATK ของเธอจะเพิ่มขึ้น <color=#00F6FF>3%</color> สำหรับทุกช่องที่ผ่านไปในการเชื่อมต่อ",
  str_skill_passive_desc_440227 = "มอบสแต็ก <color=#00F6FF>3</color> ของ Eagle Talon ให้เป้าหมายที่ใกล้ที่สุดเมื่อผ่าน <link=\"30093\"><#FFAE07><u>ช่องมืด</u></color></link> ในตอนเริ่มรอบของศัตรู ทำดาเมจเท่ากับ <color=#00F6FF>80%</color> ของ ATK ปัจจุบันของ Rachel สำหรับแต่ละสแต็ก Eagle Talon จำนวนสแต็กจะลดลงครึ่งหนึ่งเมื่อรอบสิ้นสุด ถ้าเป้าหมายถูกฆ่า สแต็ก Eagle Talon ครึ่งหนึ่งจะถูกโอนไปยังศัตรูที่ใกล้ที่สุด ถ้า Rachel <color=#00F6FF>อ่อนเพลีย</color> ATK ของเธอจะเพิ่มขึ้น <color=#00F6FF>3%</color> สำหรับทุกช่องที่ผ่านในการเชื่อมต่อ",
  str_skill_passive_desc_460227 = "ทำให้เกิดสถานะ <color=#00F6FF>3</color> สแต็กของ Eagle Talon กับเป้าหมายที่ใกล้ที่สุดเมื่อผ่านทาง<link=\"30093\"><#FFAE07><u>ช่องมืด</u></color></link> ในตอนเริ่มรอบของศัตรู จะทำดาเมจเท่ากับ <color=#00F6FF>80%</color> ของ ATK ปัจจุบันของ Rachel สำหรับแต่ละสแต็กของ Eagle Talon จำนวนสแต็กจะลดลงครึ่งหนึ่งเมื่อรอบจบ ถ้าเป้าหมายถูกฆ่า สแต็กของ Eagle Talon ครึ่งหนึ่งจะถูกโอนไปยังศัตรูที่ใกล้ที่สุด ถ้า Rachel อยู่ในสถานะ<color=#00F6FF>อ่อนแรง</color> ATK ของเธอจะเพิ่มขึ้น <color=#00F6FF>4%</color> สำหรับทุกช่องที่เดินผ่านในการเชื่อมต่อ",
  str_skill_desc_3502271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องมืดบน <color=#00F6FF>1</color> ช่องจากช่องเหล่านี้โดยสุ่ม จากนั้นสร้าง <color=#00F6FF>2</color> ช่องของ Eagle Talon บนเป้าหมายที่ใกล้ที่สุด\nสกิลใช้งานสามารถใช้งานอีกครั้งก่อนที่จะพร้อม หลังจากใช้งาน ระยะเวลาในการรอสกิลใช้งานของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ Exhausted จะถูกนำออกเมื่อสกิลใช้งานพร้อมใช้งานอีกครั้ง",
  str_skill_desc_3532271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องมืดบน <color=#00F6FF>1</color> ในช่องเหล่านี้โดยสุ่ม จากนั้นทำให้เกิด <color=#00F6FF>2</color> ชั้นของ Eagle Talon บนเป้าหมายที่อยู่ใกล้ที่สุด\nสกิลใช้งานสามารถใช้งานอีกครั้งก่อนที่จะพร้อม ทำให้จำนวนการเปลี่ยนช่องเพิ่มขึ้น <color=#00F6FF>2</color> และสร้างช่องมืดเพิ่มเติม <color=#00F6FF>1</color> ช่อง หลังจากใช้งานสกิล ระยะเวลาในการรอสกิลจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ทำให้ไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะหมดแรงจะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่อีกครั้ง",
  str_skill_desc_3562271 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่ใกล้ที่สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>2</color> ช่องเหล่านี้โดยสุ่ม จากนั้นสร้าง <color=#00F6FF>2</color> ชั้นของ Eagle Talon บนเป้าหมายที่ใกล้ที่สุด\nสกิลใช้งานสามารถใช้งานอีกครั้งก่อนที่จะพร้อม ทำให้จำนวนการเปลี่ยนช่องเพิ่มขึ้น <color=#00F6FF>2</color> และสร้างช่องสีมืดเพิ่มเติม <color=#00F6FF>1</color> ช่อง หลังจากใช้สกิล ระยะเวลาในการรอสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะหมดแรงจะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่อีกครั้ง",
  str_skill_desc_3502272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>3</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องมืดบน <color=#00F6FF>1</color> ช่องจากช่องเหล่านี้โดยสุ่ม จากนั้นสร้าง <color=#00F6FF>2</color> ชุด Eagle Talon บนเป้าหมายที่อยู่ใกล้ที่สุด\nหลังจากใช้สกิล, ระยะเวลาในการรอสกิลใช้งานของสกิลใช้งานเพิ่มขึ้น 1 รอบ, และ Rachel กลายเป็น <color=#00F6FF>Exhausted</color>, ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos. Exhausted จะถูกนำออกเมื่อสกิลใช้งานพร้อมใช้ใหม่อีกครั้ง",
  str_skill_desc_3532272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>2</color> ช่องจากช่องเหล่านี้โดยสุ่ม จากนั้นสร้าง <color=#00F6FF>2</color> ชั้นของ Eagle Talon บนเป้าหมายที่อยู่ใกล้ที่สุด\nหลังจากใช้สกิล ระยะเวลารอสกิลใช้งานของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะ Exhausted จะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่",
  str_skill_desc_3562272 = "เปลี่ยนช่องที่ไม่ใช่สีเหลืองที่อยู่ใกล้สุด <color=#00F6FF>5</color> ช่องให้กลายเป็นสีเหลือง และสร้างช่องสีมืดบน <color=#00F6FF>3</color> ช่องเหล่านี้โดยสุ่ม จากนั้นสร้าง <color=#00F6FF>2</color> กองทัพ Eagle Talon บนเป้าหมายที่อยู่ใกล้ที่สุด\nหลังจากใช้สกิล ระยะเวลารอสกิลใช้งานของสกิลใช้งานจะเพิ่มขึ้น 1 รอบ และ Rachel จะกลายเป็น <color=#00F6FF>Exhausted</color> ซึ่งทำให้เธอไม่สามารถใช้การโจมตีปกติหรือ Chain Combos ได้ สถานะ Exhausted จะถูกยกเลิกเมื่อสกิลใช้งานพร้อมใช้ใหม่",
  str_skill_upgrade_desc_16022713 = "เสริมพลังสกิลใช้งาน: สกิลใช้งานสามารถใช้งานได้อีกครั้งก่อนที่จะพร้อม ทำให้เพิ่มการเปลี่ยนสีช่องได้ <color=#FFFF00>2</color> ช่อง และสร้างกระเบื้องสีมืดเพิ่มเติม <color=#FFFF00>1</color> ช่อง",
  str_skill_upgrade_desc_16022716 = "เสริมพลังสกิลใช้งาน: เพิ่มจำนวนการสร้างช่องสีเข้มขึ้น <color=#FFFF00>1</color> ช่อง",
  str_skill_upgrade_refine_desc_16022711 = "การเสริมทักษะอุปกรณ์: ในตอนเริ่มรอบของศัตรู จะทำความเสียหายเท่ากับ <color=#00F6FF>80%</color> ของ ATK ปัจจุบันของ Rachel หนึ่งครั้งสำหรับแต่ละกอง Eagle Talon.",
  str_skill_upgrade_refine_desc_16022712 = "เสริมพลังสกิลใช้งาน: หลังจากหล่อสกิล สร้าง <color=#00F6FF>2</color> ชั้นของ Eagle Talon ให้กับเป้าหมายที่ใกล้ที่สุด",
  str_skill_upgrade_refine_desc_16022713 = "การเสริมทักษะอุปกรณ์: หาก Rachel รู้สึกเหนื่อยล้า, พลังโจมตีของเธอจะเพิ่มขึ้น <color=#00F6FF>4%</color> สำหรับทุกแผ่นที่เดินผ่านในการเชื่อมต่อ",
  str_skill_upgrade_desc_15022812 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้\nสกิลลับ <color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> สามารถใช้ได้สำหรับ Ascension I.",
  str_skill_upgrade_desc_15022815 = "เสริมพลังสกิลใช้งาน Variety Blitz: เพิ่มจำนวนช่องที่คุณสามารถเลือกได้ <color=#FFFF00>1</color> ช่อง",
  str_skill_desc_10071120 = "ปล่อยลำแสงปะทะไปยังตำแหน่งของเป้าหมายในรอบสุดท้าย ทำดาเมจใส่เป้าหมายที่อยู่ในเส้นทางของลำแสง และที่ตำแหน่งของเป้าหมาย",
  str_skill_desc_10071130 = "ผลักเป้าหมายที่อยู่ในระยะให้ไปอยู่กลางกระดาน",
  str_skill_name_54550920 = "กรงเล็บหนวด - การหลีกเลี่ยงความเสียหาย",
  str_skill_desc_54550920 = "เมื่อออโรเรียนปล่อยคอมโบเชน กรงเล็บหนวดจะม้วนหนวดของมันเพื่อหลบเลี่ยงการโจมตี และดูดซับช่องเสริมพลังที่ตำแหน่งของมัน",
  str_skill_name_29097013 = "โจมตีปกติ",
  str_skill_desc_29097013 = "สร้างความเสียหายให้กับ Aurorians ที่อยู่ด้านหน้าหลังจากเคลื่อนที่",
  str_skill_name_29097014 = "ลาวาเร่งรีบ",
  str_skill_desc_29097014 = "สร้างความเสียหายให้กับพื้นที่ทรงพัดขนาดใหญ่ในทิศทางของ Aurorians และสร้าง Pebbles",
  str_skill_name_29097015 = "คำรามเผาไหม้",
  str_skill_desc_29097015 = "ทำดาเมจทั่วหน้าจอ 3 ครั้ง โดยผลักเป้าหมายถอยหลังไป 1 ช่องในแต่ละครั้ง ถ้าเป้าหมายไม่สามารถถูกผลักได้ จะได้รับความเสียหายที่มากขึ้น",
  str_skill_name_2002281 = "ซุ่มโจมตีอย่างหวาน",
  str_skill_name_2002282 = "ซุ่มโจมตีอย่างหวาน",
  str_skill_name_2002283 = "ซุ่มโจมตีอย่างหวาน",
  str_skill_desc_2002281 = "เซต้าปล่อย Conan ที่ค้นหาศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>กระเบื้อง 12 แผ่นเป็นรูปเพชร</color> มันจะระเบิดเมื่อถึงเป้าหมาย สร้างความเสียหาย <color=#00F6FF>150%</color> ให้กับกระเบื้อง 5 แผ่นในรูปกากบาท",
  str_skill_desc_2002282 = "เซต้าปล่อย Conan ที่ค้นหาศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>24 กระเบื้องเป็นรูปเพชร</color> มันจะระเบิดเมื่อถึงเป้าหมาย สร้างความเสียหาย <color=#00F6FF>160%</color> ให้กับ 5 กระเบื้องในรูปกากบาท",
  str_skill_desc_2002283 = "เซต้าปล่อย Conan ที่ค้นหาศัตรูที่ใกล้ที่สุดภายใน <color=#00F6FF>กระเบื้อง 24 แผ่นเป็นรูปเพชร</color> มันจะระเบิดเมื่อถึงเป้าหมาย ทำความเสียหาย <color=#00F6FF>160%</color> ให้กับกระเบื้อง 5 แผ่นในรูปกากบาท\nเมื่อเซต้าร่าย Chain Combo ระดับ 3 ระยะความเสียหายของ Conan ที่ถูกเรียกโดย Secret Razzle Dazzle Active Skill ของเธอจะขยายเป็น 1 กระจุกรอบ",
  str_skill_name_3002281 = "สายฟ้าแลบหลากหลาย",
  str_skill_name_3052281 = "สายฟ้าแลบหลากหลาย",
  str_skill_name_3102281 = "สายฟ้าแลบหลากหลาย",
  str_skill_name_3152281 = "สายฟ้าแลบหลากหลาย",
  str_skill_desc_3002281 = "เลือกไทล์ใด ๆ 3 ชิ้น จากนั้นรีเซ็ตสีและทำความสะอาดพวกเขา ไทล์สีน้ำเงินจะถูกเก็บรักษาเมื่อรีเซ็ตไทล์",
  str_skill_desc_3052281 = "เลือกช่องใด ๆ 4 ช่อง จากนั้นรีเซ็ตสีและทำความสะอาดช่องเหล่านั้น ช่องสีน้ำเงินจะถูกเก็บรักษาไว้เมื่อรีเซ็ตช่อง",
  str_skill_desc_3102281 = "เลือกช่องใดก็ได้ 3 ช่อง บันทึกสีของพวกเขาบน<link=\"30100\"><#FFAE07><u>บอร์ดสี</u></color></link> จากนั้นรีเซ็ตสีของพวกเขาและทำความสะอาดพวกเขา ช่องสีน้ำเงินจะถูกเก็บไว้เมื่อรีเซ็ตช่อง",
  str_skill_desc_3152281 = "เลือกช่องใดก็ได้ 4 ช่อง, บันทึกสีของพวกเขาบน<link=\"30100\"><#FFAE07><u>บอร์ดสี</u></color></link>, จากนั้นรีเซ็ตสีของพวกเขาและทำความสะอาดพวกเขา. ช่องสีน้ำเงินจะถูกเก็บไว้เมื่อรีเซ็ตช่อง.",
  str_skill_name_3002282 = "เคล็ดลับการสว่างไสว",
  str_skill_desc_3002282 = "ใช้สีทั้งหมดบน <link=\"30100\"><#FFAE07><u>Color Board</u></color></link> ที่เต็มเพื่อเรียก Conan บน 1 ช่องที่เดินได้ เมื่อเซต้าใช้ Chain Combo ครั้งแรกในรอบนี้ Conan จะค้นหาศัตรูและโจมตีพวกเขา",
  str_skill_passive_name_410228 = "เรนโบว์ไดนาไมต์",
  str_skill_passive_name_420228 = "เรนโบว์ไดนาไมต์",
  str_skill_passive_name_430228 = "เรนโบว์ไดนาไมต์",
  str_skill_passive_desc_410228 = "เซต้าได้รับสกิลใช้งาน Secret Razzle Dazzle และ <link=\"30100\"><#FFAE07><u>Color Board</u></color></link> โคนันที่ถูกเรียกด้วย Secret Razzle Dazzle จะ <color=#00F6FF>ค้นหาศัตรูรอบตัวและโจมตีพวกเขา</color> เมื่อเซต้าใช้คอมโบต่อเนื่อง รัศมีการค้นหาของเขาเท่ากับ <color=#00F6FF>เดียวกัน</color> กับระยะของคอมโบต่อเนื่องที่เซต้าใช้ และเขาทำความเสียหายเท่ากับ <color=#00F6FF>{1}</color> ของความเสียหายที่คอมโบต่อเนื่องของเซต้าทำได้",
  str_skill_passive_desc_420228 = "เซต้าได้รับสกิลใช้งาน Secret Razzle Dazzle และ <link=\"30100\"><#FFAE07><u>Color Board</u></color></link> โคนันที่ถูกเรียกด้วย Secret Razzle Dazzle จะ <color=#00F6FF>ค้นหาศัตรูรอบตัวเขาและโจมตีพวกเขา</color> เมื่อเซต้าใช้คอมโบต่อเนื่อง รัศมีการค้นหาของเขาเท่ากับ <color=#00F6FF>เดียวกัน</color> กับระยะของคอมโบต่อเนื่องที่เซต้าใช้ และเขาทำความเสียหายเท่ากับ <color=#00F6FF>{1}</color> ของความเสียหายที่คอมโบต่อเนื่องของเซต้าทำ หากเซต้าใช้คอมโบต่อเนื่องระดับ 3 ระยะความเสียหายของโคนันจะขยายเป็น <color=#00F6FF>วงรอบตัว 1 ชั้น</color>",
  str_skill_passive_desc_430228 = "เซต้าได้รับสกิลใช้งาน Secret Razzle Dazzle และ <link=\"30100\"><#FFAE07><u>Color Board</u></color></link> โคนันที่ถูกเรียกด้วย Secret Razzle Dazzle จะ <color=#00F6FF>ค้นหาศัตรูรอบตัวและโจมตีพวกเขา</color> เมื่อเซต้าใช้คอมโบต่อเนื่อง รัศมีการค้นหาของเขาเท่ากับ <color=#00F6FF>เท่ากับ</color> ระยะของคอมโบต่อเนื่องที่เซต้าใช้ และเขาทำความเสียหายเท่ากับ <color=#00F6FF>{1}</color> ของความเสียหายที่คอมโบต่อเนื่องของเซต้าทำให้ เมื่อเซต้าใช้คอมโบต่อเนื่องระดับ 3 ระยะความเสียหายของโคนันจะขยายออกไป <color=#00F6FF>1 วงรอบตัว</color>. เมื่อกระดานสีเต็ม จะฟื้นฟู HP ของทีมเท่ากับ <color=#00F6FF>12%</color> ของ HP สูงสุดของเซต้า",
  str_skill_name_2002291 = "เจอทางออกแล้ว!",
  str_skill_name_2002292 = "Exit Found!",
  str_skill_name_2002293 = "Exit Found!",
  str_skill_name_3002291 = "ทั้งหมดเรียบร้อย!",
  str_skill_name_3202291 = "All Clear!",
  str_skill_name_3302291 = "All Clear!",
  str_skill_name_3232291 = "All Clear!",
  str_skill_name_3262291 = "All Clear!",
  str_skill_name_3332291 = "All Clear!",
  str_skill_name_3362291 = "All Clear!",
  str_skill_passive_name_4002291 = "อย่าให้แบตเตอรี่หมด!",
  str_skill_desc_2002291 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว",
  str_skill_desc_2002292 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่่อยู่ใกล้ที่สุด",
  str_skill_desc_2002293 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด",
  str_skill_desc_2202291 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรูที่อยู่ใกล้ที่สุด 2 ตัว และทำให้เกิดสถานะเผาไหม้ 1 สแต็ก",
  str_skill_desc_2202292 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 3 ตัวที่่อยู่ใกล้ที่สุด และทำให้เกิดสถานะเผาไหม้ 1 สแต็ก",
  str_skill_desc_2202293 = "ทำดาเมจ <color=#00F6FF>{1}%</color> กับศัตรู 4 ตัวที่อยู่ใกล้ที่สุด และมอบสถานะเผาไหม้ 1 สแต็ก",
  str_skill_desc_3002291 = "Batia เริ่มการต่อสู้ด้วย <link=\"30110\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง",
  str_skill_desc_3202291 = "Batia เริ่มต้นการต่อสู้ด้วย <link=\"30111\"><#FFAE07><u>Next Queue</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงใน Next Queue จะถูกเปลี่ยนเป็นช่องสีแดง ช่องสีแดงที่ผ่านไปทุกช่องจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> เพื่อสุ่มบล็อก การสุ่มทุกครั้งจะเสียพลังงานเพิ่มเติม <color=#00F6FF>5</color> จนกว่าจะใช้สกิลใช้งานของเธอครั้งถัดไป",
  str_skill_desc_3232291 = "บาเทียเริ่มต้นการต่อสู้ด้วย <link=\"30112\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง คิวถัดไปเริ่มต้นด้วยพลังงาน <color=#00F6FF>10</color> และแต่ละช่องสีแดงที่ผ่านจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> เพื่อสุ่มบล็อก การพยายามสุ่มแต่ละครั้งจะเสียพลังงานเพิ่มเติม <color=#00F6FF>5</color> จนกว่าจะใช้สกิลใช้งานของเธอครั้งถัดไป",
  str_skill_desc_3262291 = "Batia เริ่มต้นการต่อสู้ด้วย <link=\"30113\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง คิวถัดไปเริ่มต้นด้วย <color=#00F6FF>10</color> พลังงาน และช่องสีแดงที่ผ่านไปแต่ละช่องจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> เพื่อสุ่มบล็อก",
  str_skill_desc_3302291 = "Batia เริ่มต้นการต่อสู้ด้วย <link=\"30114\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง ช่องสีแดงที่ผ่านไปแต่ละช่องจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> เพื่อสุ่มบล็อก การพยายามสุ่มแต่ละครั้งจะเสียพลังงานเพิ่มเติม <color=#00F6FF>5</color> จุด จนกว่าจะใช้สกิลใช้งานของเธอครั้งถัดไป ล็อคบล็อกในคิวถัดไปเพื่อป้องกันไม่ให้สุ่ม ขณะที่ล็อคแต่ละการสุ่มจะเพิ่มพลังบล็อกปัจจุบัน สำหรับการเพิ่มพลังแต่ละครั้ง สกิลใช้งานจะสร้าง Dark Tile ที่ตำแหน่งสุ่มด้วย",
  str_skill_desc_3332291 = "Batia เริ่มต้นการต่อสู้ด้วย <link=\"30115\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง คิวถัดไปเริ่มต้นด้วยพลังงาน <color=#00F6FF>10</color> และทุกช่องสีแดงที่ผ่านไปจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> พลังงานสำหรับการสุ่มบล็อก การสุ่มแต่ละครั้งจะเสียพลังงานเพิ่มเติม <color=#00F6FF>5</color> จนกว่าจะใช้สกิลใช้งานของเธอครั้งถัดไป ล็อกบล็อกในคิวถัดไปเพื่อป้องกันการสุ่ม ขณะที่ล็อก การสุ่มแต่ละครั้งจะเพิ่มความสามารถของบล็อกปัจจุบัน สำหรับการเพิ่มความสามารถแต่ละครั้ง สกิลใช้งานจะสร้าง Dark Tile ที่ตำแหน่งสุ่ม",
  str_skill_desc_3362291 = "Batia เริ่มการต่อสู้ด้วย <link=\"30116\"><#FFAE07><u>คิวถัดไป</u></color></link> เลือก 1 ช่อง และพื้นที่ที่ตรงกับบล็อกที่แสดงในคิวถัดไปจะถูกเปลี่ยนเป็นช่องสีแดง คิวถัดไปเริ่มด้วยพลังงาน <color=#00F6FF>10</color> และแต่ละช่องสีแดงที่ผ่านไปจะให้พลังงาน <color=#00F6FF>1</color> ใช้พลังงาน <color=#00F6FF>5</color> พลังงานสำหรับการสุ่มบล็อก ล็อกบล็อกใน Next Queue เพื่อป้องกันไม่ให้สุ่ม ขณะที่ถูกล็อก การสุ่มแต่ละครั้งจะเพิ่มความสามารถของบล็อกปัจจุบัน สำหรับการเพิ่มความสามารถแต่ละครั้ง Active Skill จะสร้าง Dark Tile ที่ตำแหน่งสุ่ม",
  str_skill_passive_desc_4002291 = "ทีมทำให้เกิดสถานะ<color=#00F6FF>ลุกเพลิง</color> แทนการเผาไหม้ แต่ละสแต็กทำดาเมจ <color=#00F6FF>{1}</color> จาก ATK โดยเฉลี่ยของทีมต่อเป้าหมาย ยิ่ง HP ของเป้าหมายสูง ดาเมจที่ทำออกไปก็ยิ่งสูง สูงสุดเพิ่มเติม 100% สะสมได้สูงสุด 5 สแต็ก และรักษาสถานะนาน 2 รอบ ทำให้เกิดสถานะ<color=#00F6FF>ลุกเพลิง</color> 1 สแต็กให้กับเป้าหมายที่ใกล้ที่สุดสำหรับแต่ละ<link=\"30093\"><#FFAE07><u>ช่องสีดำ</u></color></link>ที่ผ่านไป",
  str_skill_upgrade_desc_16022913 = "เสริมพลังสกิลใช้งาน: เปลี่ยนสกิลใช้งานเป็น<color=#FFFF00>สกิลจู่โจมเปิดฉาก</color> ซึ่งพร้อมใช้ได้ทันทีเมื่อเริ่มต่อสู้ คิวถัดไปเริ่มด้วยพลังงาน 10 หน่วย (ใช้ได้สำหรับการเลื่อนขั้น II)",
  str_skill_upgrade_desc_16022916 = "เสริมพลังสกิลใช้งาน: ค่าพลังงานไม่เพิ่มขึ้นเมื่อทำการสุ่ม Next Queue (ใช้ได้สำหรับการเลื่อนขั้น II)",
  str_skill_name_28002414 = "กดขี่",
  str_skill_desc_28002414 = "ฟอร์เซคินใช้คาถาที่มีพลังแรงและผลักออโรเรียนให้ถอยหลัง",
  str_skill_name_28002415 = "เรียก",
  str_skill_desc_28002415 = "ฟอร์เซคินเรียกอิคลิพไซท์มาแบบสุ่มตำแหน่งในสนามรบ",
  str_skill_name_1003003 = "ล็อก",
  str_skill_desc_1003003 = "Shadowgeist แปลง 1 ช่องสุ่มใน 1 คลัสเตอร์รอบ ๆ เป็นช่องล็อกในแต่ละรอบ",
  str_skill_name_29102421 = "เผาไหม้",
  str_skill_desc_29102421 = "สร้างความเสียหายให้กับ Aurorians ที่อยู่ใน 4 คอลัมน์ข้างหน้าและเรียกเปลวไฟที่ตำแหน่งสุ่ม",
  str_skill_name_29102422 = "ราชันแห่งอัคคี",
  str_skill_desc_29102422 = "ปล่อยเปลวไฟที่ร้อนแรง ทำความเสียหายต่อทั้งสนาม และทำความเสียหายเพิ่มเติม 1 ครั้งกับเป้าหมายที่อยู่ในระยะ 3 แถวทั้งสองด้านของสนาม",
  str_skill_name_15017611 = "พายุออสตราลิส",
  str_skill_desc_15017611 = "สร้างความเสียหายหลายครั้งต่อ Aurorians ภายใน 3 กระจุกรอบ ตามจำนวนของ Australis Spear ที่เธอมี แต่ละครั้งของความเสียหายจะทำให้เป้าหมายได้รับ Australis Spear เพิ่ม 1 ถ้าเป้าหมายไม่สามารถถูกโจมตี จะทำให้เธอได้รับ Australis Spear 3 ชิ้นเพิ่มเติม",
  str_skill_name_15017612 = "Borealis รุ่งเรือง",
  str_skill_desc_15017612 = "ลบ Australis Spears ออกจากเป้าหมายภายใน 2 กระจุกรอบ. แต่ละ Australis Spear สร้างความเสียหาย 20%. ถ้าเป้าหมายไม่สามารถถูกโจมตี ทำให้ตนเองได้รับ 3 กอง Australis Spear.",
  str_skill_name_15020011 = "ความมืดมา",
  str_skill_desc_15020011 = "ทำดาเมจใส่ยูนิตศัตรูภายในวงรอบตัว 3 ชั้น",
  str_skill_name_15020012 = "บทกวีสู่ความลึก",
  str_skill_desc_15020012 = "รวบรวม Aurorians และทหารอิลลูมินาไปยังศูนย์กลางที่เกี่ยวข้องกับตำแหน่งของทั้งสอง",
  str_skill_name_547100101 = "การโจมตีปกติของไรน์ฮาร์ต",
  str_skill_desc_547100101 = "ไรน์ฮาร์ตเข้าใกล้ศัตรูและเริ่มโจมตี.",
  str_skill_name_547100102 = "แสงระเบิดเจิดจ้า",
  str_skill_desc_547100102 = "ไรน์ฮาร์ตสร้างความเสียหายหนักให้กับศัตรู.",
  str_skill_name_290980101 = "ความชั่วร้ายทะลวง",
  str_skill_name_290980102 = "Soulscorned พิพากษา",
  str_skill_name_290980103 = "กรีดร้องสายฟ้าแลบกระแส",
  str_skill_name_290980104 = "ลมหายใจมังกรรวมกัน",
  str_skill_desc_290980101 = "ถ้ามีศัตรูอยู่ในพื้นที่รูป X จะทำดาเมจให้กับพวกเขาและเรียกหน่วยรอบข้าง หากไม่เช่นนั้น จะเรียกหน่วยรอบข้างรอบตัวเอง",
  str_skill_desc_290980102 = "ถ้ามีศัตรูอยู่ในพื้นที่รูปบวก จะทำดาเมจให้กับพวกเขาและเรียกหน่วยรอบข้าง หากไม่เช่นนั้น จะเรียกหน่วยรอบข้างมาอยู่รอบ ๆ ตัวเอง",
  str_skill_desc_290980103 = "เรียกหน่วยรอบข้างรอบตัวเอง",
  str_skill_desc_290980104 = "สร้างความเสียหายแก่ศัตรูทั้งหมดในสนาม ผลักพวกเขาถอยหลังและเรียกหน่วยรอบ ๆ พวกเขา",
  str_skill_name_200510101 = "แสงที่ท้าทาย",
  str_skill_desc_200510101 = "พวกโจรสลัดชายแดนเข้าใกล้ศัตรูและโจมตี",
  str_skill_name_290520111 = "Forsaken: สายฟ้าแลบดุร้าย",
  str_skill_desc_290520111 = "ฟิเจอรัลด์เคลื่อนเข้าหา Aurorians และสร้างความเสียหายจำนวนมาก จากนั้นถอยห่าง",
  str_skill_name_290520112 = "Forsaken: การโจมตีของฟิเจอรัลด์",
  str_skill_desc_290520112 = "ฟิเจอรัลด์เคลื่อนที่ จากนั้นสร้างความเสียหายให้กับ Aurorians ทั้งหมดที่อยู่ในระยะ",
  str_skill_name_290940113 = "Forsaken: หอกไฟเงาที่ถูกทอดทิ้ง",
  str_skill_desc_290940113 = "ไอราสร้างความเสียหายเท่ากับ 40% ของ HP ปัจจุบันของ Aurorians, เพิ่ม HP สูงสุดของทีมตามความเสียหายที่ทำให้, และสร้าง Shadowfires ที่ชิ้นส่วนที่อยู่ที่สุดขอบของกระดานภายในระยะสูงสุดในพื้นที่ที่มีรูปแบบเป็นกากบาทที่ตรงกลางของ Aurorian.",
  str_skill_name_290940114 = "Forsaken: ลมหนาวที่ร้อนแรง",
  str_skill_desc_290940114 = "ไอราทำดาเมจใส่ออโรเรียนที่อยู่ในวงรอบตัวเอง 2 ชั้น",
  str_skill_name_290940115 = "Forsaken: ดาวตกพิโรธ",
  str_skill_desc_290940115 = "ไอราเรียกหินดาวตกมาโจมตีตำแหน่งที่ออโรเรียนอยู่ในรอบก่อนหน้า สร้างความเสียหายร้ายแรงและทำลายแผ่นกระเบื้อง ทิ้งแผ่นกระเบื้องแตก 4 แผ่นในรูปกากบาท",
  str_skill_upgrade_refine_desc_17010711 = "เสริมพลังสกิลใช้งาน: เพิ่มดาเมจคอมโบต่อเนื่อง <color=#00F6FF>25%</color> เมื่อได้รับการเพิ่มประสิทธิภาพ.",
  str_skill_upgrade_refine_desc_17010712 = "เสริมพลังสกิลอุปกรณ์: เมื่อเริ่มต้นแต่ละรอบ จะได้รับ Vis 1 หน่วย สำหรับศัตรูแต่ละตัวที่อยู่ใน<color=#00F6FF>วงรอบตัว 1 ชั้น</color>",
  str_skill_upgrade_refine_desc_17010713 = "เสริมพลังสกิลอุปกรณ์: ได้รับ Vis 5 หน่วยที่<color=#00F6FF>จบรอบ</color> (ได้รับ Vis เพิ่ม 1 หน่วยทุกครั้งที่เสีย HP <color=#00F6FF>15%</color>)",
  str_skill_desc_346107 = "ใช้ Vis <color=#00F6FF>10</color> หน่วยเพื่อเข้าสู่สถานะเพิ่มพลังในรอบนี้: การโจมตีปกติสามารถเกิดขึ้นในแนวทแยง และเพิ่มดาเมจของการโจมตีปกติ/คอมโบต่อเนื่อง <color=#00F6FF>20%/25%</color> ตามลำดับ (สามารถสะสมได้) ได้รับ Vis 2 หน่วยสำหรับศัตรูที่ถูกสังหารในขณะที่เพิ่มพลัง",
  str_skill_passive_desc_456107 = "ได้รับ Vis 10 หน่วยเมื่อเริ่มการต่อสู้ เมื่อเริ่มต้นแต่ละรอบ จะได้รับ Vis <color=#00F6FF>1</color> หน่วยสำหรับศัตรูทุกคนที่อยู่ภายใน <color=#00F6FF>1 กลุ่มรอบตัว</color> เมื่อจบรอบโดยไม่ได้อยู่ในสถานะเพิ่มพลัง จะได้รับ Vis <color=#00F6FF>5</color> หน่วยและ Vis เพิ่มเติม 1 หน่วยสำหรับทุก 20% ของ HP ที่สูญเสีย",
  str_skill_passive_desc_466107 = "ได้รับ Vis 10 หน่วยเมื่อเริ่มการต่อสู้ เมื่อเริ่มต้นแต่ละรอบ จะได้รับ Vis <color=#00F6FF>1</color> หน่วยสำหรับศัตรูทุกคนที่อยู่ภายใน <color=#00F6FF>1 กลุ่มรอบตัว</color> ได้รับ Vis <color=#00F6FF>5</color> หน่วยเมื่อจบรอบ และได้รับ Vis เพิ่มเติม 1 หน่วยสำหรับทุก 15% ของ HP ที่สูญเสีย",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF>สกิลใช้งานรูปแบบ I</color>: ใช้ Vis <color=#00F6FF>15</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>480%</color> ใส่ช่องที่เลือก การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐาน <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ",
  str_skill_upgrade_refine_desc_17010812 = "เสริมพลังสกิลใช้งาน: การร่ายทุกครั้งเพิ่มดาเมจสุดท้ายของสกิลใช้งาน <color=#00F6FF>3%</color>",
  str_skill_upgrade_refine_desc_17010813 = "เสริมพลังสกิลใช้งาน: ทำดาเมจ <color=#00F6FF>300%</color> ต่อเป้าหมายที่มี HP น้อยกว่า <color=#00F6FF>10%</color>",
  str_skill_name_366108 = "พายุดาวตก",
  str_skill_name_33610801 = "พายุดาวตก รุ่น I",
  str_skill_name_36610801 = "พายุดาวตก รุ่น I",
  str_skill_desc_33610801 = "ใช้ Vis <color=#00F6FF>15</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>480%</color> ใส่ช่องที่เลือก การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐาน <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ",
  str_skill_desc_356108 = "ใช้ Vis <color=#00F6FF>10</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>240%</color> กับช่อง 1 ช่องที่เลือก และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> 50% กับศัตรูรอบ ๆ ในระยะ <color=#00F6FF>4 ช่องรูปบวก</color> การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐานและดาเมจสุดท้ายของสกิลที่ใช้งานอยู่ <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ",
  str_skill_desc_35610801 = "ใช้ Vis <color=#00F6FF>15</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>480%</color> ใส่ช่องที่เลือก การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐานและดาเมจสุดท้ายของสกิลที่ใช้งาน <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ",
  str_skill_desc_366108 = "ใช้ Vis <color=#00F6FF>10</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>240%</color> กับช่อง 1 ช่องที่เลือก และทำดาเมจ<link=\"30015\"><#FFAE07><u>กระจาย</u></color></link> 50% กับศัตรูรอบ ๆ ในระยะ <color=#00F6FF>4 ช่องรูปบวก</color> การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐานและดาเมจสุดท้ายของสกิลที่ใช้งานอยู่ <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ ทำดาเมจ <color=#00F6FF>300%</color> กับเป้าหมายที่มี HP น้อยกว่า <color=#00F6FF>10%</color>",
  str_skill_desc_36610801 = "ใช้ Vis <color=#00F6FF>15</color> หน่วยเพื่อทำดาเมจ <color=#00F6FF>480%</color> กับช่องที่เลือก การร่ายทุกครั้งจะเพิ่ม ATK พื้นฐานและดาเมจสุดท้ายของสกิลที่ใช้งาน <color=#00F6FF>3%</color> สามารถร่ายได้หลายครั้งในแต่ละรอบ ทำดาเมจ <color=#00F6FF>300%</color> กับเป้าหมายที่มี HP น้อยกว่า <color=#00F6FF>10%</color>",
  str_skill_upgrade_refine_desc_17010911 = "เสริมพลังสกิลใช้งาน: <color=#00F6FF>เลือก 1 ช่องในสนาม</color> และการโจมตีสามารถถึง <color=#00F6FF>เป้าหมายที่อยู่ข้างหลังทีม</color>",
  str_skill_upgrade_refine_desc_17010912 = "เสริมพลังสกิลอุปกรณ์: ได้รับ Vis <color=#00F6FF>1</color> หน่วยสำหรับการโจมตีปกติ <color=#00F6FF>2</color> ครั้งแรกในแต่ละรอบ และเพิ่มดาเมจที่เกิดจากการโจมตีเหล่านี้ <color=#00F6FF>100%</color>",
  str_skill_upgrade_refine_desc_17010913 = "สกิลใช้งานใหม่: ใช้ Vis <color=#00F6FF>10</color> หน่วยเพื่อเพิ่มเป้าหมายของคอมโบต่อเนื่องในรอบนี้ <color=#00F6FF>1</color> ตัว (สามารถสแต็กได้)",
  str_skill_name_340109 = "ออกล่าใต้แสงจันทร์",
  str_skill_desc_340109 = "ใช้ Vis <color=#00F6FF>10</color> หน่วย จากนั้นเผาผลาญ Vis ที่เหลือทั้งหมดเพื่อเลือกช่อง 1 ช่องและทำดาเมจ <color=#00F6FF><color=#00F6FF>150%</color></color> กับศัตรูทุกตัวบนเส้นทางระหว่าง Aurorian และช่องที่เลือก ทั้งสองทิศทาง รวมถึงศัตรูบนช่องข้างเคียงด้วย ดาเมจสุดท้ายจะเพิ่มขึ้น <color=#00F6FF>8%</color> ต่อค่า Vis 1 หน่วยที่เผาผลาญ",
  str_skill_passive_desc_453109 = "ได้รับ Vis <color=#00F6FF>5</color> หน่วยเมื่อเริ่มต้นแต่ละรอบ และได้รับ Vis <color=#00F6FF>1</color> หน่วยสำหรับการโจมตีปกติ <color=#00F6FF>2</color> ครั้งแรกในแต่ละรอบ พร้อมเพิ่มดาเมจของการโจมตีปกติครั้งแรกนี้ <color=#00F6FF>100%</color>",
  str_skill_name_360109 = "ไล่ล่าแชโดว์ในหมู่ต้นไม้",
  str_skill_desc_360109 = "ใช้ Vis <color=#00F6FF>10</color> หน่วยเพื่อเพิ่มจำนวนเป้าหมายสำหรับคอมโบต่อเนื่องในรอบนี้ <color=#00F6FF>1</color> ตัว (สามารถสะสมได้)",
  str_skill_upgrade_refine_desc_17011011 = "การเพิ่มประสิทธิภาพทักษะอุปกรณ์: การโจมตีปกติมีโอกาส <color=#00F6FF>35%</color> ที่จะโจมตีศัตรูที่อยู่ไกลที่สุดด้วยสายฟ้า",
  str_skill_upgrade_refine_desc_17011012 = "เสริมพลังสกิลอุปกรณ์: ได้รับ Vis 1 หน่วยสำหรับแต่ละการโจมตีด้วยสายฟ้าเมื่อมี Vis น้อยกว่า 5 หน่วย",
  str_skill_upgrade_refine_desc_17011013 = "เสริมพลังสกิลใช้งาน: ได้รับตราเรเควียม 1 สแต็กสำหรับทุกการปล่อยฟ้าผ่า และตราทั้งหมดจะถูกล้างเมื่อสกิลใช้งานถูกปล่อย การเพิ่มปัจจัยความเสียหายสำหรับสกิลใช้งาน 10% สำหรับแต่ละสแต็กของตราเรเควียมที่ถูกล้าง",
  str_skill_passive_desc_443110 = "ได้รับ Vis <color=#00F6FF>5</color> หน่วยเมื่อเริ่มต้นแต่ละรอบ และได้รับ Vis เพิ่มเติม<color=#00F6FF>2</color> หน่วยเมื่อสังหารเป้าหมายด้วยสกิลใช้งาน การโจมตีปกติมีโอกาส <color=#00F6FF>35%</color> ที่จะปล่อยสายฟ้าจู่โจมศัตรูที่อยู่ไกลที่สุด",
  str_skill_passive_desc_453110 = "ได้รับ Vis <color=#00F6FF>5</color> หน่วยเมื่อเริ่มต้นแต่ละรอบ และได้รับ Vis เพิ่มเติม<color=#00F6FF>2</color> หน่วยเมื่อสังหารเป้าหมายด้วยสกิลใช้งาน การโจมตีปกติมีโอกาส <color=#00F6FF>35%</color> ที่จะปล่อยสายฟ้าจู่โจมศัตรูที่อยู่ไกลที่สุด ได้รับ Vis 1 หน่วยสำหรับการปล่อยสายฟ้าแต่ละครั้งเมื่อมี Vis น้อยกว่า 5 หน่วย",
  str_skill_desc_366110 = "ใช้ Vis <color=#00F6FF>10</color> หน่วย จากนั้นเผาผลาญ Vis ที่เหลือทั้งหมดและ <link=\"30117\"><#FFAE07><u>เครื่องหมาย Requiem</u></color></link> เพื่อทำดาเมจ <color=#00F6FF>150%</color> กับศัตรูทุกตัว ดาเมจจะเพิ่มขึ้น <color=#00F6FF>15%</color> ต่อค่า Vis 1 หน่วยที่เผาผลาญ และไม่สนใจค่า DEF <color=#00F6FF>1%</color> การทำดาเมจจากสกิลใช้งานจะเพิ่มขึ้น <color=#00F6FF>10%</color> สำหรับแต่ละเครื่องหมาย Requiem ที่เผาผลาญ",
  str_skill_upgrade_desc_16023013 = "การเสริมทักษะอุปกรณ์: เมื่อสุขภาพจิตต่ำหรือสูงกว่า 50, แผ่นที่ไม่ใช่สีแดงที่ใกล้ทีมที่สุดจะถูกเปลี่ยนเป็น <color=#00F6FF>แผ่นสีแดงมืด</color>.",
  str_skill_upgrade_desc_16023014 = "เสริมพลังสกิลใช้งานและทักษะอุปกรณ์: เมื่อทำความเสียหาย จะรวมเพิ่มเติม <color=#00F6FF>4,000</color> HP ที่ทีมสูญเสีย.",
  str_skill_upgrade_desc_16023015 = "การเสริมทักษะอุปกรณ์: วิกตอเรีย: ความเสียหายจาก Elegy ต่อศัตรูที่มี Lord's Covenant จะเพิ่มขึ้นเมื่อ HP ของทีมลดลง สูงสุดที่ <color=#00F6FF>15%</color> เมื่อ HP ของทีมอยู่ที่ 50%",
  str_skill_name_2002301 = "เรือนจำสีแดงฉาน",
  str_skill_name_2002302 = "เรือนจำสีแดงฉาน",
  str_skill_name_2002303 = "เรือนจำสีแดงฉาน",
