  str_skill_desc_2002332 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color>",
  str_skill_desc_2002333 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ใน<color=#00F6FF>วงรอบตัว 2 ชั้น</color>",
  str_skill_desc_2032332 = "ทำดาเมจ <color=#00F6FF>{1}%</color> ในระยะ <color=#00F6FF>12 ช่องรูปข้าวหลามตัด</color> และสุ่มสร้าง <color=#00F6FF>1</color> ช่องมืดภายในพื้นที่ที่ได้รับผลกระทบ",
